    # ─────────────────────────────────────────────────────────────────────
    #  Sprite loading (cached)
    # ─────────────────────────────────────────────────────────────────────
    def _get_sprite(self, path: str, size_px: int) -> pygame.Surface | None:
        key = (path, size_px)
        if key not in self.sprites:
            if path and os.path.exists(path):
                try:
                    raw = pygame.image.load(path).convert_alpha()
                    self.sprites[key] = pygame.transform.scale(
                        raw, (size_px, size_px))
                except Exception:
                    self.sprites[key] = None
            else:
                self.sprites[key] = None
        return self.sprites[key]

    def _get_caster_color(self, caster_idx: int) -> tuple[int, int, int]:
        """Generate a distinctive color for a caster based on their agent index."""
        # Use different colors for different casters to visually link them to their targets
        colors = [
            (255, 100, 100),  # Red
            (100, 100, 255),  # Blue
            (100, 255, 100),  # Green
            (255, 255, 100),  # Yellow
            (255, 100, 255),  # Magenta
            (100, 255, 255),  # Cyan
            (255, 200, 100),  # Orange
            (200, 100, 255),  # Purple
        ]
        return colors[caster_idx % len(colors)]

    def _get_mob_sprite_path(self, mob_name: str) -> str:
        """Determine sprite path for a mob: use specific sprite if it exists, otherwise use first letter."""
        specific_path = os.path.join(self.sprites_dir, f"{mob_name}.png")
        if os.path.exists(specific_path):
            return specific_path
        return os.path.join(self.sprites_dir, f"{mob_name[0].upper()}.png")

    def _weapon_from_slot_value(self, val):
        """Build an rpg.Weapon from a bestiary weapon-slot value: a catalog
        name string (resolved via weapons.json) or a synthesized weapon dict.
        Empty/unknown -> a blank rpg.Weapon()."""
        if isinstance(val, dict):
            return _dict_to_weapon(val)
        if isinstance(val, str) and val and val in self.weapon_name_to_dict:
            return _dict_to_weapon(self.weapon_name_to_dict[val])
        return rpg.Weapon()

    @staticmethod
    def _has_real_weapons(weapons) -> bool:
        """True if any slot holds a real weapon. 'Unarmed'/'MonkUnarmed' is the
        default empty-slot sentinel (weapon.hpp), so it counts as no weapon."""
        return any(w.name and w.name not in ("Unarmed", "MonkUnarmed")
                   for w in weapons)

    def _auto_weapons_from_mob_stats(self, mob_record: dict) -> list:
        """Variable-length rpg.Weapon list built from the bestiary record's
        pre-synthesized `weapons` field. Accepts BOTH the new flat "Attack N"
        list AND the legacy {main_hand,off_hand,ranged} dict. Padded to >=3 so
        callers can still assign main/off/ranged positionally; extra attacks
        (index 3+) follow. Empty slots are blank weapons."""
        wfield = mob_record.get("weapons", {})
        if isinstance(wfield, list):
            weapons = [self._weapon_from_slot_value(v) for v in wfield]
        else:
            weapons = [self._weapon_from_slot_value(wfield.get(slot, ""))
                       for slot in ("main_hand", "off_hand", "ranged")]
        while len(weapons) < 3:
            weapons.append(rpg.Weapon())
        return weapons

    def _size_category_to_grid_size(self, size_category: str) -> int:
        """Convert D&D size category to grid size (cells)."""
        size_map = {
            "Small": 1,
            "Tiny": 1,
            "Medium": 1,
            "Large": 2,
            "Huge": 3,
            "Gargantuan": 4,
        }
        return size_map.get(size_category, 1)

    def _on_mob_selected(self, mob_name: str):
        """Callback when a mob is selected from the dialog."""
        # Load stats from JSON
        if mob_name in self.mob_stats_json:
            self.selected_mob_stats = self.mob_stats_json[mob_name]
            # Set size based on mob size category
            size_category = self.selected_mob_stats.get("size", "Medium")
            self.current_mob_grid_size = self._size_category_to_grid_size(size_category)
        else:
            self.selected_mob_stats = None
            self.current_mob_grid_size = 1

        # Enter placement mode immediately
        cfg = rpg.AgentConfig()
        cfg.name        = mob_name
        cfg.sprite_path = self._get_mob_sprite_path(mob_name)
        cfg.size        = self.current_mob_grid_size
        cfg.start_col   = 0
        cfg.start_row   = 0
        self.placement_mode_active = True
        self.placement_config = cfg
        self.placement_cell = None
        self.placement_valid = False

    def _on_pc_class_selected(self, class_name: str):
        """Callback when a PC class is selected."""
        self.selected_mob_stats = None  # No mob stats for PCs
        self.current_mob_grid_size = 1

        # Setup PC config
        cfg = rpg.AgentConfig()
        cfg.name        = f"{class_name} 1"
        cfg.sprite_path = ""  # PCs don't have sprites initially
        cfg.size        = 1
        cfg.start_col   = 0
        cfg.start_row   = 0

        # Create default PC stats (standard array: 15, 14, 13, 12, 10, 8)
        stats = rpg.Stats()
        stats.str        = 15
        stats.dex        = 14
        stats.con        = 13
        stats.intel      = 12
        stats.wis        = 10
        stats.cha        = 8
        stats.hp_max     = 8  # Will be updated based on class
        stats.hp_cur     = 8
        stats.base_ac    = 10
        stats.speed_walk = 30
        stats.prof_bonus = 2
        stats.num_attacks = 1
        # Set class and level (this also sets can_cast_spell and spell slots)
        stats.set_class_level(getattr(rpg.CharacterClass, class_name), 1)
        # Initialize class resources (Rage, Focus Points, etc.)
        stats.initialize_class_resources(getattr(rpg.CharacterClass, class_name), 1)

        # Store for use in placement handler
        self._pending_pc_class = class_name
        self._pending_pc_stats = stats

        self.placement_mode_active = False
        self.placement_config = cfg
        self.placement_cell = None
        self.placement_valid = False

        # Create TextInput for name editing in the panel
        px, W, _, _, _, _ = self._panel_layout()
        self._pc_name_input = TextInput(pygame.Rect(px, 70, W, 28), placeholder=cfg.name, font=self.font_md)
        self._pc_name_input.text = cfg.name
        self._pc_name_input.active = True

    def _mob_stats_to_d_d_stats(self, mob_record: dict):
        """Build rpg.Stats from an engine-ready bestiary record.

        The record's `stats` block is already in agent_loader.dict_to_stats
        shape (ability scores, speeds, save profs, resist/immune/vuln lists,
        is_npc), so this just loads it and applies the damage multipliers."""
        sd = mob_record.get("stats", {})
        # Add legendary data from meta.legendary to the stats dict for dict_to_stats to consume
        meta = mob_record.get("meta", {})
        if "legendary" in meta:
            sd["legendary"] = meta["legendary"]
        stats = dict_to_stats(sd)
        apply_damage_multipliers(stats, sd)
        # Creature type from the stat block's meta.type (e.g. "Fiend (Devil)", "Undead", "Fey").
        # Drives the Magic Circle / Hallow movement wards (D4) and Divine Smite's +1d8 vs
        # Fiend/Undead. Substring match handles the parenthetical subtypes in the bestiary.
        mtype = str(meta.get("type") or "").lower()
        for _needle, _flag in (("aberration", "is_aberration"), ("celestial", "is_celestial"),
                               ("elemental", "is_elemental"), ("fey", "is_fey"),
                               ("fiend", "is_fiend"), ("undead", "is_undead")):
            if _needle in mtype and hasattr(stats, _flag):
                setattr(stats, _flag, True)
        # Monsters whose bonus action grants Dash/Disengage (e.g. the Vampire
        # Spawn's "Deathless Agility") reuse the Cunning Action machinery, which
        # is what surfaces the bonus-action Dash/Disengage buttons in the GUI.
        ba = str(meta.get("bonus_action") or "").lower()
        if "dash" in ba or "disengage" in ba:
            stats.has_cunning_action = True
        return stats

    def _load_npc_spells_from_record(self, agent_idx: int, mob_record: dict):
        """Auto-populate an NPC's innate spells from its bestiary record.

        Mirrors the saved-agent spell-restore path: the record's `spell_indices`
        (canonical catalog names) become Spell objects via spells.json, then
        `npc_spell_groups` ({uses/day: [names]}) sets each spell's uses_max via
        init_npc_spell_groups. No-op for non-casters."""
        spell_names = mob_record.get("spell_indices", [])
        if not spell_names:
            return
        cpp_spells = []
        for spell_name in spell_names:
            idx = self.spell_name_to_idx.get(spell_name)
            if idx is None:
                print(f"WARNING: NPC spell '{spell_name}' not in catalog "
                      f"for {mob_record.get('name', agent_idx)}")
                continue
            spell_dict = self.all_spells[idx]
            self._spell_metadata[(agent_idx, len(cpp_spells))] = {
                "terrain_effect": spell_dict.get("terrain_effect"),
                "hatch_pattern": spell_dict.get("hatch_pattern"),
                "terrain_color": spell_dict.get("terrain_color"),
            }
            cpp_spells.append(_dict_to_spell(spell_dict))

        # Breath weapons / recharge actions: a per-monster {spell_name: recharge_min}
        # map sets the recharge die threshold on the matching catalog Spell (the
        # generic Breath<…> entries ship with recharge_min=0; the actual 5-6/6/4
        # value is monster-specific). uses_max=1 so it's a single charge that the
        # beginTurn d6 roll refills. See NPC_USES_RECHARGE_PLAN.md.
        recharge_map = mob_record.get("npc_spell_recharge", {})
        if recharge_map:
            for j, sp in enumerate(cpp_spells):
                rmin = recharge_map.get(sp.name)
                if rmin:
                    sp.recharge_min   = int(rmin)
                    sp.uses_max       = max(1, sp.uses_max)
                    sp.uses_remaining = sp.uses_max
                    sp.expended       = False
        self.combat.set_agent_spells(self.bm, agent_idx, cpp_spells)

        npc_spell_groups = mob_record.get("npc_spell_groups", {})
        if npc_spell_groups or recharge_map:
            groups_dict = {int(k): v for k, v in npc_spell_groups.items()}
            if groups_dict:
                self.combat.init_npc_spell_groups(self.bm, agent_idx, groups_dict)
            self._agent_meta[agent_idx] = {
                "is_npc": True, "npc_spell_groups": npc_spell_groups,
                "npc_spell_recharge": recharge_map}

    # ─────────────────────────────────────────────────────────────────────
    #  Grid coordinate helpers
    # ─────────────────────────────────────────────────────────────────────
    def _screen_to_cell(self, sx, sy):
        """Convert a screen pixel position to a grid Cell, or None if outside."""
        s     = self.map_scale
        raw_v = self.bm.v_line_positions
        raw_h = self.bm.h_line_positions
        if not raw_v or not raw_h:
            return None
        # Remove pan offset, then unscale back to original image space
        ix = (sx - self.pan_x) / s
        iy = (sy - self.pan_y) / s
        # Binary-search which column/row we're in
        import bisect
        c = bisect.bisect_right(raw_v, ix) - 1
        r = bisect.bisect_right(raw_h, iy) - 1
        if 0 <= c < self.bm.grid_cols and 0 <= r < self.bm.grid_rows:
            return rpg.Cell(c, r)
        return None

    def _pixel_to_cell(self, ix, iy):
        """Convert image pixel coordinates to a grid Cell, or None if outside.
        Unlike _screen_to_cell, this works with raw image pixels (no pan/scale adjustment)."""
        raw_v = self.bm.v_line_positions
        raw_h = self.bm.h_line_positions
        if not raw_v or not raw_h:
            return None
        # Binary-search which column/row we're in
        import bisect
        c = bisect.bisect_right(raw_v, ix) - 1
        r = bisect.bisect_right(raw_h, iy) - 1
        if 0 <= c < self.bm.grid_cols and 0 <= r < self.bm.grid_rows:
            return rpg.Cell(c, r)
        return None

    def _cell_to_screen(self, col, row):
        """Return top-left screen pixel of a grid cell."""
        s     = self.map_scale
        raw_v = self.bm.v_line_positions
        raw_h = self.bm.h_line_positions
        return int(raw_v[col] * s + self.pan_x), int(raw_h[row] * s + self.pan_y)

    def _cell_to_screen_f(self, col, row):
        """_cell_to_screen for FRACTIONAL grid coordinates (NPC-turn playback: a token
        mid-slide between two cells). Interpolates between adjacent grid-line positions."""
        s     = self.map_scale
        raw_v = self.bm.v_line_positions
        raw_h = self.bm.h_line_positions

        def lerp(lines, v):
            i = max(0, min(int(v), len(lines) - 1))
            f = v - i
            if f <= 0 or i + 1 >= len(lines):
                return lines[i]
            return lines[i] + f * (lines[i + 1] - lines[i])

        return int(lerp(raw_v, col) * s + self.pan_x), int(lerp(raw_h, row) * s + self.pan_y)

    def _agent_at(self, cell):
        """Return index of the placed agent whose footprint contains cell, or -1.

        A truly dead corpse (conditions.dead) or a tombstoned agent is skipped so it can
        never be clicked/targeted — a live creature now shares its square, and that's the
        one we want. A downed-but-alive creature (hp 0, making death saves) is NOT skipped,
        so it can still be selected to be healed."""
        for i, pt in enumerate(self.bm.placed_agents):
            if pt.removed_from_play or pt.conditions.dead:
                continue
            oc, or_ = pt.origin.col, pt.origin.row
            if oc <= cell.col < oc + pt.size and or_ <= cell.row < or_ + pt.size:
                return i
        return -1

    def _corpse_at(self, cell):
        """Return the index of a true-dead corpse (conditions.dead) whose footprint contains
        cell, or -1. The mirror image of _agent_at, which deliberately skips corpses: revive /
        raise spells (revives_dead) select a body the normal click can't reach. A tombstoned
        (removed_from_play) corpse is still skipped — it's gone from the board."""
        for i, pt in enumerate(self.bm.placed_agents):
            if pt.removed_from_play or not pt.conditions.dead:
                continue
            oc, or_ = pt.origin.col, pt.origin.row
            if oc <= cell.col < oc + pt.size and or_ <= cell.row < or_ + pt.size:
                return i
        return -1

    def _can_place(self, cell, size, exclude_idx=-1):
        """Return True if a size×size agent can be placed with top-left at cell.
        Rule lives in helpers.can_place_agent (shared with the summon preview + tests)."""
        return can_place_agent(self.bm, cell, size, exclude_idx)

    # ─────────────────────────────────────────────────────────────────────
    #  Save / Load
    # ─────────────────────────────────────────────────────────────────────
    # ── Save / load callbacks called by the file browser ─────────────────────
    def _set_encounter_base(self, agents_path: str):
        """Point all per-encounter sidecar files at the same base name as the chosen
        agents file, so one map PNG can host many encounters.

        Given '<dir>/<base>_agents.json' (or '<dir>/<base>.json' if the user typed a
        plain name), the sidecars become '<dir>/<base>_terrain.json',
        '<base>_effects.json' and '<base>_lighting.json'.
        """
        self._save_path = agents_path
        d  = os.path.dirname(agents_path)
        fn = os.path.basename(agents_path)
        if fn.endswith("_agents.json"):
            base = fn[:-len("_agents.json")]
        else:
            base = os.path.splitext(fn)[0]
        self._terrain_path  = os.path.join(d, base + "_terrain.json")
        self._effects_path  = os.path.join(d, base + "_effects.json")
        self._lighting_path = os.path.join(d, base + "_lighting.json")

    def _on_save_path_chosen(self, path: str):
        # Capture the previous sidecar locations so lighting/effects (which have no GUI
        # re-serialization path) can be carried forward to the new encounter base.
        old_lighting = self._lighting_path
        old_effects  = self._effects_path
        self._set_encounter_base(path)
        self._save_agents(path)
        self._save_terrain()        # writes self._terrain_path (now at the new base)
        # Lighting & effects travel with the encounter: copy the previous files to the
        # new base if they exist and we aren't overwriting an existing encounter's scene.
        for old, new in ((old_lighting, self._lighting_path),
                         (old_effects,  self._effects_path)):
            if old != new and os.path.exists(old) and not os.path.exists(new):
                try:
                    shutil.copyfile(old, new)
                except Exception as e:
                    print(f"Warning: could not carry forward {os.path.basename(old)}: {e}")

    def _on_load_path_chosen(self, path: str):
        # The Load browser shows every .json, so the user can pick a sidecar
        # (terrain/lighting/effects) by mistake. Those have no "agents" key — refuse
        # them rather than wiping the current scene with an empty agent list.
        try:
            with open(path) as f:
                if "agents" not in json.load(f):
                    self._flash_status(f"Not an encounter file: {os.path.basename(path)}")
                    return
        except Exception as e:
            self._flash_status(f"Could not read {os.path.basename(path)}: {e}")
            return
        self._set_encounter_base(path)
        self._load_agents(path)
        # Re-load the rest of the scene from the new base (terrain resets even if the
        # new encounter has none of these files, so a stale scene doesn't bleed through).
        self._load_terrain()
        self._load_lighting()
        self._load_spell_effects()

    # ─────────────────────────────────────────────────────────────────────
    #  Multi-map dungeons — active-map switching & paging (Phase 3)
    #  FLOORS_IMPLEMENTATION_PLAN.md. The engine simulates one BattleMap at a
    #  time; a "page" is one PNG placed on a shared global (X, Y, Z) grid.
    # ─────────────────────────────────────────────────────────────────────
    def _apply_page_origin(self, page: MapPage):
        """Stamp the engine map's global placement from ``page`` (Phase 1 fields).
        Defensive: skips silently if the extension predates the origin/z_level
        bindings so the app still runs on an un-rebuilt engine."""
        try:
            self.bm.origin_col = int(page.gx)
            self.bm.origin_row = int(page.gy)
            self.bm.z_level    = int(page.z)
        except AttributeError:
            pass  # engine not yet rebuilt with Phase 1 bindings — global coords stay 0

    def _switch_to_page(self, page: MapPage, drop_cell=None, carry=None, force=False):
        """Save the current scene, make ``page`` the active map, and reload its scene.

        - ``drop_cell``  : (col,row) on the target where carried agents land (else a
                           free spot near the top-left is chosen).
        - ``carry``      : list of agent indices on the CURRENT page to move onto the
                           target (a portal crossing). They are removed from the source
                           encounter and injected onto the target (incremental spawn,
                           never apply_agent_configs — see [[agent_dual_list_gotcha]]).
        - ``force``      : bypass the out-of-combat guard (used for the initial load).

        Returns True on success. Cross-page switching is out-of-combat only for the
        MVP (see Known Limitations); in combat it refuses with a flash unless forced.
        """
        if self.combat_active and not force:
            self._flash_status("Finish combat before changing maps.")
            return False

        already_here = (self.dungeon_page is not None and page.id == self.dungeon_page.id)

        # Manifest paths may be relative (portability); resolve against the manifest's
        # folder (where its PNGs and encounters live) so the engine gets valid paths.
        base_dir = self._dungeon_dir()

        def _resolve(p):
            return p if (not p or os.path.isabs(p)) else os.path.join(base_dir, p)

        # A page whose PNG has been moved/renamed would take the app down inside
        # _load_map_png — refuse the switch (nothing has changed yet) and say so.
        if not already_here and not os.path.exists(_resolve(page.png)):
            self._flash_status(f"Page '{page.id}': map image not found ({page.png})")
            return False

        # ── 1. Serialize carried agents, then persist the current scene ────────
        carried_records = self._read_agent_records(carry) if carry else []
        if self.dungeon_page is not None and not already_here:
            # Save the source scene WITHOUT the carried agents — they have left it.
            self._save_agents(exclude_indices=set(carry) if carry else None)
            self._save_terrain()
            # Lighting / effects have no GUI re-serializer; they were written when
            # last edited and travel with their encounter base, so nothing to do.

        # ── 2. Swap the PNG + engine map (skip if we're re-entering the same page) ─
        if not already_here:
            self._load_map_png(_resolve(page.png))
        self._apply_page_origin(page)

        # ── 3. Re-point the sidecars and reload the target scene ───────────────
        self._set_encounter_base(_resolve(page.encounter_base))
        self._load_terrain()
        self._load_lighting()
        self._load_spell_effects()
        self._load_agents()

        self.dungeon_page = page

        # ── 4. Inject carried agents onto the target (incremental) ─────────────
        if carried_records:
            self._inject_carried_agents(carried_records, drop_cell)

        self._mark_fog_dirty()
        return True

    def _read_agent_records(self, indices):
        """Return full serialized agent records (the same shape ``_save_agents``
        writes) for ``indices`` on the CURRENT engine map, by round-tripping through a
        temporary encounter file. Reusing the canonical serializer keeps carried agents
        lossless (stats/weapons/spells/armor) without duplicating its logic."""
        if not indices:
            return []
        want = set(indices)
        all_idx = set(range(len(self.bm.placed_agents)))
        tmp = os.path.join(self._map_dir, f".carry_{os.getpid()}.json")
        try:
            self._save_agents(tmp, exclude_indices=(all_idx - want))
            with open(tmp) as f:
                doc = json.load(f)
        except Exception as e:                       # noqa: BLE001 — carry is best-effort
            print(f"Warning: could not serialize carried agents: {e}")
            return []
        finally:
            try:
                os.remove(tmp)
            except OSError:
                pass
        return doc.get("agents", [])

    def _inject_carried_agents(self, records, drop_cell):
        """Persist ``records`` onto the freshly loaded target page and reload so the
        carried party appears there. Agents are repositioned to free cells at/around
        ``drop_cell`` (or the top-left) so they don't collide with the target's own
        residents. This writes them into the target's encounter file — after a crossing
        the party belongs to that page."""
        if not records:
            return
        try:
            with open(self._save_path) as f:
                doc = json.load(f)
        except (OSError, json.JSONDecodeError):
            doc = {"agents": [], "map_items": []}
        agents = doc.setdefault("agents", [])
        occupied = {(a.get("col"), a.get("row")) for a in agents}
        cols, rows = self.bm.grid_cols, self.bm.grid_rows
        start_c, start_r = (drop_cell if drop_cell is not None else (0, 0))

        def _free_spot():
            # Spiral-ish scan outward from the drop cell for the first open cell.
            for radius in range(0, max(cols, rows) + 1):
                for r in range(max(0, start_r - radius), min(rows, start_r + radius + 1)):
                    for c in range(max(0, start_c - radius), min(cols, start_c + radius + 1)):
                        if (c, r) not in occupied:
                            return c, r
            return start_c, start_r

        for rec in records:
            c, r = _free_spot()
            rec["col"], rec["row"] = c, r
            occupied.add((c, r))
            agents.append(rec)
        doc.setdefault("map_items", [])
        with open(self._save_path, "w") as f:
            json.dump(doc, f, indent=2)
        self._load_agents()

    def _page_step(self, direction: str):
        """Page to the neighbouring same-floor map (view switch, no carry)."""
        if self.dungeon is None or self.dungeon_page is None:
            return
        nxt = self.dungeon.neighbor(self.dungeon_page, direction)
        if nxt is None:
            self._flash_status(f"No map to the {direction}.")
            return
        if self._switch_to_page(nxt):
            self._flash_status(f"Map: {nxt.id}")

    def _floor_step(self, delta: int):
        """Change floors (Z ± delta), landing on the page at the party's current
        global (X, Y) if one exists there, else the first page on that floor."""
        if self.dungeon is None or self.dungeon_page is None:
            return
        cur = self.dungeon_page
        target_z = cur.z + delta
        if target_z not in self.dungeon.floors():
            self._flash_status("No floor there.")
            return
        # Prefer the page directly above/below the current view's top-left corner.
        below = self.dungeon.page_at_global(cur.gx, cur.gy, target_z)
        if below is None:
            on_floor = self.dungeon.pages_on_floor(target_z)
            below = on_floor[0] if on_floor else None
        if below is None:
            self._flash_status("No floor there.")
            return
        if self._switch_to_page(below):
            self._flash_status(f"Floor {target_z}: {below.id}")

    # ─────────────────────────────────────────────────────────────────────
    #  Grouped panel menus: the Agents… / Terrain… / Lighting… buttons each
    #  pop a ContextMenu of that group's actions (replacing the old wall of
    #  per-action buttons in the setup panel).
    # ─────────────────────────────────────────────────────────────────────
    def _show_agents_menu(self):
        """Popup for the "Agents…" panel button: encounter save/load plus the ways
        to add individual agents (Create Mob/PC replace the old Select Mob/PC)."""
        items = [
            ("Load…",       self._open_load_agents_browser),
            ("Import DDB…", self._import_ddb_character),
            ("Save…",       self._open_save_agents_browser),
            ("Load PCs…",   self._open_load_pcs_browser),
            ("Create Mob…", lambda: self.mob_dialog.show(
                                lambda mob: self._on_mob_selected(mob))),
            ("Create PC…",  self._show_pc_class_menu),
            ("Clear",       self._clear_agents),
        ]
        self.context_menu.show((self.btn_agents.rect.x, self.btn_agents.rect.y),
                               items, self.screen.get_size())

    def _clear_agents(self):
        """Remove every placed agent (plus their spell terrain effects and any
        ground items) — the agent-scoped clear that used to be the Clear All
        button. The panel's Clear All now wipes the whole scene via _clear_all."""
        self.bm.clear_agents()
        self.bm.clear_terrain_effects()
        self.bm.clear_items()
        self.pending_configs.clear()
        self.pending_mob_stats.clear()
        # Index-keyed per-agent metadata would bleed onto whatever agents land at
        # those indices next (same gotcha as _load_agents) — drop it with them.
        self._spell_metadata.clear()
        self._agent_meta.clear()
        self._xp_awarded_agents.clear()
        self.selected_idx        = -1
        self.drag_idx            = -1
        self._attack_cells_melee = []
        self._attack_cells_rnorm = []
        self._attack_cells_rlong = []

    def _clear_lighting(self):
        """Remove all DM-placed light sources and reset the whole map to the
        fully-lit default (mirrors _load_lighting's no-file branch)."""
        for eff in list(self.bm.active_light_effects):
            if eff.source_agent_idx == -1:  # DM-placed
                self.bm.remove_light_effect(eff.id)
        self.bm.apply_base_lighting(rpg.VisibilityLevel.Clear, [])

    def _clear_all(self):
        """Panel "Clear All": wipe the whole scene — agents, terrain AND lighting —
        back to a blank map (same state as a fresh startup)."""
        self._clear_agents()
        self._clear_terrain()
        self._clear_lighting()
        self._flash_status("Cleared agents, terrain and lighting.")

    def _open_load_agents_browser(self):
        """Open the encounter Load browser. No name_pattern: show ALL .json so
        encounters saved with custom names (not just *_agents.json) are visible."""
        start = os.path.dirname(self._save_path) or self._map_dir
        self.file_browser.open(
            start, self._on_load_path_chosen,
            save_mode=False,
            extensions=JSON_EXTS,
            title="Load Encounter",
        )

    def _open_save_agents_browser(self):
        start = os.path.dirname(self._save_path) or self._map_dir
        self.file_browser.open(
            start, self._on_save_path_chosen,
            save_mode=True,
            extensions=JSON_EXTS,
            default_filename=os.path.basename(self._save_path),
            name_pattern="_agents.json",
            title="Save Encounter As",
        )

    def _open_load_pcs_browser(self):
        """Load a party (*_pc_agents.json) ADDITIVELY onto the current scene, so
        the PCs drop onto an already-loaded dungeon without wiping its monsters."""
        start = os.path.dirname(self._save_path) or self._map_dir
        self.file_browser.open(
            start, self._on_load_pcs_chosen,
            save_mode=False,
            extensions=JSON_EXTS,
            name_pattern="_pc_agents.json",
            title="Load PCs",
        )

    def _show_pc_class_menu(self):
        pc_classes = ["Barbarian", "Bard", "Cleric", "Druid", "Fighter", "Monk",
                      "Paladin", "Ranger", "Rogue", "Sorcerer", "Warlock", "Wizard"]
        options = [(cls, lambda c=cls: self._on_pc_class_selected(c)) for cls in pc_classes]
        px_popup = self._panel_x() + self._PANEL_PAD
        self.context_menu.show((px_popup, 100), options, self.screen.get_size())

    def _show_terrain_menu(self):
        """Popup for the "Terrain…" panel button."""
        items = [
            ("Edit…",     self._open_terrain_editor),
            ("Load…",     self._open_load_terrain_browser),
            ("Save…",     self._open_save_terrain_browser),
            ("Generate…", self._on_generate_terrain),
            ("Hide" if self.show_terrain else "Show", self._toggle_show_terrain),
            ("Clear",     self._clear_terrain),
        ]
        self.context_menu.show((self.btn_terrain.rect.x, self.btn_terrain.rect.y),
                               items, self.screen.get_size())

    def _open_terrain_editor(self):
        self.terrain_editor.open(self.map_surf, self._terrain_regions, self.bm,
                                 ladders=self._ladders, door_links=self._door_links)

    def _toggle_show_terrain(self):
        self.show_terrain = not self.show_terrain

    def _open_save_terrain_browser(self):
        """Save Terrain (file picker — lets terrain be saved before combat and
        reused across maps/encounters, independent of the agents save)."""
        start = os.path.dirname(self._terrain_path) or self._map_dir
        self.file_browser.open(
            start, self._on_save_terrain_chosen,
            save_mode=True,
            extensions=JSON_EXTS,
            default_filename=os.path.basename(self._terrain_path),
            name_pattern="_terrain.json",
            title="Save Terrain As",
        )

    def _open_load_terrain_browser(self):
        """Open the terrain Load browser. No name_pattern: show ALL .json so
        terrain saved with custom names (not just *_terrain.json) shows."""
        start = os.path.dirname(self._terrain_path) or self._map_dir
        self.file_browser.open(
            start, self._on_load_terrain_chosen,
            save_mode=False,
            extensions=JSON_EXTS,
            title="Load Terrain",
        )

    def _clear_terrain(self):
        """Reset the scene's terrain to a blank slate: painted regions, doors,
        ladders, generator room metadata and engine terrain effects all go.
        Auto-detected walls and the manual grid are left alone (the Walls toggle
        and Set Grid… own those)."""
        self._terrain_regions = []
        self._terrain_rooms = []
        self._staging_cells = None
        self._ladders = []
        self._door_links = {}
        for d in list(self.bm.doors):
            self.bm.remove_door(d.id)
        self.bm.reset_terrain_multipliers()
        self._apply_terrain_to_battle_map()   # reverts painted Wall/Chasm/Water cells
        self.bm.clear_terrain_effects()
        self._build_overlay()
        self._mark_fog_dirty()
        if self.selected_idx >= 0:
            self._update_reach()
            self._update_attack_overlay()
        self._flash_status("Terrain cleared.")

    def _show_lighting_menu(self):
        """Popup for the "Lighting…" panel button."""
        items = [
            ("Edit…", self._open_lighting_editor),
            ("Load…", self._open_load_lighting_browser),
            ("Hide" if self.show_lighting_overlay else "Show",
             self._toggle_lighting_overlay),
        ]
        self.context_menu.show((self.btn_lighting.rect.x, self.btn_lighting.rect.y),
                               items, self.screen.get_size())

    def _open_lighting_editor(self):
        """Open the lighting editor primed with the encounter's saved lighting."""
        light_sources = []
        default_light = rpg.VisibilityLevel.Clear
        if os.path.exists(self._lighting_path):
            try:
                with open(self._lighting_path, 'r') as f:
                    data = json.load(f)
                    # Convert saved format (with "light_level" string) to dialog format (with "level" enum)
                    saved_sources = data.get("light_sources", [])
                    for src in saved_sources:
                        level_str = src.get("light_level", "Sunlight")

                        # Lights can be stored as grid coordinates (col, row) or old pixel format (x, y)
                        if "col" in src and "row" in src:
                            # New format: grid coordinates
                            col = src.get("col", 0)
                            row = src.get("row", 0)
                        else:
                            # Old format: pixel coordinates - convert to grid
                            x = src.get("x", 0)
                            y = src.get("y", 0)
                            cell = self._pixel_to_cell(x, y)
                            if not cell:
                                continue
                            col = cell.col
                            row = cell.row

                        light_sources.append({
                            "name": src.get("name", "Light"),
                            "col": col,
                            "row": row,
                            "level": self._parse_light_level(level_str),
                            "radius": src.get("bright_radius", 5),
                        })
                    default_light_str = data.get("default_light", "BrightLight")
                    default_light = self._parse_light_level(default_light_str)
            except:
                light_sources = []
                default_light = rpg.VisibilityLevel.Clear
        self.lighting_editor.open(self.map_surf, self.bm, self, light_sources, default_light)

    def _open_load_lighting_browser(self):
        start = os.path.dirname(self._lighting_path) or self._map_dir
        self.file_browser.open(
            start, self._on_load_lighting_chosen,
            save_mode=False,
            extensions=JSON_EXTS,
            title="Load Lighting",
        )

    def _toggle_lighting_overlay(self):
        self.show_lighting_overlay = not self.show_lighting_overlay

    # ─────────────────────────────────────────────────────────────────────
    #  Dungeon manifest management (Phase 6): New / Open / Save / Add Page,
    #  plus the Pages overview that places pages on the global grid.
    #  The manifest is placement-only; each page's scene lives in its own
    #  encounter sidecars (agents/terrain/lighting/effects).
    # ─────────────────────────────────────────────────────────────────────
    def _show_dungeon_menu(self):
        """Popup for the "Dungeon Configuration" panel button. The item set depends
        on whether a manifest is currently open."""
        if self.dungeon is None:
            items = [
                ("New Dungeon (this map)", self._dungeon_new),
                ("Open Dungeon…",          self._dungeon_open_browser),
            ]
        else:
            items = [
                ("Pages / Overview…", self._dungeon_pages_overview),
                ("Add Page…",         self._dungeon_add_page_browser),
                ("Save Dungeon",      self._dungeon_save),
                ("Open Dungeon…",     self._dungeon_open_browser),
                ("Close Dungeon",     self._dungeon_close),
            ]
        self.context_menu.show((self.btn_dungeon.rect.x, self.btn_dungeon.rect.y),
                               items, self.screen.get_size())

    def _dungeon_dir(self) -> str:
        """The folder a page's relative ``png`` / ``encounter_base`` resolves against: the
        manifest's own folder (so a dungeon and its files travel together), falling back to
        the map dir before a manifest exists."""
        if self._dungeon_manifest_path:
            return os.path.dirname(os.path.abspath(self._dungeon_manifest_path)) or self._map_dir
        return self._map_dir

    def _dungeon_path_ref(self, path: str) -> str:
        """How a page references a file in the manifest: a bare basename when the file sits
        beside the manifest (portable), else an absolute path. ``_switch_to_page`` resolves
        both."""
        if not path:
            return ""
        ap = os.path.abspath(path)
        if os.path.dirname(ap) == os.path.abspath(self._dungeon_dir()):
            return os.path.basename(ap)
        return ap

    def _dungeon_stem(self) -> str:
        """The manifest's name without the ``.dungeon.json`` suffix — the prefix new
        pages' encounter files are named after."""
        path = self._dungeon_manifest_path or self._save_path
        fn = os.path.basename(path)
        for suffix in (".dungeon.json", "_agents.json", ".json"):
            if fn.endswith(suffix):
                return fn[: -len(suffix)]
        return os.path.splitext(fn)[0]

    def _unique_page_id(self, seed: str) -> str:
        """``seed``, suffixed with a counter until it is unused in the manifest."""
        seed = re.sub(r"[^\w.-]+", "_", seed).strip("_") or "page"
        cand, n = seed, 2
        while self.dungeon is not None and self.dungeon.page_by_id(cand) is not None:
            cand, n = f"{seed}_{n}", n + 1
        return cand

    def _dungeon_new(self):
        """Start a manifest with the CURRENT map + encounter as its (entry) first page,
        at global origin (0, 0, 0). Further pages come from Add Page…."""
        if self.combat_active:
            self._flash_status("Finish combat before starting a dungeon.")
            return
        cols = int(getattr(self.bm, "grid_cols", 0) or 0)
        rows = int(getattr(self.bm, "grid_rows", 0) or 0)
        if not cols or not rows:
            self._modal_message(["New Dungeon",
                                 "This map has no grid — Set Grid… first, so the page",
                                 "has a footprint on the global (X, Y, Z) grid."])
            return
        # Set the manifest path first: page refs are stored relative to its folder.
        self._dungeon_manifest_path = dungeon_path_for(self._save_path)
        page = MapPage(id=self._unique_page_id(self._dungeon_stem()),
                       png=self._dungeon_path_ref(self._map_path),
                       encounter_base=self._dungeon_path_ref(self._save_path),
                       origin=[0, 0, 0], cols=cols, rows=rows)
        self.dungeon = Dungeon(pages=[page], entry_page_id=page.id)
        self.dungeon_page = page          # already loaded — no page switch needed
        self._apply_page_origin(page)
        self._dungeon_save()

    def _dungeon_save(self):
        """Write the manifest, plus the active page's scene (agents + terrain) so the
        dungeon on disk matches what's on screen."""
        if self.dungeon is None:
            self._flash_status("No dungeon open — New Dungeon first.")
            return
        path = self._dungeon_manifest_path or dungeon_path_for(self._save_path)
        try:
            self.dungeon.save(path)
        except OSError as e:                          # noqa: BLE001 — report, don't crash
            self._flash_status(f"Could not save dungeon: {e}")
            return
        self._dungeon_manifest_path = path
        self._save_agents()
        self._save_terrain()
        self._flash_status(f"Saved {os.path.basename(path)} ({len(self.dungeon.pages)} pages)")

    def _dungeon_open_browser(self):
        start = os.path.dirname(self._dungeon_manifest_path or self._save_path) or self._map_dir
        self.file_browser.open(
            start, self._on_open_dungeon_chosen,
            save_mode=False,
            extensions=JSON_EXTS,
            name_pattern=".dungeon.json",
            title="Open Dungeon",
        )

    def _on_open_dungeon_chosen(self, path: str):
        """Open a ``.dungeon.json`` and load its entry page."""
        if self.combat_active:
            self._flash_status("Finish combat before opening a dungeon.")
            return
        try:
            dungeon = Dungeon.load(path)
        except Exception as e:                       # noqa: BLE001 — bad file ⇒ keep the scene
            self._flash_status(f"Not a dungeon manifest: {os.path.basename(path)} ({e})")
            return
        entry = dungeon.entry_page()
        if entry is None:
            self._flash_status("Dungeon manifest has no pages.")
            return
        self.dungeon = dungeon
        self._dungeon_manifest_path = path
        self.dungeon_page = None      # initial load: don't write the outgoing scene back
        if not self._switch_to_page(entry, force=True):
            # Entry page unusable (its PNG is gone) — stay where we were.
            self.dungeon = None
            self._dungeon_manifest_path = None
            return
        self._flash_status(f"Dungeon: {os.path.basename(path)} — {entry.id}")

    def _dungeon_close(self):
        """Leave dungeon mode. The manifest stays on disk; the active page's map and
        encounter stay loaded as an ordinary single map."""
        if self.dungeon is None:
            return
        if self.combat_active:
            self._flash_status("Finish combat before closing the dungeon.")
            return
        self._save_agents()
        self._save_terrain()
        self.dungeon = None
        self.dungeon_page = None
        self._dungeon_manifest_path = None
        self._flash_status("Dungeon closed — single-map mode.")

    def _dungeon_add_page_browser(self):
        if self.dungeon is None:
            self._flash_status("No dungeon open — New Dungeon first.")
            return
        self.file_browser.open(
            self._dungeon_dir(), self._on_add_page_png_chosen,
            save_mode=False,
            extensions=IMAGE_EXTS,
            title="Add Page — Select Map Image",
        )

    def _on_add_page_png_chosen(self, png_path: str):
        """Add ``png_path`` as a new page, east of the current floor's rightmost page,
        with a fresh empty encounter, and switch to it. The page's footprint
        (cols × rows) is only known once its grid is analyzed, so it is recorded after
        the switch; the origin can then be moved in the Pages overview."""
        if self.dungeon is None:
            return
        if self.combat_active:
            self._flash_status("Finish combat before adding a page.")
            return
        cur = self.dungeon_page
        z  = cur.z  if cur else 0
        gy = cur.gy if cur else 0
        on_floor = self.dungeon.pages_on_floor(z)
        gx = max((p.gx + p.cols for p in on_floor), default=0)

        page_id = self._unique_page_id(os.path.splitext(os.path.basename(png_path))[0])
        # Each page owns its own encounter sidecars: <manifest stem>_<page id>_agents.json,
        # written beside the manifest.
        agents_path = os.path.join(self._dungeon_dir(),
                                   f"{self._dungeon_stem()}_{page_id}_agents.json")
        if not os.path.exists(agents_path):
            try:
                with open(agents_path, "w") as f:
                    json.dump({"agents": [], "map_items": []}, f, indent=2)
            except OSError as e:                     # noqa: BLE001
                self._flash_status(f"Could not create {os.path.basename(agents_path)}: {e}")
                return

        page = MapPage(id=page_id, png=self._dungeon_path_ref(png_path),
                       encounter_base=self._dungeon_path_ref(agents_path),
                       origin=[gx, gy, z], cols=0, rows=0)
        self.dungeon.add_page(page)
        if not self._switch_to_page(page):
            self.dungeon.remove_page(page_id)        # switch refused — don't keep a page we can't open
            return
        page.cols = int(getattr(self.bm, "grid_cols", 0) or 0)
        page.rows = int(getattr(self.bm, "grid_rows", 0) or 0)
        self._apply_page_origin(page)
        self._dungeon_save()
        if not page.cols or not page.rows:
            self._modal_message(["Page added — but it has no grid",
                                 f"'{page_id}' has no detected grid, so it has no footprint",
                                 "on the global map. Use Set Grid…, then re-save the dungeon",
                                 "(Dungeon… → Save Dungeon) to record its size."])
        else:
            self._flash_status(f"Added page '{page_id}' at ({gx}, {gy}, {z})")

    def _dungeon_pages_overview(self):
        """Run the Pages overview modal, then apply what it asked for: persist the
        manifest, re-stamp the engine's origin if the ACTIVE page moved, and switch
        pages on a Go To (done out here — a page switch resizes the window, so it must
        not happen inside the modal's own draw loop)."""
        if self.dungeon is None:
            self._flash_status("No dungeon open — New Dungeon first.")
            return
        goto = self._modal_dungeon_pages()
        # The overview edits the manifest in place (origins / entry / removals), so it is
        # always written back on exit.
        self._dungeon_save()
        if self.dungeon_page is not None and self.dungeon.page_by_id(self.dungeon_page.id) is None:
            # The active page was removed — fall back to the entry page.
            entry = self.dungeon.entry_page()
            self.dungeon_page = None
            if entry is None:
                self._flash_status("Dungeon has no pages left.")
                return
            self._switch_to_page(entry, force=True)
            return
        if goto is not None and (self.dungeon_page is None or goto.id != self.dungeon_page.id):
            if self._switch_to_page(goto):
                self._flash_status(f"Page: {goto.id} (floor {goto.z})")
            return
        if self.dungeon_page is not None:
            self._apply_page_origin(self.dungeon_page)   # its origin may have moved

    def _modal_dungeon_pages(self) -> "MapPage | None":
        """Blocking Pages / Overview dialog: the manifest's page list, a map of the
        selected page's floor (drawn from the origins), and the selected page's global
        origin (X/Y/Z steppers). Edits apply to the manifest immediately; the caller
        persists them. Returns the page to switch to (Go To), else None."""
        dung = self.dungeon
        sw, sh = self.screen.get_size()
        W, H = min(820, sw - 60), min(560, sh - 60)
        box = pygame.Rect((sw - W) // 2, (sh - H) // 2, W, H)
        lx  = box.x + 20
        list_w = 300
        list_rect = pygame.Rect(lx, box.y + 56, list_w, H - 160)
        ov_rect   = pygame.Rect(list_rect.right + 16, list_rect.y,
                                box.right - 20 - (list_rect.right + 16), list_rect.h - 46)
        ROW_H = 22

        sel = dung.page_by_id(self.dungeon_page.id) if self.dungeon_page else dung.entry_page()
        sel_id = sel.id if sel else None

        # Origin steppers for the selected page (re-seeded whenever the selection changes).
        st_y = ov_rect.bottom + 12
        sx = IntStepper(pygame.Rect(ov_rect.x + 26,       st_y, 92, 30), 0, -999, 999, font=self.font_sm)
        sy = IntStepper(pygame.Rect(ov_rect.x + 26 + 108, st_y, 92, 30), 0, -999, 999, font=self.font_sm)
        sz = IntStepper(pygame.Rect(ov_rect.x + 26 + 216, st_y, 92, 30), 0, -99,   99, font=self.font_sm)

        def seed_steppers():
            p = dung.page_by_id(sel_id)
            if p is None:
                return
            sx.value, sy.value, sz.value = p.gx, p.gy, p.z

        seed_steppers()

        by = box.bottom - 46
        btn_entry  = Button(pygame.Rect(lx,             by, 96, 32), "Set Entry",
                            (70, 90, 120), (95, 115, 150), font=self.font_sm)
        btn_goto   = Button(pygame.Rect(lx + 104,       by, 96, 32), "Go To Page",
                            (60, 110, 70), (80, 140, 90), font=self.font_sm)
        btn_remove = Button(pygame.Rect(lx + 208,       by, 96, 32), "Remove",
                            (110, 60, 60), (150, 80, 80), font=self.font_sm)
        btn_close  = Button(pygame.Rect(box.right - 115, by, 95, 32), "Close",
                            (70, 80, 100), (95, 105, 130), font=self.font_sm)

        overlay = pygame.Surface((sw, sh), pygame.SRCALPHA)
        overlay.fill((0, 0, 0, 170))
        ov_hits: dict = {}          # page id → rect, rebuilt by the overview each frame

        while True:
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    return None
                if event.type == pygame.KEYDOWN and event.key in (pygame.K_ESCAPE, pygame.K_RETURN):
                    return None
                if event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
                    # Pick a page from the list…
                    if list_rect.collidepoint(event.pos):
                        idx = (event.pos[1] - list_rect.y - 4) // ROW_H
                        if 0 <= idx < len(dung.pages):
                            sel_id = dung.pages[idx].id
                            seed_steppers()
                    # …or straight off the floor map.
                    for pid, r in ov_hits.items():
                        if r.collidepoint(event.pos):
                            sel_id = pid
                            seed_steppers()
                            break
                sx.handle(event)
                sy.handle(event)
                sz.handle(event)
                if btn_close.clicked(event):
                    return None
                p = dung.page_by_id(sel_id)
                if btn_entry.clicked(event) and p is not None:
                    dung.entry_page_id = p.id
                if btn_goto.clicked(event) and p is not None:
                    return p
                if btn_remove.clicked(event) and p is not None:
                    dung.remove_page(p.id)
                    nxt = dung.entry_page()
                    sel_id = nxt.id if nxt else None
                    seed_steppers()

            # Live-apply the steppers to the selected page so the overview shows the move
            # as it happens (the caller writes the manifest when the dialog closes).
            p = dung.page_by_id(sel_id)
            if p is not None:
                p.origin = [sx.value, sy.value, sz.value]

            # ── Render ─────────────────────────────────────────────────────
            self.screen.blit(overlay, (0, 0))
            pygame.draw.rect(self.screen, (35, 35, 50), box, border_radius=8)
            pygame.draw.rect(self.screen, (90, 90, 110), box, 1, border_radius=8)
            name = os.path.basename(self._dungeon_manifest_path or "dungeon.json")
            self.screen.blit(self.font_lg.render(f"Dungeon — {name}", True, (235, 235, 245)),
                             (lx, box.y + 16))

            # Page list: ★ = entry page, ● = the page loaded in the engine.
            pygame.draw.rect(self.screen, (24, 24, 36), list_rect, border_radius=6)
            pygame.draw.rect(self.screen, (90, 90, 115), list_rect, 1, border_radius=6)
            for i, pg in enumerate(dung.pages):
                ry = list_rect.y + 4 + i * ROW_H
                if ry + ROW_H > list_rect.bottom:
                    break
                row = pygame.Rect(list_rect.x + 2, ry, list_rect.w - 4, ROW_H - 2)
                if pg.id == sel_id:
                    pygame.draw.rect(self.screen, (55, 75, 120), row, border_radius=3)
                marks = ("★" if pg.id == dung.entry_page_id else " ") + \
                        ("●" if (self.dungeon_page and pg.id == self.dungeon_page.id) else " ")
                txt = f"{marks} {pg.id}  z={pg.z} ({pg.gx},{pg.gy}) {pg.cols}×{pg.rows}"
                self.screen.blit(self.font_sm.render(txt, True, (222, 222, 236)),
                                 (row.x + 6, row.y + 3))

            # Floor map of the selected page's floor.
            floor_z = p.z if p is not None else 0
            ov_hits = self._draw_floor_overview(ov_rect, floor_z, sel_id)

            # Origin row.
            self.screen.blit(self.font_sm.render(f"Origin of '{sel_id or '—'}' (global cells)",
                                                 True, (185, 185, 200)),
                             (ov_rect.x, st_y - 16))
            for label, st in (("X", sx), ("Y", sy), ("Z", sz)):
                self.screen.blit(self.font_sm.render(label, True, (185, 185, 200)),
                                 (st.rect.x - 16, st.rect.y + 8))
                st.draw(self.screen)

            btn_entry.draw(self.screen)
            btn_goto.draw(self.screen)
            btn_remove.draw(self.screen)
            btn_close.draw(self.screen)
            pygame.display.flip()
            self.clock.tick(60)

    def _draw_floor_overview(self, rect: pygame.Rect, z: int, sel_id=None) -> dict:
        """Draw floor ``z``'s page layout (straight from the manifest origins) inside
        ``rect``: one box per page, scaled to fit, gold = the page loaded in the engine,
        white outline = ``sel_id``. Returns {page id: rect} for hit-testing."""
        pygame.draw.rect(self.screen, (24, 24, 36), rect, border_radius=6)
        pygame.draw.rect(self.screen, (90, 90, 115), rect, 1, border_radius=6)
        hits: dict = {}
        if self.dungeon is None:
            return hits
        # A page with no grid has no footprint — it can't be drawn on the global map.
        pages = [p for p in self.dungeon.pages_on_floor(z) if p.cols > 0 and p.rows > 0]
        if not pages:
            self.screen.blit(self.font_sm.render(f"No sized pages on floor {z}", True, (140, 140, 160)),
                             (rect.x + 12, rect.y + 12))
            return hits

        min_x = min(p.gx for p in pages)
        min_y = min(p.gy for p in pages)
        span_x = max(1, max(p.gx + p.cols for p in pages) - min_x)
        span_y = max(1, max(p.gy + p.rows for p in pages) - min_y)
        pad = 12
        s = min((rect.w - 2 * pad) / span_x, (rect.h - 2 * pad) / span_y)
        ox = rect.x + pad + ((rect.w - 2 * pad) - span_x * s) / 2
        oy = rect.y + pad + ((rect.h - 2 * pad) - span_y * s) / 2

        self.screen.blit(self.font_sm.render(f"Floor {z}", True, (170, 170, 190)),
                         (rect.x + 8, rect.y + 4))
        for p in pages:
            r = pygame.Rect(int(ox + (p.gx - min_x) * s), int(oy + (p.gy - min_y) * s),
                            max(6, int(p.cols * s)), max(6, int(p.rows * s)))
            active = self.dungeon_page is not None and p.id == self.dungeon_page.id
            pygame.draw.rect(self.screen, (86, 72, 42) if active else (44, 50, 66), r, border_radius=3)
            if p.id == sel_id:
                pygame.draw.rect(self.screen, (240, 240, 250), r, 2, border_radius=3)
            else:
                pygame.draw.rect(self.screen, (110, 110, 140), r, 1, border_radius=3)
            tag = ("★ " if p.id == self.dungeon.entry_page_id else "") + p.id
            t = self.font_sm.render(tag, True, (230, 230, 240))
            if t.get_width() <= r.w - 6 and t.get_height() <= r.h - 4:
                self.screen.blit(t, (r.centerx - t.get_width() // 2, r.centery - t.get_height() // 2))
            hits[p.id] = r
        return hits

    def _flash_status(self, msg: str, secs: float = 2.5):
        """Show a transient confirmation message in the panel for `secs` seconds."""
        self._status_msg = msg
        self._status_msg_until = pygame.time.get_ticks() + int(secs * 1000)

    def _spawn_flash(self, agent_idx, text: str, color, secs: float = 1.5):
        """Spawn a short-lived floating text flash above an agent's token (e.g.
        "Hit (12)" / "Miss" / "Saved" / "Failed"). Session-only visual state; drawn
        each frame by _draw_floating_texts until it expires."""
        if agent_idx is None or agent_idx < 0:
            return
        # Stagger multiple flashes on the same agent (e.g. multiattack) so they
        # rise from different heights rather than overlapping.
        rise = sum(20 for f in self._floating_texts if f["agent_idx"] == agent_idx)
        self._floating_texts.append({
            "agent_idx": agent_idx, "text": text, "color": color,
            "spawn_ms": pygame.time.get_ticks(), "dur_ms": int(secs * 1000),
            "rise": rise,
        })

    def _draw_floating_texts(self):
        """Render active floating-outcome flashes above their agents, drifting up
        and fading out over their lifetime. Called each frame after _draw_agents."""
        if not self._floating_texts:
            return
        now = pygame.time.get_ticks()
        # Prune expired entries in place.
        self._floating_texts = [
            f for f in self._floating_texts if now - f["spawn_ms"] < f["dur_ms"]
        ]
        agents = self.bm.placed_agents
        cpx = int(self.bm.cell_pixel_size * self.map_scale)
        font = getattr(self, "font_md", None) or self.font_sm
        for f in self._floating_texts:
            idx = f["agent_idx"]
            if idx < 0 or idx >= len(agents):
                continue
            pt = agents[idx]
            # NPC turn playback holds a just-killed token on screen until it drains, so the
            # killing-blow flash isn't dropped over an empty square.
            if pt.removed_from_play or (pt.conditions.dead and not self._npc_anim_draws_dead(idx)):
                continue
            apos = self._npc_anim_display_pos(idx)   # follow the animated position mid-slide
            if apos is not None:
                sx, sy = self._cell_to_screen_f(apos[0], apos[1])
            else:
                sx, sy = self._cell_to_screen(pt.origin.col, pt.origin.row)
            size_px = cpx * pt.size
            p = (now - f["spawn_ms"]) / max(1, f["dur_ms"])   # 0 → 1 over lifetime
            label = font.render(f["text"], True, f["color"]).convert_alpha()
            # Antialiased text has per-pixel alpha, so set_alpha() is ignored — fade by
            # multiplying the whole surface's alpha channel instead.
            alpha = max(0, int(255 * (1.0 - p)))
            label.fill((255, 255, 255, alpha), None, pygame.BLEND_RGBA_MULT)
            lx = sx + size_px // 2 - label.get_width() // 2
            ly = sy - 6 - f["rise"] - int(p * 20)
            self.screen.blit(label, (lx, ly))

    # ─────────────────────────────────────────────────────────────────────
    #  NPC turn playback (animated automated turns)
    # ─────────────────────────────────────────────────────────────────────
    # run_npc_turn resolves an automated turn atomically in C++, but the engine records a
    # visual event stream (rpg.NpcVisualEvent: Move paths / Announce text / Outcomes) which
    # the GUI replays here over several frames. While a playback is active the board renders
    # DISPLAY OVERRIDES — positions, HP values and alive-flags snapshotted BEFORE the turn
    # ran — and each played event advances them: the token slides along its actual route,
    # the action text typewriter-scrolls above the actor, and damage flashes / HP-bar drops
    # land when their moment arrives instead of teleport-and-done. _advance_turn (or the
    # parked reaction menu) is DEFERRED until the queue drains. Any click or keypress
    # fast-forwards (see _handle_events).

    _NPC_EV_MOVE, _NPC_EV_ANNOUNCE, _NPC_EV_OUTCOME = 0, 1, 2   # NpcVisualEvent.Kind values

    def _npc_anim_snapshot(self):
        """Pre-turn display state: origin / HP / alive of every in-play agent, captured
        BEFORE run_npc_turn mutates the world. Seeds the playback's display overrides."""
        snap = {}
        for i, pt in enumerate(self.bm.placed_agents):
            if pt.removed_from_play:
                continue
            snap[i] = {"pos": (float(pt.origin.col), float(pt.origin.row)),
                       "hp": pt.stats.hp_cur,
                       "was_alive": not pt.conditions.dead}
        return snap

    def _npc_anim_start(self, events, snapshot, on_done):
        """Begin replaying an automated turn's event stream. on_done runs when it drains
        (advance the turn, or open the parked reaction menu the turn suspended on)."""
        self._npc_anim = {
            "events":  events,
            "ei":      0,                          # current event index
            "t0":      pygame.time.get_ticks(),    # ms the current event started
            "applied": False,                      # current Outcome's one-shot side effects done
            "pos":     {i: s["pos"] for i, s in snapshot.items()},   # {idx: (fcol, frow)}
            "hp":      {i: s["hp"] for i, s in snapshot.items()},    # {idx: displayed hp_cur}
            # Agents alive at snapshot keep drawing even if the turn killed them — the corpse
            # (and its killing-blow flash) vanish together when the playback drains.
            "draw_dead": {i for i, s in snapshot.items() if s["was_alive"]},
            "on_done": on_done,
        }

    # ── Display-override accessors (rendering reads these) ───────────────
    def _npc_anim_display_pos(self, idx):
        """(fcol, frow) the token should be drawn at during playback, else None."""
        a = self._npc_anim
        return a["pos"].get(idx) if a is not None else None

    def _npc_anim_hp(self, idx):
        """HP value the token's bar should show during playback, else None (= live)."""
        a = self._npc_anim
        return a["hp"].get(idx) if a is not None else None

    def _npc_anim_draws_dead(self, idx):
        """True while playback holds a now-dead token on screen (alive at snapshot)."""
        a = self._npc_anim
        return a is not None and idx in a["draw_dead"]

    def _npc_anim_agent_fogged(self, idx):
        """True when idx's whole footprint sits in never-explored fog (mirrors _draw_agents'
        fog gate). Its Move/Announce events resolve instantly and silently — no info leak,
        no dead air staring at an empty map."""
        if not self._fog_active() or idx < 0 or idx >= len(self.bm.placed_agents):
            return False
        pt = self.bm.placed_agents[idx]
        if pt.faction == PC_FACTION:
            return False
        fp = [rpg.Cell(pt.origin.col + dc, pt.origin.row + dr)
              for dc in range(pt.size) for dr in range(pt.size)]
        return bool(fp) and all(not self.bm.is_explored(c) for c in fp)

    # ── Per-frame advance (called from the main loop) ─────────────────────
    def _advance_npc_playback(self):
        """Advance the active playback one frame. Instant events chain within the frame;
        timed events (a sliding move, a scrolling announce, an outcome beat) return with
        their overrides set for this frame's draw."""
        a = self._npc_anim
        if a is None:
            return
        now = pygame.time.get_ticks()
        while True:
            if a["ei"] >= len(a["events"]):
                self._npc_anim_finish()
                return
            ev = a["events"][a["ei"]]
            el = now - a["t0"]
            if ev.kind == self._NPC_EV_MOVE:
                path  = ev.path
                steps = len(path) - 1
                if steps <= 0 or self._npc_anim_agent_fogged(ev.agent_idx):
                    if steps > 0:   # fogged mover: commit the destination, skip the slide
                        a["pos"][ev.agent_idx] = (float(path[-1].col), float(path[-1].row))
                    self._npc_anim_next(now)
                    continue
                dur = steps / NPC_ANIM_CELLS_PER_SEC * 1000.0
                if el >= dur:
                    a["pos"][ev.agent_idx] = (float(path[-1].col), float(path[-1].row))
                    self._npc_anim_next(now)
                    continue
                p = el / dur * steps                 # fractional path progress in cells
                i = min(int(p), steps - 1)
                f = p - i
                c0, c1 = path[i], path[i + 1]
                a["pos"][ev.agent_idx] = (c0.col + f * (c1.col - c0.col),
                                          c0.row + f * (c1.row - c0.row))
                return
            if ev.kind == self._NPC_EV_ANNOUNCE:
                if self._npc_anim_agent_fogged(ev.agent_idx):
                    self._npc_anim_next(now)
                    continue
                dur = len(ev.text) / NPC_TYPEWRITER_CPS * 1000.0 + NPC_ANNOUNCE_HOLD_MS
                if el >= dur:
                    self._npc_anim_next(now)
                    continue
                return   # _draw_npc_announcement renders the typewriter reveal from ev + t0
            # Outcome: one-shot side effects (flash + HP override), then a short beat so
            # consecutive swings of a multiattack read as separate hits.
            if not a["applied"]:
                a["applied"] = True
                self._npc_anim_apply_outcome(ev)
            if el >= NPC_OUTCOME_BEAT_MS:
                self._npc_anim_next(now)
                continue
            return

    def _npc_anim_next(self, now):
        a = self._npc_anim
        a["ei"]      += 1
        a["t0"]       = now
        a["applied"]  = False

    def _npc_anim_apply_outcome(self, ev):
        """One-shot side effects of an Outcome event: the floating flash and the synced
        HP-bar override. (A killed token keeps drawing until the playback drains — see
        draw_dead — so the killing-blow flash isn't orphaned over an empty square.)"""
        self._spawn_flash(ev.agent_idx, ev.text, FLASH_GOOD if ev.good else FLASH_BAD)
        if ev.hp_after >= 0:
            self._npc_anim["hp"][ev.agent_idx] = ev.hp_after

    def _npc_anim_fast_forward(self):
        """Skip control (any click/keypress): apply everything left instantly and finish."""
        a = self._npc_anim
        if a is None:
            return
        first = True
        for ev in a["events"][a["ei"]:]:
            if ev.kind == self._NPC_EV_MOVE and len(ev.path) > 1:
                a["pos"][ev.agent_idx] = (float(ev.path[-1].col), float(ev.path[-1].row))
            elif ev.kind == self._NPC_EV_OUTCOME and not (first and a["applied"]):
                self._npc_anim_apply_outcome(ev)
            first = False
        a["ei"] = len(a["events"])
        self._npc_anim_finish()

    def _npc_anim_finish(self):
        """Queue drained: drop every display override (live state shows — including corpse
        removal for anything killed this turn) and run the deferred continuation."""
        a = self._npc_anim
        self._npc_anim = None
        cb = a.get("on_done")
        if cb:
            cb()

    def _draw_npc_announcement(self):
        """Typewriter-scroll the active Announce event's text above the acting token.
        Drawn each frame right after the floating flashes."""
        a = self._npc_anim
        if a is None or a["ei"] >= len(a["events"]):
            return
        ev = a["events"][a["ei"]]
        if ev.kind != self._NPC_EV_ANNOUNCE:
            return
        idx = ev.agent_idx
        if idx < 0 or idx >= len(self.bm.placed_agents):
            return
        pt = self.bm.placed_agents[idx]
        # A still-concealed actor's announcement bubble would float over an undrawn
        # token and give away its position — suppress it. (An attacker's Hidden clears
        # during the turn, so revealed actors announce normally at playback time.)
        if self._npc_concealed_from_party(idx, pt):
            return
        now   = pygame.time.get_ticks()
        shown = ev.text[:max(1, int((now - a["t0"]) / 1000.0 * NPC_TYPEWRITER_CPS))]
        pos = a["pos"].get(idx, (float(pt.origin.col), float(pt.origin.row)))
        sx, sy = self._cell_to_screen_f(pos[0], pos[1])
        cpx     = int(self.bm.cell_pixel_size * self.map_scale)
        size_px = cpx * pt.size
        font  = getattr(self, "font_md", None) or self.font_sm
        label = font.render(shown, True, (255, 240, 200))
        bg = pygame.Surface((label.get_width() + 10, label.get_height() + 6), pygame.SRCALPHA)
        bg.fill((20, 15, 5, 215))
        bx = sx + size_px // 2 - bg.get_width() // 2
        by = sy - bg.get_height() - 8
        bx = max(4, min(bx, self.screen.get_width() - bg.get_width() - 4))   # keep on screen
        by = max(4, by)
        self.screen.blit(bg, (bx, by))
        self.screen.blit(label, (bx + 5, by + 3))

    def _on_save_terrain_chosen(self, path: str):
        """Export the current terrain to a chosen _terrain.json (does not change the
        active encounter base — pure export so terrain can be reused across maps)."""
        self._save_terrain(path)
        self._flash_status(f"Terrain saved: {os.path.basename(path)}")

    def _on_load_terrain_chosen(self, path: str):
        """Import terrain from a chosen _terrain.json into the current scene (it then
        saves with this encounter)."""
        # Load shows every .json, so refuse a non-terrain pick (no "regions" key)
        # rather than clearing the current terrain with an empty region list.
        try:
            with open(path) as f:
                if "regions" not in json.load(f):
                    self._flash_status(f"Not a terrain file: {os.path.basename(path)}")
                    return
        except Exception as e:
            self._flash_status(f"Could not read {os.path.basename(path)}: {e}")
            return
        self._load_terrain(path)
        if self.selected_idx >= 0:
            self._update_reach()
            self._update_attack_overlay()
        self._flash_status(f"Terrain loaded: {os.path.basename(path)}")

    def _on_load_lighting_chosen(self, path: str):
        """Import lighting from a chosen _lighting.json into the current scene (it then
        saves with this encounter)."""
        # Load shows every .json, so refuse a non-lighting pick (no "light_sources" key)
        # rather than clearing the current lighting with an empty source list.
        try:
            with open(path) as f:
                if "light_sources" not in json.load(f):
                    self._flash_status(f"Not a lighting file: {os.path.basename(path)}")
                    return
        except Exception as e:
            self._flash_status(f"Could not read {os.path.basename(path)}: {e}")
            return
        self._load_lighting(path)
        # Auto-enable the lighting overlay so the user can see the loaded lighting
        self.show_lighting_overlay = True
        self._flash_status(f"Lighting loaded: {os.path.basename(path)}")

    def _merge_free_cell(self, col: int, row: int, size: int,
                         reserved: set[tuple[int, int]]):
        """Nearest cell to (col,row) where a size×size agent fits, respecting live
        terrain + already-placed agents (via _can_place) AND the cells already
        claimed by PCs merged in this same pass (`reserved`). Returns an rpg.Cell or
        None if nowhere on the map is free. Prefers the PC's own saved cell."""
        def ok(c) -> bool:
            if not (0 <= c.col < self.bm.grid_cols and 0 <= c.row < self.bm.grid_rows):
                return False
            if not self._can_place(c, size):
                return False
            return all((c.col + dc, c.row + dr) not in reserved
                       for dc in range(size) for dr in range(size))
        home = rpg.Cell(col, row)
        if ok(home):
            return home
        for radius in range(1, max(self.bm.grid_cols, self.bm.grid_rows) + 1):
            for dc in range(-radius, radius + 1):
                for dr in range(-radius, radius + 1):
                    if max(abs(dc), abs(dr)) != radius:
                        continue                     # only the ring at this radius
                    c = rpg.Cell(col + dc, row + dr)
                    if ok(c):
                        return c
        return None

    def _place_in_room(self, size: int, room_cells: list[tuple[int, int]],
                       reserved: set[tuple[int, int]]) -> rpg.Cell | None:
        """Find a size×size placement within the given room's floor cells, respecting
        terrain and reserved cells. Returns an rpg.Cell or None if no space fits."""
        def ok(c) -> bool:
            if not (0 <= c.col < self.bm.grid_cols and 0 <= c.row < self.bm.grid_rows):
                return False
            if not self._can_place(c, size):
                return False
            return all((c.col + dc, c.row + dr) not in reserved
                       for dc in range(size) for dr in range(size))

        # Try cells in the room (shuffled for variety)
        candidates = [rpg.Cell(c, r) for c, r in room_cells]
        random.shuffle(candidates)
        for c in candidates:
            if ok(c):
                return c
        return None

    def _on_load_pcs_chosen(self, path: str):
        """Load a party (*_pc_agents.json) ADDITIVELY onto the current scene, so the
        PCs drop onto an already-loaded dungeon without the destructive full-scene
        reload wiping the placed monsters. Mirrors the D&D Beyond import merge:
        persist the current agents, append each PC (relocated off any occupied or
        blocked cell), then reload the combined file. Every PC is forced onto the
        blue team (PC_FACTION) so the whole party fights the red encounter mobs as
        one side, regardless of what faction the party file stored. Each PC keeps its
        loadout from the party file. In a generated dungeon the PCs start in room 0 on
        floor 0 (the generator leaves that room empty for them)."""
        try:
            with open(path) as f:
                pc_doc = json.load(f)
        except Exception as e:                       # noqa: BLE001 — surface read/parse errors
            self._flash_status(f"Could not read {os.path.basename(path)}: {e}")
            return
        pcs = pc_doc.get("agents")
        if not isinstance(pcs, list) or not pcs:
            self._flash_status(f"No PCs in {os.path.basename(path)}")
            return
        if self.combat_active:
            self._flash_status("Finish combat before loading PCs")
            return

        # In a generated dungeon the party enters on floor 0, whose room 0 the generator
        # leaves empty as a staging room. If another floor is showing, drop back to the
        # entry (floor 0) page first so the PCs always start there.
        if self.dungeon is not None and self.dungeon_page is not None:
            entry = self.dungeon.entry_page()
            if entry is not None and self.dungeon_page.id != entry.id:
                if not self._switch_to_page(entry):
                    self._flash_status("Could not switch to floor 0 to place PCs.")
                    return

        # Persist current placements, then merge the PCs into that saved doc and reload.
        self._save_agents()
        try:
            with open(self._save_path) as f:
                doc = json.load(f)
        except (OSError, json.JSONDecodeError):
            doc = {"agents": [], "map_items": []}
        agents = doc.setdefault("agents", [])

        # Drop the PCs into the room the generator left empty. The authoritative source is
        # `_staging_cells` — the exact (post-filter) cells of results[0] recorded by Generate
        # Dungeon. It comes from the terrain sidecar; the current page's terrain (incl. floor
        # 0 after the switch above) is already loaded, so this is the staging room for here.
        #
        # We must NOT re-derive "room 0" as min(path_index): build_dungeon filters rooms with
        # too few placeable cells before choosing results[0], so raw path_index 0 can be a
        # DIFFERENT (e.g. top-left) room than the one actually left empty. `_staging_cells`
        # sidesteps that. Fall back to the path_index heuristic only for older saves.
        room0_cells = getattr(self, "_staging_cells", None)
        if not room0_cells:
            terrain_rooms = getattr(self, "_terrain_rooms", None) or []
            dict_rooms = [m for m in terrain_rooms if isinstance(m, dict)]
            if dict_rooms:
                entrance = min(dict_rooms, key=lambda m: m.get("path_index", 0))
                room0_cells = entrance.get("cells")

        reserved: set[tuple[int, int]] = set()
        added = dropped = 0
        for src in pcs:
            pc = dict(src)                           # don't mutate the source file's dict
            pc["faction"] = PC_FACTION               # whole party fights as the blue team
            size = int(pc.get("size", 1))

            # If we have room 0's cells, try to place the PC there; else default placement
            if room0_cells:
                spot = self._place_in_room(size, room0_cells, reserved)
            else:
                spot = self._merge_free_cell(int(pc.get("col", 0)), int(pc.get("row", 0)),
                                             size, reserved)

            if spot is None:
                dropped += 1                         # no free footprint
                continue
            pc["col"], pc["row"] = spot.col, spot.row
            for dc in range(size):
                for dr in range(size):
                    reserved.add((spot.col + dc, spot.row + dr))
            agents.append(pc)
            added += 1
        doc.setdefault("map_items", [])
        with open(self._save_path, "w") as f:
            json.dump(doc, f, indent=2)
        self._load_agents()

        msg = f"Loaded {added} PC(s) from {os.path.basename(path)}"
        if dropped:
            msg += f" ({dropped} didn't fit)"
        if room0_cells:
            msg += " in room 0"
        self._flash_status(msg)

    # ─────────────────────────────────────────────────────────────────────
    #  Copy / paste agents (pre-combat encounter building)
    # ─────────────────────────────────────────────────────────────────────
    def _unique_agent_name(self, name: str) -> str:
        """Return a name not already in use, suffixing/incrementing a trailing number.
        e.g. 'Goblin' -> 'Goblin 2', 'Goblin 2' -> 'Goblin 3' (skipping taken names)."""
        existing = {pt.name for pt in self.bm.placed_agents}
        parts = name.rsplit(" ", 1)
        if len(parts) == 2 and parts[1].isdigit():
            base, n = parts[0], int(parts[1]) + 1
        else:
            base, n = name, 2
        candidate = f"{base} {n}"
        while candidate in existing:
            n += 1
            candidate = f"{base} {n}"
        return candidate

    def _find_free_cell_near(self, col: int, row: int, size: int):
        """Spiral out from (col,row) for the nearest cell where a size×size agent fits."""
        for radius in range(0, 13):
            for dc in range(-radius, radius + 1):
                for dr in range(-radius, radius + 1):
                    if max(abs(dc), abs(dr)) != radius:
                        continue   # only the ring at this radius
                    c = rpg.Cell(col + dc, row + dr)
                    if self._can_place(c, size):
                        return c
        return None

    def _copy_agent(self, idx: int):
        """Snapshot a placed agent's full loadout to the clipboard (Ctrl+C)."""
        if not (0 <= idx < len(self.bm.placed_agents)):
            self._flash_status("Select an agent first, then Ctrl+C")
            return
        pt = self.bm.placed_agents[idx]
        self._agent_clipboard = {
            "name":       pt.name,
            "sprite":     pt.sprite_path,
            "size":       pt.size,
            "stats":      self.combat.get_agent_stats(self.bm, idx),
            "weapons":    list(self.combat.get_agent_weapons(self.bm, idx)),
            "spells":     list(self.combat.get_agent_spells(self.bm, idx)),
            "items":      list(self.combat.get_agent_items(self.bm, idx)),
            "armor":      list(self.combat.get_agent_armor(self.bm, idx)),
            "meta":       dict(self._agent_meta.get(idx, {})),
            # Spell rendering metadata for this agent, keyed by spell index.
            "spell_meta": {sp_idx: m for (a_idx, sp_idx), m in self._spell_metadata.items()
                           if a_idx == idx},
            # NPC automation flags, so a copied automated NPC pastes ready to self-drive.
            "npc_automated":   self.bm.is_agent_npc_automated(idx),
            "npc_auto_diff":   self.bm.get_agent_npc_automation_difficulty(idx),
            "npc_auto_strat":  self.bm.get_agent_npc_automation_strategy(idx),
        }
        self._flash_status(f"Copied {pt.name} — Ctrl+V to paste")

    def _paste_agent(self, cell):
        """Spawn a clone of the clipboard agent at/near `cell` (pre-combat only)."""
        if self.combat_active:
            return
        if not self._agent_clipboard:
            self._flash_status("Nothing to paste — copy an agent first (Ctrl+C)")
            return
        if cell is None:
            self._flash_status("Hover the map, then Ctrl+V to paste")
            return
        clip = self._agent_clipboard
        dest = self._find_free_cell_near(cell.col, cell.row, clip["size"])
        if dest is None:
            self._flash_status("No free space to paste here")
            return

        # Append a new agent non-destructively (existing agents' state untouched).
        cfg = rpg.AgentConfig()
        cfg.name        = self._unique_agent_name(clip["name"])
        cfg.sprite_path = clip["sprite"]
        cfg.size        = clip["size"]
        cfg.start_col   = dest.col
        cfg.start_row   = dest.row
        new_idx = self.bm.spawn_agent(cfg)
        if new_idx < 0:
            self._flash_status("Paste failed — could not place the copy")
            return

        # Clone the full loadout. The copy is a fresh creature: start at full HP, no
        # temp HP, no carried-over conditions (spawn_agent already gives clean conditions).
        st = clip["stats"]
        st.hp_cur  = st.hp_max
        st.temp_hp = 0
        self.combat.set_agent_stats(self.bm, new_idx, st)
        self.combat.set_agent_weapons(self.bm, new_idx, clip["weapons"])
        self.combat.set_agent_spells(self.bm, new_idx, clip["spells"])
        self.combat.set_agent_items(self.bm, new_idx, clip.get("items", []))
        self.combat.set_agent_armor(self.bm, new_idx, clip["armor"])

        # NPC innate-spell groups, so a copied NPC caster can still cast.
        meta = clip["meta"]
        if meta.get("is_npc") and meta.get("npc_spell_groups"):
            groups = {int(k): v for k, v in meta["npc_spell_groups"].items()}
            self.combat.init_npc_spell_groups(self.bm, new_idx, groups)
            self._agent_meta[new_idx] = {"is_npc": True,
                                         "npc_spell_groups": meta["npc_spell_groups"]}

        # Re-key spell rendering metadata onto the pasted agent.
        for sp_idx, m in clip["spell_meta"].items():
            self._spell_metadata[(new_idx, sp_idx)] = m

        # Carry over NPC automation flags so the copy self-drives like its source.
        if clip.get("npc_automated"):
            self.bm.set_agent_npc_automated(new_idx, True)
            self.bm.set_agent_npc_automation_difficulty(new_idx, clip.get("npc_auto_diff", 0))
            strat = clip.get("npc_auto_strat")
            if strat is not None:
                self.bm.set_agent_npc_automation_strategy(new_idx, strat)

        self.sprites.clear()
        self.selected_idx = new_idx
        self._mark_fog_dirty()   # a pasted token may be a party member with its own vision
        self._update_reach()
        self._update_attack_overlay()
        self._flash_status(f"Pasted {cfg.name}")

    def _update_reach(self):
        """Recompute walk/fly reachable-cell overlays for the selected agent.

        In combat mode the budget comes from CombatEngine so it shrinks as the
        agent moves.  Outside combat the full stat speed is used.
        """
        self._reach_walk   = []
        self._reach_fly    = []
        self._reach_swim   = []
        self._reach_burrow = []
        self._reach_set    = set()
        idx = self.selected_idx
        if idx < 0 or idx >= len(self.bm.placed_agents):
            return
        pt    = self.bm.placed_agents[idx]
        # A concealed automated NPC (Hidden/unpierced Invisible) must not paint its
        # movement range — the overlay would betray the position of an undrawn token.
        if self._npc_concealed_from_party(idx, pt):
            return
        stats = self.combat.get_agent_stats(self.bm, idx)

        if self.combat_active:
            walk_ft   = self.move_remaining_walk
            fly_ft    = self.move_remaining_fly
            swim_ft   = self.move_remaining_swim
            burrow_ft = self.move_remaining_burrow
        else:
            walk_ft   = stats.speed_walk
            fly_ft    = stats.speed_fly
            swim_ft   = stats.speed_swim
            burrow_ft = stats.speed_burrow

        # Dragging a grappled creature costs double per foot (BattleMap::moveAgent), so the agent
        # can only reach half as far. Halve the previewed budget so the overlay matches enforcement.
        if any(o.conditions.grappled and o.conditions.grappler_idx == idx
               for j, o in enumerate(self.bm.placed_agents) if j != idx):
            walk_ft   //= 2
            fly_ft    //= 2
            swim_ft   //= 2
            burrow_ft //= 2

        # Pass idx so faction-spared difficult terrain (e.g. the agent's own / an ally's
        # Spirit Guardians) does not shrink the previewed reach.
        if walk_ft > 0:
            self._reach_walk = self.bm.reachable_cells(
                pt.origin, pt.size, walk_ft, rpg.MovementType.Walk, idx)
        if fly_ft > 0:
            self._reach_fly = self.bm.reachable_cells(
                pt.origin, pt.size, fly_ft, rpg.MovementType.Fly, idx)
        if swim_ft > 0:
            self._reach_swim = self.bm.reachable_cells(
                pt.origin, pt.size, swim_ft, rpg.MovementType.Swim, idx)
        if burrow_ft > 0:
            self._reach_burrow = self.bm.reachable_cells(
                pt.origin, pt.size, burrow_ft, rpg.MovementType.Burrow, idx)

        # Drag validity uses only the selected movement type's reach.
        _reach_by_type = {
            rpg.MovementType.Walk:   self._reach_walk,
            rpg.MovementType.Fly:    self._reach_fly,
            rpg.MovementType.Swim:   self._reach_swim,
            rpg.MovementType.Burrow: self._reach_burrow,
        }
        self._reach_set = {(c.col, c.row)
                           for c in _reach_by_type.get(self.move_type, [])}

    # Origin feats the GUI can assign (must mirror StatsDialog.ORIGIN_FEATS minus "NONE").
    _ORIGIN_FEATS = {"Alert", "Crafter", "Healer", "Lucky", "Magic Initiate", "Musician",
                     "Savage Attacker", "Skilled", "Tavern Brawler", "Tough"}

    @staticmethod
    def _set_origin_feat(stats, new_feat: str, char_level: int):
        """Set the agent's single origin feat idempotently.

        The dialog re-edits a live Stats whose hp_max/luck_points already include any prior
        feat's one-time bonus (the HP stepper round-trips the boosted value), so changing or
        re-confirming a feat must STRIP the previous origin feat's effects before applying the
        new one. add_feat() (the C++ source of truth) handles the apply; this only handles the
        inverse for the swap. No-op when the feat is unchanged.
        """
        new_feat = new_feat or "NONE"
        prev = next((f for f in list(stats.feats) if f in App._ORIGIN_FEATS), None)
        prev = prev or "NONE"
        if prev == new_feat:
            return  # already applied — leave hp_max/luck_points/initiative_prof as-is

        # Strip the previous origin feat's one-time effects.
        if prev == "Tough":
            stats.hp_max = max(1, stats.hp_max - 2 * char_level)
            stats.hp_cur = max(1, stats.hp_cur - 2 * char_level)
        elif prev == "Alert":
            stats.initiative_prof = False   # only this feat sets it
        elif prev == "Lucky":
            stats.luck_points = 0
            stats.luck_points_max = 0
        stats.feats = [f for f in list(stats.feats) if f not in App._ORIGIN_FEATS]

        # Apply the newly chosen feat via the engine (applies Tough HP / Alert prof / Lucky points).
        if new_feat != "NONE":
            stats.add_feat(new_feat)

    @staticmethod
    def _set_general_feats(stats, names):
        """Set the agent's general feats from the multi-select picker.

        General feats currently carry no one-time stat effects (ASI is not auto-applied —
        edit ability scores via the steppers), so this is a plain replace: drop all general
        feats, then re-add the selected ones. `add_feat` is used so any future general feat
        that gains an addFeat effect still applies on grant. Origin feats are untouched
        (the name-sets are disjoint). Epic boons ride the same picker/list as general feats,
        so they are dropped/re-added here too.
        """
        names = list(names or [])
        stats.feats = [f for f in list(stats.feats)
                       if f not in GENERAL_FEAT_NAMES and f not in EPIC_BOON_FEAT_NAMES]
        for n in names:
            stats.add_feat(n)

    def _on_stats_ok(self, agent_idx: int, steppers: dict, prof_flags: dict, class_name: str = "None", char_level: int = 1, npc_data: dict = None, subclass_name: str = "NONE", eldritch_invocations: list = None, blessed_strike_name: str = "NONE", origin_feat: str = "NONE", general_feats: list = None, elemental_adept_types: list = None, hunter_prey_name: str = "NONE", defensive_tactics_name: str = "NONE", draconic_affinity_type: int = -1, metamagic_options: list = None, irresistible_offense_ability: int = 0, class_levels: dict = None, subclasses: dict = None):
        """Called by StatsDialog when the user clicks OK.

        Multiclassing (MULTICLASSING_PLAN.md Phase 5): `class_levels` ({class:level})
        and `subclasses` ({class:subclass}) carry the full build. `class_name` /
        `char_level` remain the PRIMARY class / TOTAL level for the single-class
        feature logic below; the class/level/subclass/resource application iterates
        the maps. When `class_levels` is absent (legacy callers) it degrades to the
        single {class_name: char_level} build."""
        # Start from current stats so flags not shown in the dialog are preserved.
        stats = self.combat.get_agent_stats(self.bm, agent_idx)
        stats.str        = steppers["str"].value
        stats.dex        = steppers["dex"].value
        stats.con        = steppers["con"].value
        stats.intel      = steppers["intel"].value
        stats.wis        = steppers["wis"].value
        stats.cha        = steppers["cha"].value
        stats.hp_cur     = steppers["hp_cur"].value
        stats.hp_max     = steppers["hp_max"].value
        stats.base_ac    = steppers["base_ac"].value
        stats.speed_walk   = steppers["speed_walk"].value
        stats.speed_swim   = steppers["speed_swim"].value
        stats.speed_fly    = steppers["speed_fly"].value
        stats.speed_burrow = steppers["speed_burrow"].value
        stats.prof_bonus   = steppers["prof_bonus"].value
        stats.num_attacks  = steppers["num_attacks"].value
        # Saving throw proficiency per ability
        stats.save_prof_str   = prof_flags.get("save_prof_str",   False)
        stats.save_prof_dex   = prof_flags.get("save_prof_dex",   False)
        stats.save_prof_con   = prof_flags.get("save_prof_con",   False)
        stats.save_prof_intel = prof_flags.get("save_prof_intel", False)
        stats.save_prof_wis   = prof_flags.get("save_prof_wis",   False)
        stats.save_prof_cha   = prof_flags.get("save_prof_cha",   False)
        # Skill proficiency: Sleight of Hand (picks door locks)
        stats.sleight_of_hand_prof = prof_flags.get("sleight_of_hand_prof", False)

        # ── Multiclass class / level / subclass / resource application ──────────
        # Resolve the full build. Fall back to the single {primary: total} shape for
        # legacy callers that don't pass class_levels.
        cl_map = {c: int(l) for c, l in (class_levels or {}).items()
                  if int(l) > 0 and c not in (None, "None")}
        if not cl_map:
            # No real class in the build → keep the agent's primary as-is. This
            # preserves the "None" sentinel for classless monsters (never invents a
            # Fighter) and degrades gracefully for legacy single-class callers.
            cl_map = {class_name: char_level}
        sub_map = dict(subclasses or {})
        if class_name in cl_map and subclass_name != "NONE" and class_name not in sub_map:
            sub_map[class_name] = subclass_name

        # Apply each membered class's subclass field FIRST (Draconic HP / Aberrant
        # resistance and other resource gates read the subclass in C++).
        subclass_fields = {
            "Barbarian": ("barbarian_subclass", rpg.BarbianSubclass),
            "Fighter":   ("fighter_subclass",   rpg.FighterSubclass),
            "Druid":     ("druid_circle",       rpg.DruidCircle),
            "Monk":      ("monk_subclass",      rpg.MonkSubclass),
            "Paladin":   ("paladin_oath",       rpg.PaladinOath),
            "Wizard":    ("wizard_subclass",    rpg.WizardSubclass),
            "Warlock":   ("warlock_subclass",   rpg.WarlockSubclass),
            "Rogue":     ("rogue_subclass",     rpg.RogueSubclass),
            "Cleric":    ("cleric_subclass",    rpg.ClericSubclass),
            "Bard":      ("bard_subclass",      rpg.BardCollege),
            "Sorcerer":  ("sorcerer_subclass",  rpg.SorcererSubclass),
            "Ranger":    ("ranger_subclass",    rpg.RangerSubclass),
        }
        for cls in cl_map:
            field = subclass_fields.get(cls)
            sub = sub_map.get(cls, "NONE")
            if field and sub not in (None,):
                try:
                    setattr(stats, field[0], getattr(field[1], sub))
                except AttributeError:
                    pass

        # Set class levels: primary (lowest enum ordinal) as a single-class reset,
        # then the remaining classes additively. Slots recompute via computeMulticlassSlots.
        _members = [(n, int(v)) for n, v in rpg.CharacterClass.__members__.items()]
        order = [n for n, v in sorted(_members, key=lambda kv: kv[1]) if v > 0]
        ordered = sorted(cl_map.items(), key=lambda kv: order.index(kv[0]) if kv[0] in order else 99)
        stats.set_class_level(getattr(rpg.CharacterClass, ordered[0][0]), ordered[0][1])
        for cls, lvl in ordered[1:]:
            stats.add_class_level(getattr(rpg.CharacterClass, cls), lvl)

        # Per-class level-dependent side effects.
        # Path of the World Tree L6 — Branches of the Tree (C++ reaction gates on this flag).
        if "Barbarian" in cl_map:
            stats.has_branches_of_the_tree = (
                sub_map.get("Barbarian") == "WorldTree" and cl_map["Barbarian"] >= 6)
        # Ranger Hunter / Beast Master defaults.
        if "Ranger" in cl_map:
            rlvl = cl_map["Ranger"]
            if sub_map.get("Ranger") == "Hunter":
                if hunter_prey_name not in (None, "NONE"):
                    stats.hunter_prey = getattr(rpg.HunterPrey, hunter_prey_name)
                elif stats.hunter_prey == rpg.HunterPrey.NONE:
                    stats.hunter_prey = rpg.HunterPrey.ColossusSlayer
                if defensive_tactics_name not in (None, "NONE"):
                    stats.defensive_tactics = getattr(rpg.DefensiveTactics, defensive_tactics_name)
                elif rlvl >= 7 and stats.defensive_tactics == rpg.DefensiveTactics.NONE:
                    stats.defensive_tactics = rpg.DefensiveTactics.EscapeTheHorde
            if sub_map.get("Ranger") == "BeastMaster" and stats.primal_companion == rpg.PrimalCompanion.NONE:
                stats.primal_companion = rpg.PrimalCompanion.Land

        # Cleric Blessed Strikes choice (L7+)
        if "Cleric" in cl_map and blessed_strike_name != "NONE":
            stats.blessed_strike = getattr(rpg.BlessedStrike, blessed_strike_name)

        # Set Warlock invocations
        if "Warlock" in cl_map and eldritch_invocations:
            stats.eldritch_invocations = list(eldritch_invocations)

        # Initialize class resources for ALL classes (Rage, Focus Points, Portent Dice, …).
        # Merges per class and never double-counts Extra Attack. Must come AFTER subclasses
        # are set since resource creation checks them.
        stats.initialize_multiclass_resources()
        # Restore remaining slots to max (set/add + resource init just recomputed them).
        stats.spell_slots_remaining = list(stats.spell_slots_max)

        # Origin feat (one per PC). Applied after stats/level/prof_bonus are set so Tough HP,
        # Alert initiative proficiency, and Lucky points compute from the final values.
        self._set_origin_feat(stats, origin_feat, char_level)
        # General feats (multi-select). Disjoint from origin feats; no ASI auto-apply.
        self._set_general_feats(stats, general_feats)
        # Elemental Adept's chosen element(s) (set via the element picker). Kept only while the feat
        # is selected; cleared otherwise so a deselect doesn't leave stale types.
        stats.elemental_adept_types = list(elemental_adept_types or []) if stats.has_feat("Elemental Adept") else []
        # Boon of Irresistible Offense: which score Overwhelming Strike reads (0=STR, 1=DEX).
        stats.irresistible_offense_ability = int(irresistible_offense_ability) if stats.has_feat("Boon of Irresistible Offense") else 0
        # Draconic L6: persist the chosen ancestry element (-1 = none/not yet set).
        if "Sorcerer" in cl_map and sub_map.get("Sorcerer") == "Draconic":
            stats.draconic_affinity_type = int(draconic_affinity_type)
        # Sorcerer Metamagic: the learned options (assign the whole list via the property
        # setter — metamagic_options is a bound std::vector<MetamagicOption>; do not mutate
        # elements in place, cf. pybind11_array_copy_gotcha). Cleared for non-Sorcerers.
        stats.metamagic_options = ([rpg.MetamagicOption(int(v)) for v in (metamagic_options or [])]
                                   if "Sorcerer" in cl_map else [])

        self.combat.set_agent_stats(self.bm, agent_idx, stats)

        # For Monks, replace default "Unarmed" weapon with "MonkUnarmed" (1d8)
        if "Monk" in cl_map:
            current_weapons = list(self.combat.get_agent_weapons(self.bm, agent_idx))
            # Replace the first weapon (default) with MonkUnarmed if it's named "Unarmed"
            if current_weapons and current_weapons[0].name == "Unarmed":
                current_weapons[0] = self._create_monk_unarmed_weapon()
                self.combat.set_agent_weapons(self.bm, agent_idx, current_weapons)

        # Master of Myriad Forms (invocation 12): give the Warlock Alter Self claws
        # (1d6) in place of a bare unarmed strike.
        if "Warlock" in cl_map and 12 in (eldritch_invocations or []):
            current_weapons = list(self.combat.get_agent_weapons(self.bm, agent_idx))
            if current_weapons and current_weapons[0].name == "Unarmed":
                current_weapons[0] = self._create_alter_self_claws_weapon()
                self.combat.set_agent_weapons(self.bm, agent_idx, current_weapons)

        # Pact of the Blade (invocation 13): conjure the pact weapon into the MAIN-HAND slot (0).
        # Weapons are a fixed 3-slot array (main/off/ranged); the pact weapon is the Warlock's
        # primary armament, so it always takes the main hand. pact_weapon=True drives the CHA
        # attack/damage + the pact-weapon rider gates.
        if "Warlock" in cl_map and 13 in (eldritch_invocations or []):
            current_weapons = list(self.combat.get_agent_weapons(self.bm, agent_idx))
            # Re-conjure when slot 0 isn't a proper pact blade. Guarding on the flag (not just the
            # name) self-heals legacy saves where "PactBlade" round-tripped without pact_weapon=True.
            if current_weapons and not (current_weapons[0].name == "PactBlade"
                                        and current_weapons[0].pact_weapon):
                current_weapons[0] = self._create_pact_blade_weapon()
                self.combat.set_agent_weapons(self.bm, agent_idx, current_weapons)

        # Soulknife Rogue (L3+): manifest Psychic Blades — a 1d6 Psychic finesse/thrown blade in the
        # main hand and a 1d4 off-hand blade (the bonus second blade). psychic_blade=True identifies
        # them for Homing Strikes / Rend Mind. (Manifesting on the Attack action is simplified to a
        # standing equip, like PactBlade.)
        stats_chk = self.combat.get_agent_stats(self.bm, agent_idx)
        current_weapons = list(self.combat.get_agent_weapons(self.bm, agent_idx))
        current_weapons, blades_changed = self._apply_psychic_blades(stats_chk, current_weapons)
        if blades_changed:
            self.combat.set_agent_weapons(self.bm, agent_idx, current_weapons)
            stats_chk.has_offhand_attack = True
            self.combat.set_agent_stats(self.bm, agent_idx, stats_chk)

        # Store NPC metadata if provided, and initialize spell uses via C++
        if npc_data:
            self._agent_meta[agent_idx] = npc_data
            # Initialize spell uses_max/uses_remaining in C++ from npc_spell_groups
            npc_spell_groups = npc_data.get("npc_spell_groups", {})
            if npc_spell_groups:
                groups_dict = {int(k): v for k, v in npc_spell_groups.items()}
                self.combat.init_npc_spell_groups(self.bm, agent_idx, groups_dict)
        elif agent_idx in self._agent_meta:
            del self._agent_meta[agent_idx]

        # Always-prepared class features (Divine Spark, Radiance of the Dawn, domain spells) follow
        # from class/level/subclass — re-grant onto the agent's current spells so they show up
        # without needing to reopen the spell picker.
        cpp_spells = list(self.combat.get_agent_spells(self.bm, agent_idx))
        self._grant_class_features(agent_idx, cpp_spells)
        self.combat.set_agent_spells(self.bm, agent_idx, cpp_spells)

        if agent_idx == self.selected_idx:
            self._update_reach()

    # ── Weapon callbacks & overlays ───────────────────────────────────────────

    def _on_weapon_done(self, agent_idx: int, weapons: list[dict]):
        """Called by WeaponDialog when the user clicks Done.

        `weapons` is a list of plain dicts (the WeaponDialog's internal format).
        Convert each to an rpg.Weapon and push the list into the C++ layer.
        """
        cpp_weapons = [_dict_to_weapon(d) for d in weapons]
        # Update has_offhand_attack based on whether any weapon is off-hand
        stats = self.combat.get_agent_stats(self.bm, agent_idx)
        offhand = any(d.get("off_hand", False) for d in weapons)
        # Re-manifest a Soulknife's Psychic Blades — the synthetic blade isn't in weapons.json, so the
        # Weapon dialog would otherwise overwrite slots 0/1 with whatever it holds (see _apply_psychic_blades).
        cpp_weapons, blades_changed = self._apply_psychic_blades(stats, cpp_weapons)
        if blades_changed:
            offhand = True
        self.combat.set_agent_weapons(self.bm, agent_idx, cpp_weapons)
        stats.has_offhand_attack = offhand
        self.combat.set_agent_stats(self.bm, agent_idx, stats)
        # Refresh attack overlay if this is the currently selected agent.
        if agent_idx == self.selected_idx:
            self._update_attack_overlay()

    def _update_attack_overlay(self):
        """Recompute attack-range overlays for the selected agent's weapons."""
        self._attack_cells_melee = []
        self._attack_cells_rnorm = []
        self._attack_cells_rlong = []
        idx = self.selected_idx
        if idx < 0 or idx >= len(self.bm.placed_agents):
            return
        weapons = self.combat.get_agent_weapons(self.bm, idx)   # list[rpg.Weapon] from C++
        if not weapons:
            return
        pt = self.bm.placed_agents[idx]
        # Same leak-guard as _update_reach: no attack-range paint for a concealed token.
        if self._npc_concealed_from_party(idx, pt):
            return
        melee_cells:  set[tuple[int, int]] = set()
        rnorm_cells:  set[tuple[int, int]] = set()
        rlongx_cells: set[tuple[int, int]] = set()  # long-range-only

        for w in weapons:
            if w.type == rpg.WeaponType.Melee:
                for c in self.bm.attack_target_cells(
                        pt.origin, pt.size, w.reach_ft):
                    melee_cells.add((c.col, c.row))
                # A Thrown melee weapon (javelin, handaxe, dagger) also reaches everything a
                # ranged weapon would: targeting past its reach hurls it (see _attack_is_a_throw),
                # so paint the throw's normal/long bands or the DM can't see where it can land.
                if w.thrown and w.quantity > 0:
                    for c in self.bm.attack_target_cells(
                            pt.origin, pt.size, w.normal_range_ft):
                        rnorm_cells.add((c.col, c.row))
                    for c in self.bm.attack_target_cells(
                            pt.origin, pt.size, w.long_range_ft):
                        if (c.col, c.row) not in rnorm_cells:
                            rlongx_cells.add((c.col, c.row))
            else:  # Ranged
                for c in self.bm.attack_target_cells(
                        pt.origin, pt.size, w.normal_range_ft):
                    rnorm_cells.add((c.col, c.row))
                for c in self.bm.attack_target_cells(
                        pt.origin, pt.size, w.long_range_ft):
                    if (c.col, c.row) not in rnorm_cells:
                        rlongx_cells.add((c.col, c.row))

        # Convert back to Cell-like objects (just store as (col,row) dicts
        # to avoid depending on rpg.Cell construction in a hot path).
        def _as_cells(s):
            return [rpg.Cell(c, r) for c, r in s]

        self._attack_cells_melee = _as_cells(melee_cells)
        self._attack_cells_rnorm = _as_cells(rnorm_cells)
        self._attack_cells_rlong = _as_cells(rlongx_cells)

    # ─────────────────────────────────────────────────────────────────────
    #  Combat widget helpers
    # ─────────────────────────────────────────────────────────────────────

    def _current_agent_idx(self) -> int:
        """Return the BattleMap index of the currently acting combatant, or -1."""
        if not self.combat_active or not self.initiative_order:
            return -1
        return self.initiative_order[self.turn_idx].agent_idx

    def _reset_movement(self, agent_idx: int):
        """Seed this turn's movement budgets from the agent's stats."""
        if 0 <= agent_idx < len(self.bm.placed_agents):
            stats  = self.combat.get_agent_stats(self.bm, agent_idx)
            cond   = self.combat.get_agent_conditions(self.bm, agent_idx)
            agent  = self.bm.placed_agents[agent_idx]
            walk   = stats.speed_walk
            fly    = stats.speed_fly
            swim   = stats.speed_swim
            burrow = stats.speed_burrow
            # Aura of Alacrity (Paladin Oath of Glory L7): +10 ft Speed while in a Glory paladin's aura
            # (the paladin itself always qualifies). Seed the agent's own budget so real moves get it.
            if self.combat.has_aura_of_alacrity(self.bm, agent_idx):
                walk += 10
            # World Tree Branches of the Tree: a failed save zeroes the target's Speed until end of turn
            # (canAgentMove also blocks the move); reflect it in the budget/overlay so the UI agrees.
            if cond.branches_speed_zeroed:
                walk = fly = swim = burrow = 0
            # Pass base speeds to init_movement; C++ getWalkRemaining() applies exhaustion penalty
            agent.init_movement(walk, fly, swim, burrow)
            # Update UI with exhaustion-adjusted remaining movement
            exhaustion_reduction = 5 * cond.exhaustion_level
            self.move_remaining_walk   = max(0, walk - exhaustion_reduction)
            self.move_remaining_fly    = max(0, fly - exhaustion_reduction)
            self.move_remaining_swim   = max(0, swim - exhaustion_reduction)
            self.move_remaining_burrow = max(0, burrow - exhaustion_reduction)
            if cond.exhaustion_level > 0:
                pass  # print(f"[_reset_movement] Agent {agent.name}: exhaustion_level={cond.exhaustion_level} (−{exhaustion_reduction}ft)")
                # print(f"  walk: {walk} → {self.move_remaining_walk}, fly: {fly} → {self.move_remaining_fly}, swim: {swim} → {self.move_remaining_swim}, burrow: {burrow} → {self.move_remaining_burrow}")
            else:
                pass  # print(f"[_reset_movement] Agent {agent.name}: exhaustion_level=0, walk={walk}, fly={fly}, swim={swim}, burrow={burrow}")
        else:
            self.move_remaining_walk   = 0
            self.move_remaining_fly    = 0
            self.move_remaining_swim   = 0
            self.move_remaining_burrow = 0
        # Default to Walk; fall back to first available type if walk speed is 0.
        if self.move_remaining_walk > 0:
            self.move_type = rpg.MovementType.Walk
        elif self.move_remaining_fly > 0:
            self.move_type = rpg.MovementType.Fly
        elif self.move_remaining_swim > 0:
            self.move_type = rpg.MovementType.Swim
        else:
            self.move_type = rpg.MovementType.Burrow
        self.last_movement_dist = 0
        self.jump_overlay_active = False
        self.jump_reachable_cells = set()

    def _toggle_jump_overlay(self):
        """Toggle the jump overlay visibility and recalculate if needed."""
        if self.jump_overlay_active:
            self.jump_overlay_active = False
            self.jump_reachable_cells = []
        else:
            self._update_jump_reachable()
            self.jump_overlay_active = True

    def _update_jump_reachable(self):
        """Calculate cells reachable by long jump from current agent."""
        self.jump_reachable_cells = []
        idx = self._current_agent_idx()
        if not (0 <= idx < len(self.bm.placed_agents)):
            return

        agent = self.bm.placed_agents[idx]
        stats = self.combat.get_agent_stats(self.bm, idx)
        strength = stats.str

        if strength <= 0:
            return

        # Determine if running or standing jump (based on most recent movement).
        # Reach is the Strength SCORE in feet (running) or half (standing).
        is_running_jump = self.last_movement_dist >= 10
        max_jump_ft = strength if is_running_jump else (strength // 2)

        # Otherworldly Leap (invocation 10): Jump spell always active → triple distance.
        if stats.character_class == rpg.CharacterClass.Warlock and stats.has_invocation(10):
            max_jump_ft *= 3

        # Convert feet → whole 5-ft squares, rounding UP (matches the engine's jump_agent), so
        # Str 8 → 8 ft → 2 squares (10 ft). Manhattan distance below is measured in squares.
        max_jump_cells = (max_jump_ft + 4) // 5

        # Calculate reachable cells (Manhattan distance from current position).
        # Jumping clears Chasm/Water but is blocked by walls, so exclude wall cells
        # (MovementType.Jump); the engine's jump_agent enforces the same on execution.
        origin = agent.origin
        size = agent.size
        cols, rows = self.bm.grid_cols, self.bm.grid_rows
        for dr in range(-max_jump_cells, max_jump_cells + 1):
            for dc in range(-max_jump_cells, max_jump_cells + 1):
                manhattan_dist = abs(dc) + abs(dr)
                if manhattan_dist == 0:
                    continue  # Can't jump to current cell
                if manhattan_dist > max_jump_cells:
                    continue

                tc, tr = origin.col + dc, origin.row + dr
                if not (0 <= tc < cols and 0 <= tr < rows):
                    continue
                target_cell = rpg.Cell(tc, tr)
                if self.bm.is_blocked(target_cell, size, rpg.MovementType.Jump):
                    continue  # landing cell is a wall — not a valid jump target
                self.jump_reachable_cells.append(target_cell)

    def _execute_jump(self, agent_idx: int, target_cell):
        """Execute a jump to the target cell, deducting movement."""
        if not (0 <= agent_idx < len(self.bm.placed_agents)):
            return

        # Refresh agent reference to ensure we have current position
        agent = self.bm.placed_agents[agent_idx]
        stats = self.combat.get_agent_stats(self.bm, agent_idx)

        # FLAG: Move to C++
        # Calculate jump distance for logging (from current position to target)
        jump_dist = (abs(target_cell.col - agent.origin.col) +
                     abs(target_cell.row - agent.origin.row)) * 5

        # Determine if running or standing jump based on most recent movement
        is_running = self.last_movement_dist >= 10

        # A jump may only be made while the bonus action is available (house rule: jumping
        # costs a Bonus Action in addition to movement).
        if self.bonus_used:
            self._combat_log_add(f"{agent.name}: Cannot jump — Bonus Action already used.")
            return

        # Execute jump (C++ handles all movement-budget deductions)
        if self.combat.jump_agent(self.bm, agent_idx, target_cell, is_running):
            self._flush_combat_log()  # Flush any spell effect damage messages
            # Update remaining movement values
            ag = self.bm.placed_agents[agent_idx]
            self.move_remaining_walk = ag.walk_remaining
            self.move_remaining_fly = ag.fly_remaining
            self.move_remaining_swim = ag.swim_remaining
            self.move_remaining_burrow = ag.burrow_remaining
            self.last_movement_dist = 0  # Reset run-up after jump
            self.bonus_used = True       # jumping spends the Bonus Action
            jump_type = "running" if is_running else "standing"
            self._combat_log_add(f"{agent.name}: {jump_type.capitalize()} long jump (+{jump_dist}ft, Bonus Action)")
            self._update_reach()
            # The bonus action is spent — close the jump overlay (no second jump this turn).
            self.jump_overlay_active = False
            self.jump_reachable_cells = []
        else:
            # Jump failed - out of range or insufficient movement. Report the ceiling'd cap in
            # feet (Strength score → squares, rounded up) to match the engine's range check.
            strength = stats.str
            max_ft = strength if is_running else (strength // 2)
            max_cells = (max_ft + 4) // 5
            self._combat_log_add(f"{agent.name}: Jump out of range ({jump_dist}ft > {max_cells * 5}ft max)")

    def _start_combat(self):
        """Roll initiative and enter combat mode."""
        if not self.bm.placed_agents:
            return
        self._mark_fog_dirty()   # combat start: reveal from the party's opening positions
        order = list(self.combat.roll_initiative(self.bm))
        if not order:
            return
        # Superior Inspiration (Bard L18+): top up Bardic Inspiration to 2 at combat start.
        # RNG-free, so it doesn't perturb the dice stream; applied before recording begins
        # (replay.py mirrors this) so checked replays stay in sync.
        self.combat.apply_superior_inspiration(self.bm)
        self.initiative_order    = order
        self.combat_active       = True
        self.combat_paused       = False
        self.show_terrain        = True   # always show terrain during combat
        self.safe_target_edit_idx = -1  # exit any safe-target editing when combat starts
        self.turn_idx            = 0
        self.round_num           = 0
        self.initiative_scroll_offset = 0  # reset initiative scroll when combat starts
        self.combat_panel_scroll = 0       # combat panel opens at the top
        self._initiative_autopaged_turn = -1  # re-arm auto-paging for the new combat
        # Thief's Reflexes (Rogue Thief L17): a second turn during the first round at Initiative-10.
        self._apply_thief_reflexes()
        self.action_used          = False
        self.bonus_used           = False
        self.pending_attack_slot       = ""
        self.attacks_remaining         = 0
        self.pending_cleave            = None
        self.pending_sweep             = None
        self.pending_rally             = None
        self.pending_feint             = None
        self.pending_mantle_active     = False
        self.pending_mantle_targets    = []
        self.pending_beguiling         = False
        self.pending_beguiling_bard    = -1
        self.pending_clairvoyant       = False
        self.pending_vow_of_enmity     = False
        self.pending_inspiring_smite   = False
        self.pending_spell_slot        = ""
        self.pending_spell_is_aoe      = False
        self.pending_spell_num_targets = 0
        self.pending_spell_targets     = []
        self.pending_dispel_selection  = None
        self.pending_shove_slot        = ""
        self.pending_shove_type        = ""
        self.pending_grapple_slot      = ""
        self.pending_unarmed_type      = ""
        self.combat_log                = []
        # Initialize combat log file
        self._combat_log_file = "combat_log.txt"
        # Initialize replay log file. Header carries the seed; the RecordingCombat
        # wrapper then appends one JSON event per engine call (with a state snapshot)
        # for deterministic checked replay (see replay.py / replay_record.py).
        self.replay_log_file = "replay_log.txt"
        with open(self.replay_log_file, "w") as f:
            f.write(f"=== COMBAT REPLAY LOG ===\n")
            f.write(f"Checked replay:  python3 replay.py <map_image> [replay_log.txt]\n")
            f.write(f"\nSEED: {self.combat_seed}\n")
            f.write(f"INITIATIVE: {[(self.bm.placed_agents[e.agent_idx].name, e.total) for e in order]}\n")
            f.write(f"\n=== EVENTS (JSON) ===\n")
        # Begin recording every engine mutation through the wrapper.
        self.combat.start_recording(self.replay_log_file, self.bm)
        with open(self._combat_log_file, "w") as f:
            f.write("=== COMBAT LOG ===\n")
            f.write(f"Seed: {self.combat_seed}\n")
        self._effect_meta         = {}
        self.bm.clear_terrain_effects()
        # Apply armor multipliers for all agents at combat start
        for i in range(len(self.bm.placed_agents)):
            self.combat.apply_armor_multipliers(self.bm, i)
            # Clear the per-combat "has taken a turn" marker (drives Assassin's Assassinate
            # Advantage vs creatures that haven't acted yet). beginTurn re-sets it each turn.
            cond = self.combat.get_agent_conditions(self.bm, i)
            # Also clear Warrior of the Elements' Elemental Attunement (a per-encounter marker; the
            # unarmed damage override it sets is reset in initializeClassResources). Re-activate each combat.
            if cond.has_taken_turn_this_combat or cond.elemental_attunement_active:
                cond.has_taken_turn_this_combat = False
                cond.elemental_attunement_active = False
                self.combat.set_agent_conditions(self.bm, i, cond)
        first = self._current_agent_idx()
        print(f"[COMBAT START] Initiative order: {[(e.total, self.bm.placed_agents[e.agent_idx].name) for e in order]}")
        print(f"[COMBAT START] First turn: agent_idx={first}, name={self.bm.placed_agents[first].name if 0 <= first < len(self.bm.placed_agents) else '?'}")
        # Begin the first combatant's turn through the SAME path as every later turn
        # (_proceed_to_new_turn → begin_turn_flow → _finish_turn_start). This runs C++ beginTurn
        # (condition reset + movement-budget seed + turn-start reaction window) and, crucially, arms
        # the NPC-automation driver (_npc_drive_idx) for the first combatant. Hand-rolling the first
        # turn here used to skip all of that, so an automated NPC acting first would sit idle until
        # initiative wrapped back to it ("waited a round before acting").
        self._proceed_to_new_turn()

    def _agent_cr(self, idx: int):
        """Challenge Rating string for a placed agent, or None if unknown (PCs,
        custom-named tokens). Looks up the bestiary by name, stripping a trailing
        copy number ("Goblin 2" → "Goblin") added by _unique_agent_name."""
        if not (0 <= idx < len(self.bm.placed_agents)):
            return None
        name = self.bm.placed_agents[idx].name
        cr = self._cr_by_name.get(name)
        if cr is None:
            base = name.rsplit(" ", 1)
            if len(base) == 2 and base[1].isdigit():
                cr = self._cr_by_name.get(base[0])
        return cr

    def _award_encounter_xp(self):
        """Tally XP for enemies of the party defeated since the last tally, log the
        award, and roll it into the session's cumulative party total. Called when
        combat ends. Awards are per-corpse-once (see _xp_awarded_agents)."""
        newly_crs = []          # CRs of enemies defeated this combat
        for i, pt in enumerate(self.bm.placed_agents):
            if i in self._xp_awarded_agents:
                continue
            if pt.faction == PC_FACTION:
                continue        # party members / their summons never grant XP
            # Defeated = dead corpse or dropped to 0 HP.
            down = pt.conditions.dead or \
                self.combat.get_agent_stats(self.bm, i).hp_cur <= 0
            if not down:
                continue
            cr = self._agent_cr(i)
            if cr is None:
                continue        # no CR on record → not a rated monster, skip
            newly_crs.append(cr)
            self._xp_awarded_agents.add(i)

        if not newly_crs:
            return
        old_total = self._party_xp_total()
        result = compute_encounter_xp(newly_crs)
        self.party_xp_earned += result["total_xp"]
        new_total = self._party_xp_total()
        mult = result["multiplier"]
        mult_str = "" if abs(mult - 1.0) < 1e-6 else f" ×{mult:g}"
        self._combat_log_add(
            f"⚔ XP earned: {result['total_xp']} "
            f"({result['count']} defeated, {result['base_xp']} base{mult_str}) "
            f"— party total {new_total}")
        self._announce_level_ups(old_total, new_total)

    def _ensure_xp_baseline(self) -> int:
        """Lock the XP tracker's starting point to the party's current level the
        first time a party is known, so the running total begins at the characters'
        level — the XP already required to reach it — rather than 0. Frozen once
        set, so later manual level-ups don't re-inflate it. Uses the lowest PC
        level so no member is overstated and no spurious level-up is announced for
        a higher-level member."""
        if self.party_xp_baseline is None:
            levels = []
            for i, pt in enumerate(self.bm.placed_agents):
                if pt.faction != PC_FACTION:
                    continue
                stats = self.combat.get_agent_stats(self.bm, i)
                if getattr(stats, "is_npc", False):
                    continue        # PC-faction summons/pets are not characters
                levels.append(stats.char_level)
            if levels:
                self.party_xp_baseline = xp_for_level(min(levels))
        return self.party_xp_baseline or 0

    def _party_xp_total(self) -> int:
        """Cumulative party XP shown by the tracker: the level-baseline (the party's
        starting level) plus XP earned from enemies defeated this session."""
        return self._ensure_xp_baseline() + self.party_xp_earned

    def _announce_level_ups(self, old_total: int, new_total: int):
        """If the party's cumulative XP just crossed one or more Character
        Advancement thresholds (SRD 5.2), pop up a message naming every party
        member (PC) who is now eligible to gain a level. A PC can advance when
        the party's XP total reaches the threshold for the level above their
        current char_level. Purely advisory — leveling itself stays manual."""
        # No new tier crossed → nothing to announce (avoids repeat popups).
        if level_for_xp(new_total) <= level_for_xp(old_total):
            return
        eligible = []          # (name, current_level, attainable_level)
        for i, pt in enumerate(self.bm.placed_agents):
            if pt.faction != PC_FACTION:
                continue        # only actual party members level up
            stats = self.combat.get_agent_stats(self.bm, i)
            if getattr(stats, "is_npc", False):
                continue        # PC-faction summons/pets are not characters
            cur = stats.char_level
            attainable = level_for_xp(new_total)
            if attainable > cur:
                eligible.append((pt.name, cur, attainable))

        if not eligible:
            return
        lines = ["⭐ Level Up!",
                 f"Party XP total {new_total:,} reached a new tier."]
        for name, cur, attainable in eligible:
            need = xp_for_level(attainable)
            lines.append(f"{name}: level {cur} → {attainable}  (needs {need:,} XP)")
            self._combat_log_add(
                f"⭐ {name} can advance to level {attainable} "
                f"(party XP {new_total:,} ≥ {need:,}).")
        self._modal_message(lines)

    def _end_combat(self):
        """Leave combat mode and clear all combat state."""
        # Award XP for enemies defeated this combat before combat state is cleared.
        self._award_encounter_xp()
        self.move_remaining_walk   = 0
        self.move_remaining_fly    = 0
        self.move_remaining_swim   = 0
        self.move_remaining_burrow = 0
        self.move_type             = rpg.MovementType.Walk
        self.combat_active         = False
        self.combat_paused         = False
        self.initiative_order    = []
        self.initiative_scroll_offset = 0  # reset scroll when combat ends
        self.combat_panel_scroll = 0
        self.turn_idx            = 0
        self.round_num           = 0
        self.action_used          = False
        self.bonus_used           = False
        self.pending_attack_slot       = ""
        self.attacks_remaining         = 0
        self.pending_cleave            = None
        self.pending_sweep             = None
        self.pending_rally             = None
        self.pending_feint             = None
        self.pending_mantle_active     = False
        self.pending_mantle_targets    = []
        self.pending_beguiling         = False
        self.pending_beguiling_bard    = -1
        self.pending_clairvoyant       = False
        self.pending_vow_of_enmity     = False
        self.pending_inspiring_smite   = False
        self.pending_spell_slot        = ""
        self.pending_spell_is_aoe      = False
        self.pending_spell_num_targets = 0
        self.pending_spell_targets     = []
        self.pending_dispel_selection  = None
        self.pending_shove_slot        = ""
        self.pending_shove_type        = ""
        self.pending_grapple_slot      = ""
        self.pending_unarmed_type      = ""
        self.selected_idx              = -1
        self._reach_walk         = []
        self._reach_fly          = []
        self._reach_set          = set()
        self._effect_meta         = {}
        self._spell_metadata      = {}
        self.combat.clear_all_concentration(self.bm)  # drop lingering concentration on all agents
        self.combat.stop_recording()                  # finish the replay event log
        self.bm.clear_terrain_effects()
        self.bm.clear_spell_effects()
        self._attack_cells_melee = []
        self._attack_cells_rnorm = []
        self._attack_cells_rlong = []

    # ── On Deck (phased-battle reinforcements) ─────────────────────────────
    def _on_deck_groups(self):
        """Reserves grouped by name, in first-placed order: list of (name, count).
        Tombstoned (dismissed) agents are excluded."""
        groups = {}          # name -> count
        order  = []          # names in first-seen order
        for i, pt in enumerate(self.bm.placed_agents):
            if pt.removed_from_play or not self.bm.is_agent_on_deck(i):
                continue
            if pt.name not in groups:
                order.append(pt.name)
                groups[pt.name] = 0
            groups[pt.name] += 1
        return [(nm, groups[nm]) for nm in order]

    def _deploy_on_deck_group(self, name):
        """Bring an on-deck reinforcement group (all reserves sharing `name`) into the
        battle. Clears their on-deck flag; if combat is live, every member shares ONE
        freshly-rolled Initiative (the 'same type → same roll' rule) and is inserted into
        the order without disturbing the current actor or existing summon adjacencies."""
        idxs = [i for i, pt in enumerate(self.bm.placed_agents)
                if not pt.removed_from_play and self.bm.is_agent_on_deck(i)
                and pt.name == name]
        self._deploy_on_deck_idxs(idxs, name)

    def _deploy_on_deck_idxs(self, idxs, label):
        """Bring a specific set of on-deck reserve agents into the battle (the shared core
        of group Deploy and per-mob Recall). Clears their on-deck flag; if combat is live,
        the whole set shares ONE freshly-rolled Initiative and is inserted into the order
        without disturbing the current actor or existing summon adjacencies. `label` is the
        display name used only in the combat log."""
        idxs = [i for i in idxs
                if 0 <= i < len(self.bm.placed_agents)
                and not self.bm.placed_agents[i].removed_from_play
                and self.bm.is_agent_on_deck(i)]
        if not idxs:
            return
        name = label
        for i in idxs:
            self.bm.set_agent_on_deck(i, False)

        if self.combat_active and self.initiative_order:
            cur_aidx = self._current_agent_idx()   # preserve whose turn it is
            base = self.combat.roll_initiative_for(self.bm, idxs[0])
            total = base.total
            # Insert just before the first existing entry with a strictly lower total,
            # so the group acts after equal-or-higher combatants (a partial sorted insert
            # that leaves summon-after-summoner adjacencies intact).
            pos = len(self.initiative_order)
            for p, e in enumerate(self.initiative_order):
                if e.total < total:
                    pos = p
                    break
            new_entries = []
            for i in idxs:
                e = rpg.InitiativeEntry()
                e.agent_idx = i
                e.d20       = base.d20
                e.modifier  = base.modifier
                e.total     = total
                new_entries.append(e)
            self.initiative_order[pos:pos] = new_entries
            # Re-point turn_idx at the same actor (its list position may have shifted).
            self.turn_idx = next((p for p, e in enumerate(self.initiative_order)
                                  if e.agent_idx == cur_aidx), self.turn_idx)
            self._combat_log_add(
                f"⚔ Reinforcements deploy: {name} ×{len(idxs)} (Initiative {total}).")
        else:
            self._combat_log_add(
                f"{name} ×{len(idxs)} removed from On Deck — will roll Initiative at combat start.")

    # ── Thief's Reflexes (Rogue Thief L17) ─────────────────────────────────
    def _apply_thief_reflexes(self):
        """Insert a second initiative entry at (Initiative - 10) for each Thief L17+ so it takes
        two turns during the first round. The bonus entries are removed once round 1 ends
        (_remove_thief_reflexes, called from _advance_turn). Pure GUI initiative manipulation —
        no engine call, so it does not affect checked replay."""
        self._thief_reflexes_extra = {}   # agent_idx -> reduced total (the bonus entry to drop)
        if not self.initiative_order:
            return
        pending = []
        for e in list(self.initiative_order):
            if e.agent_idx in self._thief_reflexes_extra:
                continue
            st = self.combat.get_agent_stats(self.bm, e.agent_idx)
            if (st.character_class == rpg.CharacterClass.Rogue
                    and st.rogue_subclass == rpg.RogueSubclass.Thief
                    and st.char_level >= 17):
                reduced = e.total - 10
                self._thief_reflexes_extra[e.agent_idx] = reduced
                pending.append((e.agent_idx, e.d20, e.modifier, reduced))
        for aidx, d20, mod, total in pending:
            ne = rpg.InitiativeEntry()
            ne.agent_idx = aidx
            ne.d20       = d20
            ne.modifier  = mod
            ne.total     = total
            # Sorted insert: just before the first entry with a strictly lower total.
            pos = len(self.initiative_order)
            for p, x in enumerate(self.initiative_order):
                if x.total < total:
                    pos = p
                    break
            self.initiative_order[pos:pos] = [ne]
            nm = self.bm.placed_agents[aidx].name if 0 <= aidx < len(self.bm.placed_agents) else "?"
            self._combat_log_add(f"{nm}: Thief's Reflexes — extra turn this round at Initiative {total}.")

    def _remove_thief_reflexes(self):
        """Drop the bonus first-round turns and re-point turn_idx at the current actor."""
        if not getattr(self, "_thief_reflexes_extra", None):
            return
        cur_aidx = self._current_agent_idx()
        to_drop = dict(self._thief_reflexes_extra)   # agent_idx -> reduced total (drop one each)
        new_order = []
        for e in self.initiative_order:
            if e.agent_idx in to_drop and e.total == to_drop[e.agent_idx]:
                del to_drop[e.agent_idx]   # remove exactly the one bonus (reduced-total) entry
                continue
            new_order.append(e)
        self.initiative_order = new_order
        self._thief_reflexes_extra = {}
        if self.initiative_order:
            self.turn_idx = next((p for p, e in enumerate(self.initiative_order)
                                  if e.agent_idx == cur_aidx), 0)
        else:
            self.turn_idx = 0

    def _advance_turn(self):
        """Advance to the next living combatant in initiative order."""
        if not self.initiative_order:
            return
        self._mark_fog_dirty()   # lights tick + positions settle at each turn boundary
        # The new combatant's action buttons are at the top of the panel, and their panel
        # may be far shorter than the outgoing one — start each turn at the top.
        self.combat_panel_scroll = 0
        n = len(self.initiative_order)
        prev_turn_idx = self.turn_idx
        prev_idx = self._current_agent_idx()

        # FLAG: Move to C++
        # Find next living agent (skip only if actually dead, not just unconscious at 0 HP)
        for _ in range(n):
            self.turn_idx = (self.turn_idx + 1) % n
            idx = self._current_agent_idx()
            if 0 <= idx < len(self.bm.placed_agents):
                # Tombstoned summons (dismissed on concentration loss) never take a turn.
                if self.bm.is_agent_removed_from_play(idx):
                    continue
                stats = self.combat.get_agent_stats(self.bm, idx)
                cond = self.combat.get_agent_conditions(self.bm, idx)
                # Skip only if dead; unconscious agents at 0 HP still get a turn for death saves
                if stats.hp_cur > 0 or (stats.hp_cur <= 0 and not cond.dead):
                    break
                else:
                    # Agent is dead, drop concentration if any
                    self._drop_concentration_for_agent(idx)

        # FLAG: Move to C++
        # Round advancement: when turn_idx wraps to 0
        if self.turn_idx < prev_turn_idx:
            self.round_num += 1
            # Thief's Reflexes: the bonus first-round turns expire once round 1 ends.
            if self.round_num == 1 and getattr(self, "_thief_reflexes_extra", None):
                self._remove_thief_reflexes()
            # Tick DM-placed effects at round boundary
            expired_dm = self.bm.tick_dm_terrain_effects()
            for effect_id in expired_dm:
                if effect_id in self._effect_meta:
                    effect_name = self._effect_meta[effect_id].get("name", "Effect")
                    self._combat_log_add(f"{effect_name} fades.")
                    del self._effect_meta[effect_id]

        # End previous agent's turn
        if prev_idx >= 0:
            prev_name = self.bm.placed_agents[prev_idx].name if prev_idx < len(self.bm.placed_agents) else "Unknown"
            self._combat_log_add(f"[END TURN] {prev_name}")
            self.combat.end_turn(self.bm, prev_idx)

        # Legendary Actions: after an (enemy) creature's turn ends, every eligible legendary
        # creature may spend a legendary action (or pass). This phase is interactive — it may park
        # on modal menus / target picks / a Dash move — so the new turn only begins once the phase
        # completes, via _proceed_to_new_turn (the queue-drain continuation).
        self._begin_legendary_phase(prev_idx)

    def _proceed_to_new_turn(self):
        """Begin the next combatant's turn. Runs after _advance_turn ends the previous turn and the
        legendary-action phase (if any) finishes draining."""
        # Reset action economy and per-turn conditions for the new combatant.
        self.action_used           = False
        self.bonus_used            = False
        self.pending_attack_slot       = ""
        self.attacks_remaining         = 0
        self._attack_sequence_slot     = ""
        self.pending_spell_slot        = ""
        self.pending_spell_is_aoe      = False
        self.pending_spell_num_targets = 0
        self.pending_spell_targets     = []
        self.pending_shove_slot        = ""
        self.pending_shove_type        = ""
        self.pending_grapple_slot      = ""
        self.pending_unarmed_type      = ""
        self.arcane_charge_pending       = False
        self.blink_steps_pending         = False
        self.pending_psychic_teleport    = False
        self.pending_wild_magic_teleport = False
        self.pending_warping_implosion   = False
        self.pending_steps_of_fey        = False
        self.pending_misty_escape        = False
        self.pending_bewitching_misty    = False
        self.pending_invoke_duplicity    = False
        self.pending_duplicity_remaining = 0
        self._duplicity_cd_pending     = False
        self.pending_move_duplicity    = False
        self.move_duplicity_idx        = -1
        self.pending_swap_duplicity    = False
        self._reaction_mover_idx       = -1
        # World Tree Vitality of the Tree: this turn-start target-pick must not leak across turns.
        # If the player picked the option last turn but never clicked a valid target, the flag would
        # otherwise stay armed and swallow every later agent click into _resolve_vitality_target
        # (re-printing "Pick a living creature within 10 ft" forever). Clear it defensively here.
        if self.pending_vitality_target or self._vitality_option_index != -1:
            print(f"[VITALITY] turn-start clearing stale state "
                  f"(pending={self.pending_vitality_target}, opt={self._vitality_option_index})")
        self.pending_vitality_target   = False
        self._vitality_option_index    = -1
        # College of Glamour Beguiling Magic: the post-cast "click a creature" offer must not leak
        # across turns. If the bard cast a qualifying Enchantment/Illusion spell but never clicked a
        # target (nor pressed Esc), the flag would otherwise stay armed and swallow the next creature
        # click on a later turn into _beguiling_pick_target — the offer appearing to "show up on the
        # next action." The window is immediate-only, so clear it defensively at every turn start.
        self.pending_beguiling         = False
        self.pending_beguiling_bard    = -1

        # Begin new agent's turn (conditions reset + movement seed now happen in C++). The turn start
        # opens the OnTurnStartNearby reaction window (Branches of the Tree) via the
        # flow-checkpoint API; the rest of the turn-start work runs in _finish_turn_start once any
        # reactions resolve (parked windows resume through _submit_reaction → _reaction_finish).
        new_idx = self._current_agent_idx()
        self.selected_idx = new_idx
        if new_idx < 0:
            self._update_reach()
            self._update_attack_overlay()
            return
        self._turn_start_idx  = new_idx
        self._reaction_finish = self._finish_turn_start
        status = self.combat.begin_turn_flow(self.bm, new_idx, True)
        self._flush_combat_log()
        if status == rpg.FlowStatus.AwaitingDecision and self.combat.pending_decision().active:
            self._show_pending_reaction_menu()   # _submit_reaction → _finish_turn_start on completion
            return
        self._finish_turn_start()

    # ── Legendary Actions ──────────────────────────────────────────────────────
    # After a creature's turn ends, each legendary creature that is its enemy and still has
    # legendary actions left may spend one (or pass), repeatedly, until it passes or runs out.
    # Actions are driven entirely from the GUI: an attack-named option reuses begin_attack (with the
    # legendary creature as the explicit attacker), and Dash/DashHalf seed an out-of-turn movement
    # budget and reuse the normal drag-to-move flow. The budget resets at the creature's own turn
    # start (C++ beginTurn). The phase is a continuation of _advance_turn → _proceed_to_new_turn.

    def _legendary_action_names_for(self, idx: int, st) -> list:
        """The list of legendary-action option names to offer creature idx. Uses the explicit
        bestiary action_names when present; otherwise falls back to a sensible default so any
        creature with legendary actions is still usable: each distinct named weapon (resolved as an
        attack) plus a half-speed move."""
        names = [n for n in st.legendary_action_names if str(n).strip()]
        if names:
            return names
        out, seen = [], set()
        for w in self.combat.get_agent_weapons(self.bm, idx):
            nm = (w.name or "").strip()
            if nm and nm.lower() not in seen:
                seen.add(nm.lower()); out.append(nm)
        out.append("DashHalf")
        return out

    def _legendary_eligible(self, idx: int, prev_idx: int) -> bool:
        """True if creature idx may take a legendary action after prev_idx's turn ended."""
        agents = self.bm.placed_agents
        if not (0 <= idx < len(agents)) or idx == prev_idx:
            return False
        if self.bm.is_agent_removed_from_play(idx):
            return False
        # On-deck reserves are out of the fight (not in initiative) → no legendary
        # actions until the DM deploys them.
        if self.bm.is_agent_on_deck(idx):
            return False
        try:
            st = self.combat.get_agent_stats(self.bm, idx)
        except Exception:
            return False
        if not getattr(st, "has_legendary_actions", False):
            return False
        if st.legendary_actions_current <= 0 or st.hp_cur <= 0:
            return False
        # Legendary actions fire after an *enemy's* turn (not an ally's).
        return not self._are_allies(idx, prev_idx)

    def _begin_legendary_phase(self, prev_idx: int):
        """Build the queue of legendary creatures eligible after prev_idx's turn, then drain it.
        Falls straight through to the new turn when nothing is eligible (the common case)."""
        self._legendary_queue = []
        self._legendary_actor = -1
        self._legendary_target_pick = False
        self._legendary_move_active = False
        if self.combat_active and prev_idx >= 0:
            for i in range(len(self.bm.placed_agents)):
                if self._legendary_eligible(i, prev_idx):
                    self._legendary_queue.append(i)
        self._offer_next_legendary()

    def _offer_next_legendary(self):
        """Show the front-of-queue legendary creature its action menu, skipping any that are no
        longer eligible. When the queue empties, begin the next combatant's turn."""
        while self._legendary_queue:
            idx = self._legendary_queue[0]
            agents = self.bm.placed_agents
            if not (0 <= idx < len(agents)) or self.bm.is_agent_removed_from_play(idx):
                self._legendary_queue.pop(0); continue
            st = self.combat.get_agent_stats(self.bm, idx)
            if st.hp_cur <= 0 or st.legendary_actions_current <= 0:
                self._legendary_queue.pop(0); continue
            self._legendary_actor = idx
            self._show_legendary_action_menu(idx, st)
            return
        self._legendary_actor = -1
        self._proceed_to_new_turn()

    def _show_legendary_action_menu(self, idx: int, st):
        """Context menu for creature idx: one entry per available action name + Pass."""
        name = self.bm.placed_agents[idx].name
        remaining = st.legendary_actions_current
        self._combat_log_add(
            f"{name}: {remaining} legendary action(s) available — choose one or pass.")
        self._flush_combat_log()
        options = [(a, (lambda a=a: self._choose_legendary_action(a)))
                   for a in self._legendary_action_names_for(idx, st)]
        options.append((f"Pass ({remaining} left)", self._pass_legendary))
        px, py = self._agent_screen_pos(idx)
        self.context_menu.show((px, py), options, self.screen.get_size())

    def _pass_legendary(self):
        """The current legendary creature declines further actions; move to the next in the queue."""
        if self._legendary_queue:
            self._legendary_queue.pop(0)
        self._legendary_actor = -1
        self._offer_next_legendary()

    def _spend_legendary_action(self, idx: int) -> int:
        """Decrement the creature's per-round legendary-action budget; return the remaining count."""
        st = self.combat.get_agent_stats(self.bm, idx)
        st.legendary_actions_current = max(0, st.legendary_actions_current - 1)
        self.combat.set_agent_stats(self.bm, idx, st)
        return st.legendary_actions_current

    def _after_legendary_action(self, idx: int):
        """A creature may take only ONE legendary action per turn-end window. Drop it from the queue
        after it acts and move on to the next eligible creature (or the new turn). Its remaining
        budget (legendary_actions_current) still lets it act again after the NEXT creature's turn,
        since the queue is rebuilt at every turn end (_begin_legendary_phase)."""
        if self._legendary_queue and self._legendary_queue[0] == idx:
            self._legendary_queue.pop(0)
        self._legendary_actor = -1
        self._offer_next_legendary()

    def _choose_legendary_action(self, action_name: str):
        """Dispatch a chosen legendary action: Dash/DashHalf → movement; otherwise treat the name as
        a weapon attack (matched by weapon name) and enter target-pick mode."""
        idx = self._legendary_actor
        if idx < 0 or idx >= len(self.bm.placed_agents):
            self._offer_next_legendary(); return
        key = action_name.strip().lower()
        if key in ("dash", "dashhalf", "dash half"):
            self._begin_legendary_dash(idx, half=(key != "dash"))
            return
        # Attack-type: find the matching weapon by (case-insensitive) name.
        weapons = self.combat.get_agent_weapons(self.bm, idx)
        widx = next((i for i, w in enumerate(weapons)
                     if w.name.strip().lower() == key), -1)
        if widx < 0:
            self._combat_log_add(
                f"{self.bm.placed_agents[idx].name}: no weapon matches legendary action "
                f"'{action_name}' — pick another or pass.")
            self._flush_combat_log()
            self._offer_next_legendary()   # re-show the menu; the action isn't consumed
            return
        if not self._weapon_usable(weapons[widx]):
            why = "recharging" if weapons[widx].expended else "out of uses"
            self._combat_log_add(
                f"{self.bm.placed_agents[idx].name}: {action_name} is {why} — pick another or pass.")
            self._flush_combat_log()
            self._offer_next_legendary()   # re-show the menu; the action isn't consumed
            return
        self._legendary_attack_name = action_name
        self._legendary_attack_widx = widx
        self._legendary_target_pick = True
        self._combat_log_add(
            f"{self.bm.placed_agents[idx].name}: click a target for legendary {action_name}.")
        self._flush_combat_log()

    def _resolve_legendary_attack(self, target_idx: int):
        """Resolve the pending legendary attack against target_idx via begin_attack (explicit
        attacker), reusing the full to-hit / Shield / on-hit pipeline. Spends one legendary action."""
        idx = self._legendary_actor
        agents = self.bm.placed_agents
        if idx < 0 or idx >= len(agents):
            self._legendary_target_pick = False
            self._offer_next_legendary(); return
        if not (0 <= target_idx < len(agents)) or target_idx == idx:
            self._combat_log_add("Pick a valid target.")
            self._flush_combat_log()
            return  # keep target-pick armed
        if self.combat.get_agent_stats(self.bm, target_idx).hp_cur <= 0:
            self._combat_log_add("Target is already down — pick another.")
            self._flush_combat_log()
            return
        self._legendary_target_pick = False
        widx = self._legendary_attack_widx
        action = rpg.Attack(idx, target_idx, widx)
        action.attack_slot = "legendary"   # resolves like a normal attack; no turn-economy cost
        # The attempt costs one legendary action regardless of hit/miss.
        self._spend_legendary_action(idx)
        self._reaction_finish = lambda i=idx: self._finish_legendary_attack(i)
        status = self.combat.begin_attack(self.bm, action)
        self._flush_combat_log()
        if status == rpg.FlowStatus.AwaitingDecision:
            self._show_pending_reaction_menu()   # target's Shield etc.; resumes via _reaction_finish
        else:
            self._finish_legendary_attack(idx)

    def _finish_legendary_attack(self, idx: int):
        """Post-resolution of a legendary attack (immediate or after a defender reaction window).
        The hit/miss, damage and on-hit riders were applied in C++; just refresh and re-offer."""
        self._flush_combat_log()
        self._sync_spell_effect_cache()
        self._update_attack_overlay()
        self._after_legendary_action(idx)

    def _begin_legendary_dash(self, idx: int, half: bool):
        """Seed an out-of-turn movement budget for a legendary Dash (full Speed) or DashHalf (half
        Speed) and enter a legendary-move mode that reuses the normal drag-to-move flow. One
        committed move resolves the action; the creature is then re-offered."""
        st = self.combat.get_agent_stats(self.bm, idx)
        div = 2 if half else 1
        walk   = st.speed_walk   // div
        fly    = st.speed_fly    // div
        swim   = st.speed_swim   // div
        burrow = st.speed_burrow // div
        # Seed BOTH budgets: agent-side init_movement drives the reachable-cell overlay; the
        # engine-side seed_move_budgets drives begin_move's spend/clamp. beginTurn was not called
        # for this out-of-turn creature, so neither would otherwise be set.
        self.bm.placed_agents[idx].init_movement(walk, fly, swim, burrow)
        self.combat.seed_move_budgets(idx, walk, fly, swim, burrow)
        self.selected_idx          = idx
        self.move_remaining_walk   = walk
        self.move_remaining_fly    = fly
        self.move_remaining_swim   = swim
        self.move_remaining_burrow = burrow
        self.move_type = (rpg.MovementType.Walk if walk > 0 else
                          rpg.MovementType.Fly if fly > 0 else
                          rpg.MovementType.Swim if swim > 0 else
                          rpg.MovementType.Burrow)
        self._legendary_move_active = True
        self._spend_legendary_action(idx)   # the Dash costs one legendary action
        label = "DashHalf (move up to half Speed)" if half else "Dash (move up to full Speed)"
        self._combat_log_add(f"{self.bm.placed_agents[idx].name}: {label} — drag it to move.")
        self._flush_combat_log()
        self._update_reach()
        self._update_attack_overlay()

    def _finish_turn_start(self):
        """Continuation of _advance_turn after the OnTurnStartNearby reaction window closes
        (begin_turn_flow). Reads the stored TurnStartResult and runs the rest of the turn-start work."""
        new_idx = self._turn_start_idx
        if new_idx < 0 or new_idx >= len(self.bm.placed_agents):
            self._update_reach()
            self._update_attack_overlay()
            return
        turn_result = self.combat.last_turn_start_result()

        # Tick conditions cast by this agent (duration counted in this agent's turns, not absolute turns)
        self.combat.tick_agent_conditions_for_caster(self.bm, new_idx)

        # Log any save rolls (e.g., paralyzed escape attempt)
        if turn_result.save_roll_message:
            self._combat_log_add(f"{self.bm.placed_agents[new_idx].name}: {turn_result.save_roll_message}")

        # If turn was skipped (e.g., paralyzed save failed), advance to next turn
        if turn_result.turn_skipped:
            self._advance_turn()
            return

        # Initialize Python-side movement tracking (C++ also seeds in beginTurn)
        self._reset_movement(new_idx)

        # Tick this agent's terrain in C++ (also clears concentration if a concentration terrain expired)
        tick = self.combat.tick_terrain_for_turn(self.bm, new_idx)
        for effect_id in tick.expired_terrain_ids:
            if effect_id in self._effect_meta:
                effect_name = self._effect_meta[effect_id].get("name", "Effect")
                self._combat_log_add(f"{effect_name} fades.")
                del self._effect_meta[effect_id]
        if tick.concentration.dropped:
            self._sync_spell_effect_cache()
            conc_name = self.bm.placed_agents[new_idx].name
            self._combat_log_add(f"{conc_name}'s {tick.concentration.spell_name or 'spell'} effect expired.")

        # Phase 3: Tick light effects (Darkness, fog spells) at turn start
        self.combat.tick_light_effects_for_turn(self.bm, new_idx)

        self._update_reach()
        self._update_attack_overlay()

        # NPC automation: if this agent is engine-driven (and actually in initiative, not an On Deck
        # reserve), arm the per-frame driver rather than recursing here. The main loop drives ONE
        # automated turn next frame so the board renders between automated turns.
        if (self.combat_active and self.bm.is_agent_npc_automated(new_idx)
                and not self.bm.is_agent_on_deck(new_idx)):
            self._npc_drive_idx = new_idx

    def _drive_npc_turn_if_pending(self):
        """Drive ONE automated NPC turn step this frame (NPC_AUTOMATION_PLAN Step 2). Called once per
        frame from the main loop. The C++ engine's run_npc_turn does all the deciding via the combat
        resolution primitives; Python snapshots display state first, then REPLAYS the turn's recorded
        visual events as an animation (see _npc_anim_start) before advancing the turn or relaying a
        parked human reaction/counter window. Never recurses through _finish_turn_start, so a run of
        automated NPCs renders one at a time and stays watchable."""
        if self._npc_anim is not None:
            return   # a playback is still running — its continuation advances the turn
        if self._npc_drive_idx < 0:
            return
        idx = self._npc_drive_idx
        self._npc_drive_idx = -1
        # The agent may have died / been removed between its turn-start and this frame.
        if not self.combat_active or idx < 0 or idx >= len(self.bm.placed_agents):
            return
        snapshot = self._npc_anim_snapshot()   # display state BEFORE the turn mutates the world
        status = self.combat.run_npc_turn(self.bm, idx)
        self._mark_fog_dirty()   # the automated turn moved tokens / opened doors / placed lights
        self._flush_combat_log()
        # Hidden-agent detection after the automated move (mirrors _after_move_committed's
        # check for manual moves — the C++ driver moves without the GUI move path). Without
        # this, a concealed automated NPC could walk into plain sight and stay undrawn
        # forever, since only attacking would ever clear its Hidden condition.
        if idx < len(self.bm.placed_agents) and self.bm.placed_agents[idx].conditions.hidden:
            detection_msg = self.combat.check_hidden_agent_detection(self.bm, idx, True)
            if detection_msg:
                self._combat_log_add(detection_msg)
        events = self.combat.take_npc_visual_events()
        if status == rpg.FlowStatus.AwaitingDecision and self.combat.pending_decision().active:
            # The NPC attempted an action; a human gets a reaction/counter window. When it closes,
            # re-arm the driver so run_npc_turn resumes next frame (one step per frame, still watchable).
            self._reaction_finish = lambda i=idx: self._resume_npc_turn(i)
            # Play what already happened FIRST — the human must SEE the provoking move/attack
            # before being asked to react to it — then open the parked reaction menu.
            if events:
                self._npc_anim_start(events, snapshot, on_done=self._show_pending_reaction_menu)
            else:
                self._show_pending_reaction_menu()
            return
        if events:
            self._npc_anim_start(events, snapshot, on_done=self._advance_turn)
        else:
            self._advance_turn()

    def _resume_npc_turn(self, idx: int):
        """Re-arm the NPC driver after a parked human reaction window closed mid-automated-turn."""
        self._npc_drive_idx = idx

    def _drop_concentration(self):
        """Drop concentration for the current agent (game logic in C++)."""
        self._drop_concentration_for_agent(self._current_agent_idx())

    def _drop_concentration_for_agent(self, agent_idx: int):
        """Drop concentration for an agent. Terrain/effect/condition removal lives in
        C++ drop_concentration; Python only refreshes the render cache and logs."""
        res = self.combat.drop_concentration(self.bm, agent_idx)
        if res.dropped:
            self._sync_spell_effect_cache()  # render cache only
            name = self.bm.placed_agents[agent_idx].name
            self._combat_log_add(f"{name} drops concentration on {res.spell_name or 'spell'}.")
            # Summons created by this caster were tombstoned (removed_from_play) in C++.
            # They stay in placedAgents_ to keep indices valid; we just log + un-render them.
            for s_idx in res.dismissed_summons:
                if 0 <= s_idx < len(self.bm.placed_agents):
                    self._combat_log_add(f"{self.bm.placed_agents[s_idx].name} vanishes.")


    def _combat_log_add(self, msg: str):
        self.combat_log.insert(0, msg)
        if len(self.combat_log) > 10:
            self.combat_log.pop()
        # Print to console
        print(msg)
        # Write to combat log file
        try:
            if not hasattr(self, '_combat_log_file'):
                self._combat_log_file = "combat_log.txt"
            with open(self._combat_log_file, "a") as f:
                f.write(msg + "\n")
        except Exception:
            pass  # Silently fail on file write errors

    def _flush_combat_log(self):
        """Flush messages from the combat engine logger into the combat log."""
        for msg in self.logger.flush():
            self._combat_log_add(msg)

    # FLAG: Move to C++
    def _drop_weapon(self, slot_idx: int):
        """Drop the equipped weapon in slot_idx onto the current agent's cell."""
        cur_idx = self._current_agent_idx()
        if cur_idx < 0:
            return
        weapons = list(self.combat.get_agent_weapons(self.bm, cur_idx))
        weapon = weapons[slot_idx]
        if not weapon.name or weapon.name == "Unnamed":
            return
        # Permanently-armed weapons (natural attacks, conjured/innate gear) cannot be dropped.
        if weapon.permanently_armed:
            self._combat_log_add(f"{self.bm.placed_agents[cur_idx].name} can't drop {weapon.name}.")
            return
        # Sprite: the Weapon now carries its own (so an engine-side drop — a THROW — lands with the
        # right icon too); fall back to the weapons.json catalog for one built before that field.
        wdict = self.weapon_name_to_dict.get(weapon.name, {})
        sprite_path = weapon.sprite_path or wdict.get("sprite_path", "")
        # Place item at agent's current cell
        agent = self.bm.placed_agents[cur_idx]
        print(f"[_drop_weapon] Dropping {weapon.name} from slot {slot_idx} for agent {agent.name} at ({agent.origin.col},{agent.origin.row})")
        print(f"[_drop_weapon DEBUG] weapon.permanently_armed = {weapon.permanently_armed}")
        item_id = self.bm.place_item(agent.origin, weapon, sprite_path)
        # Clear the weapon slot
        weapons[slot_idx] = rpg.Weapon()
        print(f"[_drop_weapon DEBUG] Before set_agent_weapons: weapons[{slot_idx}].name = '{weapons[slot_idx].name}'")
        self.combat.set_agent_weapons(self.bm, cur_idx, weapons)
        # Verify the slot was cleared
        weapons_after = list(self.combat.get_agent_weapons(self.bm, cur_idx))
        print(f"[_drop_weapon DEBUG] After set_agent_weapons: weapons_after[{slot_idx}].name = '{weapons_after[slot_idx].name}'")
        self._combat_log_add(f"{agent.name} drops {weapon.name}.")

    # FLAG: Move to C++
    def _show_item_pickup_menu(self, cell, items, agent_idx, pos):
        """Show context menu to pick up one of the items at this cell."""
        menu_items = []
        for item in items:
            def _pickup(i=item, a=agent_idx):
                self._pickup_item(i, a)
            menu_items.append((f"Pick up {item.weapon.name}", _pickup))
        if menu_items:
            self.context_menu.show(pos, menu_items, self.screen.get_size())

    def _pickup_item(self, item, agent_idx: int):
        """Take a weapon off the ground: pick the slot here, let the engine do the assignment.

        BattleMap::pickUpItem owns what happens to the weapon list — in particular, retrieving a
        thrown weapon you are still carrying re-joins the BUNDLE (pick up one of the javelins you
        threw and you hold 4 again, not two stacks) rather than consuming the slot we suggest. That
        rule lives in exactly one place; don't re-implement it here."""
        weapons = list(self.combat.get_agent_weapons(self.bm, agent_idx))
        agent = self.bm.placed_agents[agent_idx]
        name = item.weapon.name or "weapon"

        slot = self._find_pickup_slot(item.weapon, weapons)
        if not self.bm.pick_up_item(item.id, agent_idx, slot):
            self._combat_log_add(f"{agent.name} can't pick up {name}.")
            return

        held = next((w.quantity for w in self.combat.get_agent_weapons(self.bm, agent_idx)
                     if w.name == item.weapon.name and w.thrown), 0)
        if held > 1:
            self._combat_log_add(f"{agent.name} picks up {name} ({held} in hand).")
        else:
            self._combat_log_add(f"{agent.name} picks up {name}.")

    # FLAG: Move to C++
    def _show_item_context_menu(self, cell, items, pos):
        """DM right-click menu for dropped weapons on a cell: remove each item.
        (Relocation is done by left-click dragging the item — see the drag handlers.)"""
        menu_items = []
        for item in items:
            nm = item.weapon.name or "item"
            menu_items.append((f"Delete {nm}", lambda i=item: self._delete_item(i)))
        if menu_items:
            self.context_menu.show(pos, menu_items, self.screen.get_size())

    def _delete_item(self, item):
        """Remove a dropped weapon from the map entirely."""
        self.bm.remove_item(item.id)
        self._combat_log_add(f"Removed {item.weapon.name or 'item'} from the map.")

    # ── Doors ─────────────────────────────────────────────────────────────────
    def _cell_adjacent_to_agent(self, agent, cell) -> bool:
        """True if `cell` is within 5 ft (Chebyshev 1) of the agent's footprint."""
        dc = max(agent.origin.col - cell.col,
                 cell.col - (agent.origin.col + agent.size - 1), 0)
        dr = max(agent.origin.row - cell.row,
                 cell.row - (agent.origin.row + agent.size - 1), 0)
        return max(dc, dr) <= 1

    def _show_door_menu(self, cell, pos):
        """Context menu for a door cell: Open/Close (object interaction) and Pick Lock
        (an action). Knock is cast as a normal spell at the cell, not from here.

        During combat the acting creature must be adjacent; out of combat the DM acts
        freely (pick-lock uses the currently selected agent)."""
        di = self.bm.door_at(cell)
        if di < 0:
            return
        door = self.bm.doors[di]
        actor = self._current_agent_idx() if self.combat_active else self.selected_idx

        if self.combat_active:
            if actor < 0:
                return
            agent = self.bm.placed_agents[actor]
            # A wide door is reachable from any of its cells, not just the clicked one.
            if not any(self._cell_adjacent_to_agent(agent, c) for c in door.cells):
                self._combat_log_add("Move adjacent to the door to interact with it.")
                return

        options = []
        door_id = door.id
        if door.open:
            options.append(("Close door", lambda d=door_id: self._door_close(d)))
        else:
            if door.arcane_lock:
                options.append(("Locked (Arcane Lock — needs Knock/Dispel)",
                                lambda: self._combat_log_add(
                                    "The door is held by an Arcane Lock; only Knock or Dispel Magic opens it.")))
            elif door.locked:
                options.append((f"Pick Lock (DC {door.lock_dc})",
                                lambda a=actor, d=door_id: self._door_pick_lock(a, d)))
            else:
                options.append(("Open door", lambda d=door_id: self._door_open(d)))

        # Cross-map staple (Floors Phase 5): an open, linked door offers passage to the
        # abutting page. A locked/arcane-locked (thus closed) door blocks it — the option
        # only appears once the door is open. Explicit action, matching the ladder menu.
        link = self._door_link_at(door)
        if link is not None and door.open:
            options.append((f"Go through door (to floor {link[2]})",
                            lambda a=actor, d=door_id: self._use_door_link(d, a)))

        if options:
            self.context_menu.show(pos, options, self.screen.get_size())

    def _show_ladder_menu(self, cell, pos):
        """Context menu for a ladder cell: a "Use Ladder" action that carries the acting
        (or selected) creature to the target floor via the dungeon manifest.

        Out-of-combat only for the MVP (see Floors plan Known Limitations); the actual
        page switch is gated by _switch_to_page's combat guard, which flashes if in combat."""
        li = self._ladder_at(cell)
        if li < 0:
            return
        lad = self._ladders[li]
        X, Y, Z = lad["target"]
        actor = self._current_agent_idx() if self.combat_active else self.selected_idx

        if self.combat_active:
            agent = self.bm.placed_agents[actor] if actor >= 0 else None
            if agent is not None and not any(
                    self._cell_adjacent_to_agent(agent, rpg.Cell(c[0], c[1])) for c in lad["cells"]):
                self._combat_log_add("Move adjacent to the ladder to use it.")
                return

        label = f"Use Ladder (to floor {Z})"
        options = [(label, lambda a=actor, l=li: self._use_ladder(l, a))]
        self.context_menu.show(pos, options, self.screen.get_size())

    def _use_ladder(self, ladder_idx: int, actor_idx: int):
        """Resolve a ladder's global target to a page + local cell and switch to it,
        carrying the acting creature. No-ops with a flash if the dungeon isn't loaded
        or the target lands on no page."""
        if ladder_idx < 0 or ladder_idx >= len(self._ladders):
            return
        if self.dungeon is None:
            self._flash_status("Ladders need a dungeon manifest (open a .dungeon.json).")
            return
        X, Y, Z = self._ladders[ladder_idx]["target"]
        page = self.dungeon.page_at_global(X, Y, Z)
        if page is None:
            self._flash_status("The ladder leads nowhere (no map on that floor).")
            return
        local = page.global_to_local(X, Y, Z)
        if local is None:
            self._flash_status("The ladder's exit is off the target map.")
            return
        carry = [actor_idx] if actor_idx is not None and actor_idx >= 0 else None
        if self._switch_to_page(page, drop_cell=local, carry=carry):
            self._flash_status(f"Climbed to floor {Z}: {page.id}")

    def _door_by_id(self, door_id: int):
        """The rpg.Door with ``id == door_id`` on the active map, or None."""
        for d in self.bm.doors:
            if d.id == door_id:
                return d
        return None

    def _door_link_at(self, door):
        """The global ``[X, Y, Z]`` cross-map target for ``door`` (an rpg.Door), or None
        for an ordinary in-map door. Looked up by the door's cell footprint."""
        return self._door_links.get(door_link_key(door.cells))

    def _use_door_link(self, door_id: int, actor_idx: int):
        """Step through a linked door to the abutting page, carrying the acting (or
        selected) creature. Mirrors _use_ladder: resolve the global target to a page +
        local cell via the dungeon manifest and switch. No-ops with a flash if the
        dungeon isn't loaded or the target lands on no page."""
        if self.dungeon is None:
            self._flash_status("Door links need a dungeon manifest (open a .dungeon.json).")
            return
        door = self._door_by_id(door_id)
        if door is None:
            return
        link = self._door_link_at(door)
        if link is None:
            return
        X, Y, Z = link
        page = self.dungeon.page_at_global(X, Y, Z)
        if page is None:
            self._flash_status("The door leads nowhere (no map on that floor).")
            return
        local = page.global_to_local(X, Y, Z)
        if local is None:
            self._flash_status("The door's exit is off the target map.")
            return
        carry = [actor_idx] if actor_idx is not None and actor_idx >= 0 else None
        if self._switch_to_page(page, drop_cell=local, carry=carry):
            self._flash_status(f"Stepped through to {page.id} (floor {Z}).")

    def _after_door_change(self):
        """Refresh movement/attack overlays after a door's open state (and thus LOS and
        passability) changed."""
        self._mark_fog_dirty()   # a door opening/closing changes party LOS through it
        if self.selected_idx >= 0:
            self._update_reach()
            self._update_attack_overlay()

    def _door_open(self, door_id: int):
        if self.bm.open_door(door_id):
            self._combat_log_add("The door opens.")
        else:
            self._combat_log_add("The door is locked.")
        self._after_door_change()

    def _door_close(self, door_id: int):
        self.bm.close_door(door_id)
        self._combat_log_add("The door closes.")
        self._after_door_change()

    def _door_pick_lock(self, actor_idx: int, door_id: int):
        if actor_idx < 0:
            self._combat_log_add("No creature selected to pick the lock.")
            return
        if self.combat_active and self.action_used:
            self._combat_log_add("Action already used this turn — cannot pick the lock.")
            return
        res = self.combat.attempt_pick_lock(self.bm, actor_idx, door_id)
        if not res.valid:
            self._combat_log_add("Cannot pick this lock.")
            return
        self._combat_log_add(res.log_message)
        if self.combat_active:
            self.action_used = True
        self._after_door_change()

    def _pending_spell_opens_doors(self) -> bool:
        """True if the spell currently pending a target is a door-opener (Knock).

        Knock is a Single-geometry spell, but it targets a doorway CELL (no creature),
        so the cast must route through the cell-targeting path instead of requiring a hit."""
        if not self.pending_spell_slot:
            return False
        ci = self._current_agent_idx()
        if ci < 0:
            return False
        try:
            sp = self.combat.get_agent_spells(self.bm, ci)[self.pending_spell_idx]
            return getattr(sp, "opens_doors", False)
        except Exception:
            return False

    def _pending_spell_dispels_magic(self) -> bool:
        """True if the spell pending a target is a Dispel-Magic effect (dispels_magic flag).

        Dispel Magic is a Single-geometry spell that normally targets a creature, but it can
        also be aimed at a map CELL holding an ongoing area effect (Hunger of Hadar, Web, …) —
        that cell cast routes through the aoe path so the engine reads aoe_col/aoe_row."""
        if not self.pending_spell_slot:
            return False
        ci = self._current_agent_idx()
        if ci < 0:
            return False
        try:
            sp = self.combat.get_agent_spells(self.bm, ci)[self.pending_spell_idx]
            return getattr(sp, "dispels_magic", False)
        except Exception:
            return False

    def _begin_dispel_pick(self, hit, cell, pos):
        """Dispel Magic click: enumerate the dispellable ongoing spells at the aimed creature and/or
        cell and open a picker so the DM ends exactly one — a buff on an ally, a debuff on an enemy,
        or one of several overlapping AoEs. Casting is deferred until an entry is chosen; an empty
        target just logs and leaves the spell pending so the caster can re-aim."""
        caster = self._current_agent_idx()
        if caster < 0:
            return

        cands, seen = [], set()

        def _add(c_list):
            for c in c_list:
                key = (tuple(c.condition_ids), tuple(c.spell_effect_ids), tuple(c.terrain_ids))
                if key in seen:
                    continue
                seen.add(key)
                cands.append(c)

        if hit is not None and hit >= 0:
            # A creature: its own spell-applied effects, plus any area magic it stands in.
            _add(self.combat.dispel_candidates_on_agent(self.bm, caster, hit))
            oc = self.bm.placed_agents[hit].origin
            _add(self.combat.dispel_candidates_at_cell(self.bm, caster, oc.col, oc.row))
        elif cell is not None:
            _add(self.combat.dispel_candidates_at_cell(self.bm, caster, cell.col, cell.row))

        if not cands:
            self._combat_log_add("No magic to dispel there.")
            return

        agents = self.bm.placed_agents
        options = []
        for c in cands:
            owner = (agents[c.owner_idx].name
                     if 0 <= c.owner_idx < len(agents) else "?")
            side  = "ally" if c.owner_is_ally else "enemy"
            label = f"{c.label} — L{c.level}, {owner} ({side})"
            options.append((label, lambda cc=c, h=hit, cl=cell: self._cast_dispel_selection(cc, h, cl)))
        self.context_menu.show(pos, options, self.screen.get_size())

    def _cast_dispel_selection(self, candidate, hit, cell):
        """Commit the picked Dispel Magic target: stash its structure ids and route through the
        normal cast path (which spends the slot once and runs the OnDeclareCast reaction window).
        execute_spell reads the selection and ends only that spell (dispelSelected)."""
        self.pending_dispel_selection = dict(
            condition_ids    = list(candidate.condition_ids),
            spell_effect_ids = list(candidate.spell_effect_ids),
            terrain_ids      = list(candidate.terrain_ids),
        )
        if hit is not None and hit >= 0:
            self._resolve_spell_cast(hit)
        elif cell is not None:
            self._resolve_spell_cast_aoe(cell)
        else:
            self.pending_dispel_selection = None

    def _begin_item_drag(self, item):
        """Grab a dropped weapon for dragging. The release decides move vs. pickup."""
        self.drag_item_id     = item.id
        self.drag_item        = item
        self.drag_item_origin = rpg.Cell(item.cell.col, item.cell.row)
        self.drag_item_cell   = rpg.Cell(item.cell.col, item.cell.row)

    def _drop_dragged_item(self, cell):
        """Relocate the dragged weapon to `cell` (remove + re-place, keeping its sprite)."""
        item = self.drag_item
        if item is None or cell is None:
            return
        wdict = self.weapon_name_to_dict.get(item.weapon.name, {})
        sprite_path = item.sprite_path or wdict.get("sprite_path", "")
        self.bm.remove_item(item.id)
        self.bm.place_item(cell, item.weapon, sprite_path)
        self._combat_log_add(
            f"Moved {item.weapon.name or 'item'} to ({cell.col}, {cell.row}).")

    def _clear_item_drag(self):
        self.drag_item_id     = -1
        self.drag_item        = None
        self.drag_item_origin = None
        self.drag_item_cell   = None

    def _find_pickup_slot(self, weapon, weapons) -> int:
        """Auto-assign weapon to the best available slot. With the variable-length
        weapon list there is always room: an empty compatible slot is reused, else
        the first empty interior slot, else a new appended slot (== len(weapons))."""
        # A slot is empty when it holds the blank-slot sentinel — an empty name, or the bare
        # "Unarmed"/"Unnamed" default (helpers._weapon_slot_is_empty, and what a dropped or
        # fully-thrown slot is reset to). Match it EXACTLY: "MonkUnarmed" is a real weapon, and a
        # substring test let a picked-up longsword overwrite a Monk's unarmed strike.
        EMPTY = lambda w: (not w.name) or w.name in ("Unarmed", "Unnamed")
        # Ranged weapon → prefer the ranged slot (index 2) if empty
        if weapon.type == rpg.WeaponType.Ranged and len(weapons) > 2 and EMPTY(weapons[2]):
            return 2
        # Main hand empty → slot 0
        if len(weapons) > 0 and EMPTY(weapons[0]):
            return 0
        # Off-hand empty → slot 1
        if len(weapons) > 1 and EMPTY(weapons[1]):
            return 1
        # Ranged slot empty as last resort for melee
        if len(weapons) > 2 and EMPTY(weapons[2]):
            return 2
        # Any further empty slot (extra attack slots)
        for i, w in enumerate(weapons):
            if EMPTY(w):
                return i
        return len(weapons)   # no free slot: append a new one

    def _open_team_picker(self):
        """Open the modal team picker listing every placed agent. Clicking a row cycles
        its team; on dismiss the chosen factions are written back to the engine."""
        agents = self.bm.placed_agents
        rows = [(i, pt.name, self.bm.get_agent_faction(i)) for i, pt in enumerate(agents)]
        if not rows:
            self._combat_log_add("No agents placed to assign to teams.")
            return

        def _commit(assign: dict):
            for idx, fac in assign.items():
                self.bm.set_agent_faction(int(idx), int(fac))
            self._combat_log_add("Teams updated.")

        self.team_dialog.show(_commit, rows)

    def _show_visible_targets_popup(self):
        """Debug popup showing visible targets for the selected agent."""
        idx = self._current_agent_idx()
        if idx < 0:
            self._combat_log_add("No agent selected!")
            return

        agents = self.bm.placed_agents
        if idx >= len(agents):
            return

        # Compute visibility for this agent
        self.combat.compute_visibility(self.bm, idx)

        # Build popup text (header + each line annotated with the agent's team)
        selected_agent = agents[idx].name
        caster_team = faction_name(self.bm.get_agent_faction(idx))
        visibility_info = f"Visible targets for {selected_agent} ({caster_team} team):\n"

        visible_count = 0
        for target_idx, agent in enumerate(agents):
            if target_idx == idx:
                continue  # Skip self

            vis_level = self.combat.get_visibility(idx, target_idx)
            if vis_level != rpg.VisibilityLevel.Blocked:
                visible_count += 1
                vis_name = {
                    rpg.VisibilityLevel.Clear: "Clear",
                    rpg.VisibilityLevel.Dim: "Dim",
                    rpg.VisibilityLevel.LightlyObscured: "Lightly Obscured",
                    rpg.VisibilityLevel.Dark: "Dark",
                    rpg.VisibilityLevel.MagicalDark: "Magical Darkness",
                    rpg.VisibilityLevel.HeavilyObscured: "Heavily Obscured (fog)",
                    rpg.VisibilityLevel.Blocked: "Blocked",
                    rpg.VisibilityLevel.Sunlight: "Sunlight"
                }.get(vis_level, "Unknown")
                tgt_team = faction_name(self.bm.get_agent_faction(target_idx))
                visibility_info += f"  • {agent.name} ({vis_name}, {tgt_team} team)\n"

        if visible_count == 0:
            visibility_info += "  (no visible targets)"

        self._combat_log_add(visibility_info)

    # FLAG: Move to C++
    def _activate_reckless_and_attack(self, idx: int, slot: str):
        """Set Reckless Attack flag and proceed with attack."""
        cond = self.combat.get_agent_conditions(self.bm, idx)
        cond.reckless_attack = True
        self.combat.set_agent_conditions(self.bm, idx, cond)
        self.combat.log_event("reckless", idx=idx)  # record for checked replay
        agent = self.bm.placed_agents[idx]
        self._combat_log_add(f"{agent.name}: Activates Reckless Attack (enemies gain advantage)")
        # Continue with weapon selection
        self._start_attack(slot)

    def _continue_attack_sequence_after_rider(self, atk_idx: int):
        """After a rider effect (Stunning Strike, etc.) is applied, check if more attacks remain
        and either re-prompt or end the attack sequence. Called from rider callbacks."""
        # Determine if more attacks remain. Key on the DURABLE _attack_sequence_slot (not the
        # transient pending_attack_slot, which _finish_attack disarms centrally so the player can
        # move between attacks — see the "central disarm" note there).
        seq_slot = self._attack_sequence_slot
        has_more_attacks = False
        if seq_slot == "bonus":
            stats = self.combat.get_agent_stats(self.bm, atk_idx)
            has_more_attacks = stats.bonus_attacks_remaining > 0
        elif seq_slot == "action":
            has_more_attacks = self.attacks_remaining > 0

        if has_more_attacks:
            atk_name = self.bm.placed_agents[atk_idx].name
            if seq_slot == "bonus":
                # Bonus multi-attack (Flurry, etc.): single target — keep auto-targeting (unchanged).
                stats = self.combat.get_agent_stats(self.bm, atk_idx)
                rem = stats.bonus_attacks_remaining
                self.pending_attack_slot = ""  # Clear to let _start_attack re-seed
                self._start_attack(self._attack_sequence_slot)
                self._combat_log_add(
                    f"{atk_name}: {rem} attack{'s' if rem != 1 else ''} remaining — click a target.")
            else:
                # Action Extra-Attack sequence: DISARM between attacks so the player can move; the
                # standing "⚔ Attack (N)" button resumes (count preserved, no re-seed). Mirrors the
                # non-rider path in _finish_attack.
                rem = self.attacks_remaining
                self.pending_attack_slot = ""
                self._combat_log_add(
                    f"{atk_name}: {rem} attack{'s' if rem != 1 else ''} remaining — "
                    f"move if you wish, then click Attack to continue.")
        else:
            # Attacks exhausted
            self.pending_attack_slot = ""
            self._attack_sequence_slot = ""
            self.pending_attack_offhand = None
            self.pending_attack_resource = None
            # Boon of Dimensional Travel — arm Blink Steps once the Attack action is fully spent (this is
            # the rider-path twin of the exhausted branch in _finish_attack).
            if seq_slot == "action":
                self._arm_blink_steps(atk_idx)

        self._update_attack_overlay()

    @staticmethod
    def _weapon_usable(w) -> bool:
        """A weapon with an N/day cap or a Recharge action is unusable when expended or out of uses."""
        if getattr(w, "expended", False):
            return False
        if getattr(w, "uses_max", 0) > 0 and getattr(w, "uses_remaining", 0) <= 0:
            return False
        return True

    @staticmethod
    def _weapon_menu_label(w) -> str:
        """Decorate a weapon's picker label with N/M usage + a ⟳ recharge marker when limited."""
        label = w.name
        if getattr(w, "uses_max", 0) > 0 or getattr(w, "recharge_min", 0) > 0:
            cap = w.uses_max if w.uses_max > 0 else 1
            label += f"  {w.uses_remaining}/{cap}"
            if getattr(w, "expended", False):
                label += " ⟳recharge"
            elif getattr(w, "recharge_min", 0) > 0:
                label += f" ⟳{w.recharge_min}+"
        return label

    def _start_attack(self, slot: str):
        """Begin target-selection for an attack in the given slot."""
        idx = self._current_agent_idx()
        if idx < 0:
            return
        weapons = self.combat.get_agent_weapons(self.bm, idx)
        if not weapons:
            self._combat_log_add("No weapons equipped!")
            if slot == "action":
                self.action_used = True
            else:
                self.bonus_used = True
            return

        stats = self.combat.get_agent_stats(self.bm, idx)
        conds = self.combat.get_agent_conditions(self.bm, idx)

        # Reckless Attack prompt for Barbarians
        if (stats.character_class == rpg.CharacterClass.Barbarian and
            conds.raging and not conds.reckless_attack):
            def _proceed_normal():
                self._start_attack(slot)
            options = [
                ("Use Reckless Attack", lambda: self._activate_reckless_and_attack(idx, slot)),
                ("Normal Attack", _proceed_normal)
            ]
            px_popup = self._panel_x() + self._PANEL_PAD
            self.context_menu.show((px_popup, 290), options, self.screen.get_size())
            return

        # Only seed attacks_remaining when starting a fresh sequence (== 0).
        # If mid-sequence and same slot, don't reset. If mid-sequence and different slot, reject.
        if self.attacks_remaining == 0:
            # Fresh start
            if slot == "action":
                self.attacks_remaining = stats.num_attacks
                # War Magic gates once per Attack action; a fresh Attack action (including the
                # second one granted by Action Surge) re-enables the substitution.
                if conds.war_magic_used:
                    conds.war_magic_used = False
                    self.combat.set_agent_conditions(self.bm, idx, conds)
            else:
                # Bonus slot: check C++ bonus_attacks_remaining (Flurry, Martial Arts, etc.)
                self.attacks_remaining = stats.bonus_attacks_remaining if stats.bonus_attacks_remaining > 0 else 1
            self._attack_sequence_slot = slot
            # A normal attack uses default (slot-derived) proficiency and no resource cost.
            self.pending_attack_offhand = None
            self.pending_attack_resource = None
        elif slot != self._attack_sequence_slot:
            # Can't start a different slot while attacks are pending
            return

        def _activate(s, wi_):
            self.pending_attack_slot = s
            self.pending_weapon_idx  = wi_
            rem = self.attacks_remaining
            suffix = f" ({rem} attack{'s' if rem != 1 else ''} remaining)"
            self._combat_log_add(f"Click a target on the map.{suffix}")

        # FLAG: Move to C++
        # Filter weapons for bonus attacks: only show off-hand weapons
        weapons_to_use = weapons
        if slot == "bonus":
            offhand_weapons = [w for w in weapons if w.off_hand]
            if offhand_weapons:
                weapons_to_use = offhand_weapons

        # Eldritch Knight War Magic (L7+): during the Attack action, one attack may be replaced by
        # casting a spell. Offer it only when the engine gate is open AND there is an eligible spell.
        war_magic_option = None
        if (slot == "action" and self.combat.can_use_war_magic(self.bm, idx)
                and self.combat.available_war_magic_spells(self.bm, idx)):
            def _pick_war_magic():
                self.pending_attack_slot = ""   # leave attack-target mode; enter spell-target mode
                self.pending_weapon_idx  = 0
                self._start_cast_spell("war_magic")
            war_magic_option = ("War Magic: cast spell (replaces an attack)", _pick_war_magic)

        if len(weapons_to_use) == 1 and war_magic_option is None:
            # Auto-select if only one weapon (or one off-hand weapon for bonus)
            only = weapons_to_use[0]
            if not self._weapon_usable(only):
                why = "recharging" if getattr(only, "expended", False) else "out of uses"
                self._combat_log_add(f"{only.name} is {why} — cannot attack with it.")
                return
            wi = next((i for i, w in enumerate(weapons) if w == only), 0)
            _activate(slot, wi)
        else:
            options = []
            for w in weapons_to_use:
                wi = next((i for i, weapon in enumerate(weapons) if weapon == w), 0)
                if not self._weapon_usable(w):
                    # Show the depleted weapon greyed-in label, but make selecting it a no-op warning.
                    def _blocked(nm=w.name, exp=getattr(w, "expended", False)):
                        self._combat_log_add(f"{nm} is {'recharging' if exp else 'out of uses'} — cannot attack with it.")
                    options.append((self._weapon_menu_label(w), _blocked))
                    continue
                def _pick(s=slot, wi_=wi):
                    _activate(s, wi_)
                options.append((self._weapon_menu_label(w), _pick))
            if war_magic_option is not None:
                options.append(war_magic_option)
            px_popup = self._panel_x() + self._PANEL_PAD
            self.context_menu.show(
                (px_popup, 290),
                options,
                self.screen.get_size()
            )

    def _damage_breakdown_str(self, result) -> str:
        """Return ' [4 (weapon) + 3 (rage)]' when a hit has multiple damage sources, else ''."""
        bd = getattr(result, "damage_breakdown", None)
        if not bd or len(bd) <= 1:
            return ""
        return " [" + " + ".join(f"{amt} ({label})" for label, amt in bd) + "]"

    def _start_extra_attack(self, weapon_idx=0, offhand=False, resource=None, label="Extra attack",
                            slot="bonus"):
        """Generic 'make one extra weapon attack' setup — reused by War Priest, Great Weapon Master,
        Nick, etc. Configures the pending-attack knobs and enters target selection; the shared
        target-click → _resolve_combat_attack does the attack and spends `resource` (if any).

        slot="bonus" consumes the bonus action (most callers); slot="action" adds the attack to the
        Attack action without touching the bonus action (Nick's off-hand relocation)."""
        idx = self._current_agent_idx()
        if idx < 0:
            return
        self._attack_sequence_slot = slot
        # Only set attacks_remaining if not already set (e.g., by Flurry of Blows which queues multiple)
        if self.attacks_remaining == 0:
            if slot == "bonus":
                stats = self.combat.get_agent_stats(self.bm, idx)
                self.attacks_remaining = stats.bonus_attacks_remaining if stats.bonus_attacks_remaining > 0 else 1
            else:
                self.attacks_remaining = 1   # a single extra Attack-action attack (Nick)
        self.pending_attack_slot = slot
        self.pending_weapon_idx = weapon_idx
        self.pending_attack_offhand = offhand     # proficient (not an off-hand strike) when False
        self.pending_attack_resource = resource   # spent on a valid attack (e.g. "War Priest")
        self._combat_log_add(f"{label} — click a target.")

    def _offhand_bonus_available(self, idx: int) -> bool:
        """Can this agent make an off-hand attack as a Bonus Action right now?

        The single Light-property off-hand extra attack lands in the bonus action by default. Once
        it's been spent (e.g. relocated into the Attack action via Nick, or already taken in the
        bonus), only the Dual Wielder feat grants a second bonus-action off-hand attack."""
        if idx < 0 or idx >= len(self.bm.placed_agents):
            return False
        weapons = self.combat.get_agent_weapons(self.bm, idx)
        if not any(w.off_hand for w in weapons):
            return False
        conds = self.combat.get_agent_conditions(self.bm, idx)
        if not conds.offhand_attack_used:
            return True
        return self.combat.get_agent_stats(self.bm, idx).has_feat("Dual Wielder")

    def _nick_offhand_idx(self, idx: int) -> int:
        """Weapon-array index of an off-hand weapon whose Nick mastery can relocate the off-hand
        attack into the Attack action right now (agent has the Weapon Mastery feature and the
        off-hand extra attack hasn't been spent), else -1."""
        if idx < 0 or idx >= len(self.bm.placed_agents):
            return -1
        # The Weapon Master general feat grants access to a weapon's Mastery property to anyone, so
        # it satisfies the same gate as the martials' auto-granted "Weapon Mastery" feature.
        st = self.combat.get_agent_stats(self.bm, idx)
        if not (st.has_feat("Weapon Mastery") or st.has_feat("Weapon Master")):
            return -1
        if self.combat.get_agent_conditions(self.bm, idx).offhand_attack_used:
            return -1
        weapons = self.combat.get_agent_weapons(self.bm, idx)
        for i, w in enumerate(weapons):
            if w.off_hand and w.mastery == rpg.WeaponMastery.Nick:
                return i
        return -1

    def _mark_offhand_attack_used(self, idx: int):
        """Mark the single per-turn off-hand extra attack as spent on agent `idx`."""
        if idx < 0 or idx >= len(self.bm.placed_agents):
            return
        conds = self.combat.get_agent_conditions(self.bm, idx)
        conds.offhand_attack_used = True
        self.combat.set_agent_conditions(self.bm, idx, conds)

    def _are_allies(self, a_idx: int, b_idx: int) -> bool:
        """GUI mirror of the engine's areAllies: same NON-zero faction. Neutral (0)
        is its own faction, allied with no one."""
        if a_idx == b_idx:
            return True
        n = len(self.bm.placed_agents)
        if not (0 <= a_idx < n and 0 <= b_idx < n):
            return False
        fa = self.bm.get_agent_faction(a_idx)
        fb = self.bm.get_agent_faction(b_idx)
        return fa != 0 and fa == fb

    def _pending_spell_is_harm(self) -> bool:
        """True if the spell currently being aimed is a Harm spell (so a friendly-fire
        confirm is warranted). Heal/Transport spells return False — healing an ally
        must never prompt."""
        ci = self._current_agent_idx()
        if ci < 0:
            return False
        spells = self.combat.get_agent_spells(self.bm, ci)
        if not (0 <= self.pending_spell_idx < len(spells)):
            return False
        return spells[self.pending_spell_idx].type == rpg.SpellType.Harm

    def _pending_spell_targets_corpse(self) -> bool:
        """True if the spell currently being aimed selects a true-dead body — either a revive
        (revives_dead — Raise Dead / Revivify) or Animate Dead (animates_dead, which raises an
        undead from the corpse). Both route their click through _corpse_at instead of _agent_at,
        since a corpse isn't reachable by the normal path."""
        sp = self._pending_spell_obj()
        return bool(sp and (getattr(sp, "revives_dead", False) or
                            getattr(sp, "animates_dead", False)))

    def _pending_spell_binds_creature(self) -> bool:
        """True if the spell currently being aimed binds a living creature to the caster's
        service (Planar Binding, binds_creature). Routes the single-target click through the
        control-transfer resolve instead of the ordinary damage/heal cast path."""
        sp = self._pending_spell_obj()
        return bool(sp and getattr(sp, "binds_creature", False))

    def _pending_spell_obj(self):
        """The rpg.Spell currently being aimed (pending single-target cast), or None."""
        if not self.pending_spell_slot or self.pending_spell_is_aoe:
            return None
        ci = self._current_agent_idx()
        if ci < 0:
            return None
        spells = self.combat.get_agent_spells(self.bm, ci)
        if not (0 <= self.pending_spell_idx < len(spells)):
            return None
        return spells[self.pending_spell_idx]

    def _confirm_friendly_harm(self, target_idx: int, on_confirm) -> None:
        """Faction rule 4: if the acting agent and target_idx are on the same team,
        ask the player to confirm before a harmful action (e.g. accidentally clicking
        a teammate). Non-allies (or no current actor) run on_confirm() immediately."""
        actor = self._current_agent_idx()
        if actor < 0 or not self._are_allies(actor, target_idx):
            on_confirm()
            return
        tgt_name = self.bm.placed_agents[target_idx].name
        options = [
            (f"Harm ally {tgt_name}!", on_confirm),
            ("Cancel", lambda: None),
        ]
        px, py = self._agent_screen_pos(target_idx)
        self.context_menu.show((px, py), options, self.screen.get_size())

    def _attack_is_a_throw(self, atk_idx: int, target_idx: int, weapon_idx: int) -> bool:
        """Is this attack a THROW — i.e. does the weapon leave the attacker's hand?

        A Thrown weapon is hurled when the DM targets something the attacker cannot reach with it:
        that attack is otherwise simply illegal (the engine's canAttack rejects it), so reading it
        as a throw adds the throw without ever turning an ordinary melee swing into one. A Ranged
        weapon with the Thrown property (a Dart) is thrown at any distance — throwing IS how it is
        used. The engine spends the copy and lands it on the ground (applyAttackResult); a weapon
        with no copies left is refused there, so no check for that is needed here."""
        weapons = self.combat.get_agent_weapons(self.bm, atk_idx)
        if not (0 <= weapon_idx < len(weapons)):
            return False
        w = weapons[weapon_idx]
        if not w.thrown:
            return False
        if w.type == rpg.WeaponType.Ranged:
            return True
        dist_ft = self._footprint_dist_ft(atk_idx, target_idx)
        return dist_ft > w.reach_ft

    def _resolve_combat_attack(self, target_idx: int):
        """Resolve the pending attack against target_idx.

        Routes through begin_attack (not execute_action) so the target can cast Shield (+5 AC) as a
        reaction before any damage (the OnHit window). begin_attack rolls the
        attack, then either parks at the Shield checkpoint (AwaitingDecision) or resolves immediately
        (Completed). _finish_attack runs the post-resolution rider chain + logging in both cases,
        reading the result from last_attack_result()."""
        atk_idx = self._current_agent_idx()
        slot    = self.pending_attack_slot
        if atk_idx < 0 or not slot:
            return
        action = rpg.Attack(atk_idx, target_idx, self.pending_weapon_idx)
        action.is_offhand = (slot == "bonus") if self.pending_attack_offhand is None else self.pending_attack_offhand
        action.attack_slot = slot  # Pass the slot type to C++ ("action" or "bonus")
        action.thrown = self._attack_is_a_throw(atk_idx, target_idx, self.pending_weapon_idx)

        # Stash what _finish_attack needs (the self.pending_* attrs stay set across the suspend) and
        # arm it as the reaction continuation, then begin the attack.
        self._attack_post = dict(atk_idx=atk_idx, target_idx=target_idx, slot=slot, action=action)
        self._reaction_finish = self._finish_attack

        status = self.combat.begin_attack(self.bm, action)
        self._flush_combat_log()
        if status == rpg.FlowStatus.AwaitingDecision:
            self._show_pending_reaction_menu()   # target's Shield menu; _submit_reaction → _finish_attack
        else:
            self._finish_attack()

    def _apply_chaos_staff_rider(self, atk_idx: int, target_idx: int, weapon_idx: int, tgt_name: str):
        """Green Slaad's Chaos Staff on-hit rider. On a hit, roll 1d4: the target is Charmed (1),
        Frightened (2), Poisoned (3), or Incapacitated (4) until the start of the Slaad's next turn.
        The random pick lives here in Python; the condition itself is applied + ticked by the C++
        engine (add_agent_condition fully sets the flags; tick_agent_conditions_for_caster expires
        it when the caster's next turn begins, so turns_remaining=1)."""
        weapons = self.combat.get_agent_weapons(self.bm, atk_idx)
        if not (0 <= weapon_idx < len(weapons)):
            return
        if weapons[weapon_idx].name != "Chaos Staff":
            return

        roll = random.randint(1, 4)
        condition = {1: "Charmed", 2: "Frightened", 3: "Poisoned", 4: "Incapacitated"}[roll]

        cond = rpg.ActiveAgentCondition()
        cond.agent_idx       = target_idx
        cond.caster_idx      = atk_idx
        cond.spell_idx       = -1            # weapon rider, not a spell
        cond.condition_name  = condition
        cond.turns_remaining = 1             # expires at the start of the Slaad's next turn
        self.combat.add_agent_condition(self.bm, cond)

        self._combat_log_add(
            f"Chaos Staff (1d4={roll}): {tgt_name} is {condition} until the start of the Slaad's next turn.")

    def _finish_attack(self):
        """Post-resolution of a begin_attack flow (immediate or after the OnHit Shield window). Reads
        the AttackResult from last_attack_result() and runs the attacker rider-offer chain + logging."""
        ctx        = self._attack_post
        atk_idx    = ctx["atk_idx"]
        target_idx = ctx["target_idx"]
        slot       = ctx["slot"]
        action     = ctx["action"]
        result     = self.combat.last_attack_result()

        # Generic extra-attack cost (War Priest, etc.): spend the resource once, only on a valid attack.
        if result.valid and self.pending_attack_resource:
            self.combat.spend_resource(self.bm, atk_idx, self.pending_attack_resource)
            self.pending_attack_resource = None

        # Spend the single per-turn off-hand extra attack when this strike used the off-hand weapon
        # (base bonus off-hand, Nick relocation, or Dual Wielder's bonus). Once spent, the base
        # bonus off-hand attack is no longer offered — only Dual Wielder grants a second one.
        if result.valid:
            weapons = self.combat.get_agent_weapons(self.bm, atk_idx)
            wi = action.weapon_idx
            if 0 <= wi < len(weapons) and weapons[wi].off_hand:
                self._mark_offhand_attack_used(atk_idx)

        self._flush_combat_log()

        agents   = self.bm.placed_agents
        atk_name = agents[atk_idx].name if atk_idx < len(agents) else "?"
        tgt_name = agents[target_idx].name if target_idx < len(agents) else "?"

        # FLAG: Move to C++
        if not result.valid:
            # Check if attack failed because agent slipped
            if atk_idx >= 0 and atk_idx < len(agents) and agents[atk_idx].conditions.slipped_this_turn:
                self._combat_log_add(f"{atk_name} slipped and cannot act — turn ends.")
                self.pending_attack_slot = ""
                self.attacks_remaining   = 0
                self._advance_turn()
            else:
                # Out of range / invalid target: this is a misclick, NOT a spent attack. Do not
                # decrement (the decrement is below this return) and — critically — do not zero
                # attacks_remaining. _start_attack re-seeds the count only when it is 0, so zeroing
                # here would let the next Attack click re-seed to num_attacks and hand out a bonus
                # attack (e.g. after a Forceful Blow / Push knocks the target out of reach mid-
                # sequence). Just clear pending_attack_slot so the player can reposition (drag-to-
                # move); clicking Attack again resumes the SAME sequence with the remaining count.
                rem = self.attacks_remaining
                tail = (f" ({rem} attack{'s' if rem != 1 else ''} remaining)" if rem > 0 else "")
                self._combat_log_add(
                    f"{atk_name}: out of range — move closer or click Attack to retry{tail}")
                self.pending_attack_slot = ""
            return

        # Check if attacker has exhaustion for potential penalty note
        # FLAG: Move to C++
        atk_cond = self.combat.get_agent_conditions(self.bm, atk_idx) if 0 <= atk_idx < len(agents) else None
        exh_note = ""
        if atk_cond and atk_cond.exhaustion_level >= 1:
            penalty = 2 * atk_cond.exhaustion_level
            exh_note = f" [−{penalty} exhaustion]"

        # FLAG: Move to C++
        # Check for a post-hit rider menu (Cunning Strike or Brutal Strike) before logging.
        has_brutal_strike = False
        has_cunning_strike = False
        has_divine_strike = False
        has_guided_strike = False
        has_peerless_aim = False
        has_restore_balance_miss = False
        has_push = False
        has_topple = False
        has_cleave = False
        has_stunning_strike = False
        has_open_hand_rider = False
        has_quivering_palm = False
        has_hand_of_harm = False
        has_elemental_move = False
        has_maneuver = False
        has_precision = False
        has_psionic_strike = False
        has_punch_and_grab = False
        has_divine_smite = False
        has_eldritch_smite = False
        has_reckless_reroll = False
        has_riposte = False
        has_protective_field = False
        has_interception = False
        has_sentinel_guard = False
        has_soul_of_vengeance = False
        has_sudden_strike = False
        has_homing_strike = False
        if result.valid:
            atk_cond = self.combat.get_agent_conditions(self.bm, atk_idx)
            # Riposte is a DEFENDER reaction: the flag is set on the target, not the attacker.
            tgt_cond = self.combat.get_agent_conditions(self.bm, target_idx) if 0 <= target_idx < len(agents) else None
            if result.hit and atk_cond and atk_cond.cunning_strike_available:
                has_cunning_strike = True
            elif result.hit and atk_cond and atk_cond.brutal_strike_available:
                has_brutal_strike = True
            elif result.hit and atk_cond and atk_cond.stunning_strike_available and self.pending_attack_slot == "action":
                has_stunning_strike = True
            elif result.hit and atk_cond and atk_cond.open_hand_rider_available:
                has_open_hand_rider = True
            # Quivering Palm (Open Hand L17): a standalone fallback offer for unarmed hits where neither
            # Stunning Strike (action) nor the Open Hand Flurry rider (bonus) claimed the hit. When one
            # of those DID fire, the plant option is injected into that menu instead (no shadowing).
            elif result.hit and atk_cond and atk_cond.quivering_palm_available:
                has_quivering_palm = True
            elif result.hit and atk_cond and atk_cond.hand_of_harm_available:
                has_hand_of_harm = True
            elif result.hit and atk_cond and atk_cond.elemental_attunement_move_available:
                has_elemental_move = True
            elif result.hit and atk_cond and atk_cond.divine_strike_available:
                has_divine_strike = True
            elif result.hit and atk_cond and atk_cond.psionic_strike_available:
                has_psionic_strike = True
            elif result.hit and atk_cond and atk_cond.grappler_punch_grab_available:
                has_punch_and_grab = True
            elif result.hit and atk_cond and atk_cond.divine_smite_available:
                has_divine_smite = True
            elif result.hit and atk_cond and atk_cond.eldritch_smite_available:
                has_eldritch_smite = True
            elif result.hit and atk_cond and atk_cond.maneuver_available:
                has_maneuver = True
            elif (not result.hit) and atk_cond and atk_cond.peerless_aim_available:
                has_peerless_aim = True
            elif (not result.hit) and atk_cond and atk_cond.guided_strike_available:
                has_guided_strike = True
            elif (not result.hit) and atk_cond and atk_cond.restore_balance_miss_available:
                has_restore_balance_miss = True
            elif (not result.hit) and atk_cond and atk_cond.maneuver_precision_available:
                has_precision = True
            elif (not result.hit) and atk_cond and atk_cond.reckless_reroll_available:
                has_reckless_reroll = True
            # Homing Strikes (Soulknife L9): on a miss with a Psychic Blade, spend a Psionic Energy
            # Die to add to the roll and (maybe) convert it to a hit.
            elif (not result.hit) and self._can_homing_strike(atk_idx, action):
                has_homing_strike = True
            # Riposte is offered LAST among on-miss options (v1): an attacker on-miss rider above
            # shadows the defender's riposte this swing (see known_limitations.md; full chaining is v2).
            elif (not result.hit) and tgt_cond and tgt_cond.riposte_available:
                has_riposte = True
            # Great Weapon Master — Hew is NOT offered here: a melee crit/kill with a Heavy weapon arms
            # the gwm_hew_available flag (in C++), which surfaces as a standalone bonus-action button
            # (see _start_gwm_hew). Keeping it out of this on-hit elif chain lets the weapon-mastery
            # riders below (Cleave/Push/Topple) resolve on the triggering hit without being shadowed.
            elif result.hit and atk_cond and atk_cond.push_available:
                has_push = True
            elif result.hit and atk_cond and atk_cond.topple_available:
                has_topple = True
            elif result.hit and atk_cond and atk_cond.cleave_available:
                has_cleave = True
            # Protective Field is a DEFENDER on-hit reaction (the flag-less mechanic re-validates in
            # C++). Offered LAST among on-hit options (v1): an attacker on-hit rider above shadows the
            # defender's Protective Field this swing (see known_limitations.md). Mirrors riposte's
            # on-miss shadowing.
            elif self._can_protective_field(target_idx, result):
                has_protective_field = True
            # Interception is a BYSTANDER on-hit damage-reduction reaction: an ally within 5 ft of the
            # target spends its reaction to reduce the damage by 1d10 + PB (post-hit heal-back). Offered
            # among the on-hit reductions; the full eligibility scan lives in C++ (can_intercept).
            elif (result.hit and result.total_damage > 0 and not result.target_down
                  and self._find_interceptor(action, target_idx, result) >= 0):
                has_interception = True
            # Sentinel Guardian is a BYSTANDER reaction (a third creature near the attacker), fired on a
            # hit OR a miss. Flagged on the attacker; offered LAST among the v1 single-rider chain (an
            # attacker's own rider shadows it this swing — see known_limitations.md).
            elif atk_cond and atk_cond.sentinel_guard_available:
                has_sentinel_guard = True
            # Soul of Vengeance (Oath of Vengeance L15): the sworn foe just attacked; the paladin holding
            # the Vow of Enmity may counter-strike. Flagged on the attacker (the sworn foe); fires on hit OR miss.
            elif atk_cond and atk_cond.soul_of_vengeance_available:
                has_soul_of_vengeance = True
            # Stalker's Flurry — Sudden Strike (Gloom Stalker L11): a Dreadful Strike hit grants one
            # FREE extra weapon attack (no action/bonus cost). Flagged on the attacker by the engine
            # when the Dreadful Strike rider fires; offered last (an attacker's own rider shadows it
            # this swing, like GWM Hew). Mass Fear (the alternative) is deferred — see known_limitations.
            elif atk_cond and atk_cond.sudden_strike_available:
                has_sudden_strike = True

        # FLAG: Move to C++
        # Format attack message
        if result.hit:
            dmg_parts = self._get_damage_type_names(result.magic_damage_types, result.physical_damage_types)
            dmg_type_str = "/".join(dmg_parts) if dmg_parts else "untyped"
            atk_msg = (f"{atk_name}→{tgt_name}: "
                       f"HIT {result.total_damage}{self._damage_breakdown_str(result)} {dmg_type_str}"
                       f"{' CRIT!' if result.critical else ''}"
                       f"{' — DOWN' if result.target_down else ''}"
                       f"{exh_note}")
        else:
            atk_msg = (f"{atk_name}→{tgt_name}: "
                       f"miss (roll {result.total_roll} vs AC {result.target_ac})"
                       f"{exh_note}")

        # On-map outcome flash above the targeted token.
        if result.hit:
            flash_txt = f"Crit ({result.total_damage})" if result.critical else f"Hit ({result.total_damage})"
            self._spawn_flash(target_idx, flash_txt, FLASH_CRIT if result.critical else FLASH_GOOD)
        else:
            self._spawn_flash(target_idx, "Miss", FLASH_BAD)

        # Green Slaad Chaos Staff: on a hit, the target gains a random condition until the
        # start of the Slaad's next turn. The 1d4 condition pick happens here in Python.
        if result.hit:
            self._apply_chaos_staff_rider(atk_idx, target_idx, action.weapon_idx, tgt_name)

        # Decrement attack counter: action attacks use Python attacks_remaining,
        # bonus-action attacks use C++ bonus_attacks_remaining
        has_more_attacks = False
        if self.pending_attack_slot == "bonus":
            has_more_attacks = self.combat.consume_bonus_attack(self.bm, atk_idx)
        elif self.pending_attack_slot == "action":
            self.attacks_remaining -= 1
            has_more_attacks = self.attacks_remaining > 0

        # Central disarm for the ACTION sequence: clear pending_attack_slot NOW, before any rider
        # menu, so the map leaves target-selection between attacks regardless of which rider (if any)
        # fires. Without this, the many on-hit riders that don't re-prompt (brutal/cunning/divine/
        # push/topple/…) left the map armed → clicking your own sprite resolved as a self-attack
        # ("out of range"). The standing "⚔ Attack (N)" button resumes the sequence; the count is
        # preserved. Bonus sequences keep their own armed auto-target flow (single target). The
        # rider continuations and the no-rider block below key on _attack_sequence_slot, not this
        # field, so the early clear is safe. Also commit the Action here (and end the sequence when
        # the last attack is spent) so it happens even for the many riders that skip the no-rider
        # block — otherwise a rider on the LAST attack would leave action_used False + a stale
        # _attack_sequence_slot, and the next Attack click would re-seed a fresh full set of attacks.
        # action_used True mid-sequence is fine: mid_sequence_action keeps the "⚔ Attack (N)" button
        # alive (and the handler lets it fire). Frenzy / unarmed-weapon restore stay in the no-rider
        # block (rider-laden actions skip them — a pre-existing edge, see known_limitations.md).
        if self._attack_sequence_slot == "action":
            self.pending_attack_slot = ""
            self.action_used = True
            if not has_more_attacks:
                self._attack_sequence_slot = ""
                self.pending_attack_offhand = None
                self.pending_attack_resource = None

        # FLAG: Move to C++
        # A weapon grants at most one Mastery, but it stacks with a class on-hit rider (e.g. a
        # Barbarian's Brutal Strike + a Topple maul, or a Paladin's Divine Smite + a Cleave greataxe).
        # The old single-rider elif chain let the class rider shadow the Mastery. Now, when a Class B
        # "extra-damage/effect" rider fires AND a Mastery (Push/Topple/Cleave) is also pending, the
        # damage rider is offered with on_done = the Mastery prompt, so BOTH resolve on the one hit.
        mastery_offer = self._pending_mastery_offer(
            atk_idx, target_idx, atk_name, tgt_name, result, atk_msg, action.weapon_idx)

        # Defer logging until the rider effect is chosen; otherwise log immediately.
        if has_cunning_strike:
            self._offer_cunning_strike(atk_idx, target_idx, atk_name, tgt_name, result, atk_msg)
        elif has_stunning_strike:
            self._offer_stunning_strike(atk_idx, target_idx, atk_name, tgt_name, result, atk_msg)
        elif has_open_hand_rider:
            self._offer_open_hand_rider(atk_idx, target_idx, atk_name, tgt_name, result, atk_msg)
        elif has_quivering_palm:
            self._offer_quivering_palm(atk_idx, target_idx, atk_name, tgt_name, result, atk_msg)
        elif has_hand_of_harm:
            self._offer_hand_of_harm(atk_idx, target_idx, atk_name, tgt_name, result, atk_msg)
        elif has_elemental_move:
            self._offer_elemental_move(atk_idx, target_idx, atk_name, tgt_name, result, atk_msg)
        elif has_brutal_strike:
            self._offer_brutal_strike(atk_idx, target_idx, atk_name, tgt_name, result, atk_msg, on_done=mastery_offer)
        elif has_divine_strike:
            self._offer_divine_strike(atk_idx, target_idx, atk_name, tgt_name, result, atk_msg, on_done=mastery_offer)
        elif has_psionic_strike:
            self._offer_psionic_strike(atk_idx, target_idx, atk_name, tgt_name, result, atk_msg, on_done=mastery_offer)
        elif has_punch_and_grab:
            self._offer_punch_and_grab(atk_idx, target_idx, atk_name, tgt_name, result, atk_msg)
        elif has_divine_smite:
            self._offer_divine_smite(atk_idx, target_idx, atk_name, tgt_name, result, atk_msg, on_done=mastery_offer)
        elif has_eldritch_smite:
            self._offer_eldritch_smite(atk_idx, target_idx, atk_name, tgt_name, result, atk_msg, on_done=mastery_offer)
        elif has_peerless_aim:
            self._offer_peerless_aim(action, atk_idx, target_idx, atk_name, tgt_name, result, atk_msg)
        elif has_guided_strike:
            self._offer_guided_strike(action, atk_idx, target_idx, atk_name, tgt_name, result, atk_msg)
        elif has_restore_balance_miss:
            self._offer_restore_balance_miss(action, atk_idx, target_idx, atk_name, tgt_name, result, atk_msg)
        elif has_maneuver:
            self._offer_maneuver(action, atk_idx, target_idx, atk_name, tgt_name, result, atk_msg)
        elif has_precision:
            self._offer_precision_attack(action, atk_idx, target_idx, atk_name, tgt_name, result, atk_msg)
        elif has_reckless_reroll:
            self._offer_reckless_reroll(action, atk_idx, target_idx, atk_name, tgt_name, result, atk_msg)
        elif has_homing_strike:
            self._offer_homing_strike(action, atk_idx, target_idx, atk_name, tgt_name, result, atk_msg)
        elif has_riposte:
            self._offer_riposte(action, atk_idx, target_idx, atk_name, tgt_name, result, atk_msg)
        elif has_protective_field:
            self._offer_protective_field(atk_idx, target_idx, atk_name, tgt_name, result, atk_msg)
        elif has_interception:
            self._offer_interception(action, atk_idx, target_idx, atk_name, tgt_name, result, atk_msg)
        elif has_sentinel_guard:
            self._offer_sentinel_guard(action, atk_idx, target_idx, atk_name, tgt_name, result, atk_msg)
        elif has_soul_of_vengeance:
            self._offer_soul_of_vengeance(action, atk_idx, target_idx, atk_name, tgt_name, result, atk_msg)
        elif has_push:
            self._offer_push(atk_idx, target_idx, atk_name, tgt_name, result, atk_msg)
        elif has_topple:
            self._offer_topple(atk_idx, target_idx, atk_name, tgt_name, result, atk_msg, action.weapon_idx)
        elif has_cleave:
            self._offer_cleave(atk_idx, target_idx, atk_name, tgt_name, result, atk_msg, action.weapon_idx)
        elif has_sudden_strike:
            self._offer_sudden_strike(atk_idx, target_idx, atk_name, tgt_name, result, atk_msg, action.weapon_idx)
        else:
            self._combat_log_add(atk_msg)

        # Concentration on weapon damage is rolled inside execute_action (C++ owns the CON save and,
        # on a failure, fully drops the spell's terrain/effects/conditions). Surface the log + sync caches.
        if result.hit and result.total_damage > 0:
            self._flush_combat_log()
            self._sync_spell_effect_cache()

        # FLAG: Move to C++
        # If target is down, drop their concentration
        if result.target_down:
            self._drop_concentration_for_agent(target_idx)

        # Only run this re-prompt logic if NO rider was offered. If a rider was offered,
        # the rider callback will handle re-prompting via _continue_attack_sequence_after_rider().
        has_rider = has_cunning_strike or has_stunning_strike or has_open_hand_rider or has_quivering_palm or has_hand_of_harm or has_brutal_strike or has_divine_strike or has_psionic_strike or has_guided_strike or has_peerless_aim or has_restore_balance_miss or has_push or has_topple or has_cleave or has_reckless_reroll or has_protective_field or has_interception or has_sudden_strike
        if not has_rider:
            # Check if more attacks are queued (action or bonus)
            if has_more_attacks:
                # More attacks left in this sequence.
                if self._attack_sequence_slot == "bonus":
                    # Bonus multi-attack (e.g. Flurry of Blows): single target, no standing
                    # mid-sequence button, so keep auto-targeting the next strike (unchanged).
                    stats = self.combat.get_agent_stats(self.bm, atk_idx)
                    rem = stats.bonus_attacks_remaining
                    self.pending_attack_slot = ""  # Clear to let _start_attack re-seed
                    self._start_attack("bonus")
                    self._combat_log_add(
                        f"{atk_name}: {rem} attack{'s' if rem != 1 else ''} remaining — click a target.")
                else:
                    # Action Extra-Attack sequence: DISARM target-selection between attacks so the
                    # player can move (clicking your own sprite no longer reads as a self-attack).
                    # The standing "⚔ Attack (N)" button (mid_sequence_action) resumes the sequence;
                    # the count is preserved, so re-clicking does NOT re-seed to a fresh full set
                    # (see _start_attack's `attacks_remaining == 0` guard). Requested by the user as
                    # the general fix for "allow movement mid-attack-sequence".
                    rem = self.attacks_remaining
                    self.pending_attack_slot = ""
                    self._combat_log_add(
                        f"{atk_name}: {rem} attack{'s' if rem != 1 else ''} remaining — "
                        f"move if you wish, then click Attack to continue.")
            else:
                # Attacks exhausted — mark action used and clear sequence state
                self.pending_attack_slot = ""
                self._attack_sequence_slot = ""
                # Clear the generic extra-attack knobs so they don't leak to the next attack.
                self.pending_attack_offhand = None
                self.pending_attack_resource = None
                # Boon of Dimensional Travel — arm Blink Steps: the Attack action is fully spent.
                if slot == "action":
                    self._arm_blink_steps(atk_idx)

            # Restore original weapons if this was an unarmed strike
            if self._unarmed_strike_original_weapons:
                idx_to_restore, orig_weapons = self._unarmed_strike_original_weapons
                self.combat.set_agent_weapons(self.bm, idx_to_restore, orig_weapons)
                self._unarmed_strike_original_weapons = None

            # FLAG: Move to C++
            if slot == "action":
                self.action_used = True
                # 2024 Berserker Frenzy = extra Nd6 damage (N = Rage damage bonus),
                # applied engine-side in combat_attack.cpp. No bonus attack in 2024
                # (that was the 2014 version), so nothing to trigger here.
            else:
                self.bonus_used = True
        # Refresh attack overlay (HP may have changed).
        self._update_attack_overlay()

    def _pending_mastery_offer(self, atk_idx, target_idx, atk_name, tgt_name, result, atk_msg, weapon_idx):
        """If a weapon-Mastery on-hit rider (Push/Topple/Cleave) is still pending on this hit, return a
        zero-arg callable that presents it as a CHAINED rider (suppressing the duplicate HIT-line log,
        since the preceding rider already logged the final damage). A weapon grants at most one Mastery,
        so at most one applies. Returns None when no Mastery is pending. Used by _finish_attack to let a
        Mastery resolve after a class on-hit rider (Brutal Strike, Divine Smite, …) instead of being
        shadowed by it."""
        if not result.hit:
            return None
        c = self.combat.get_agent_conditions(self.bm, atk_idx)
        if c.push_available:
            return lambda: self._offer_push(atk_idx, target_idx, atk_name, tgt_name, result, atk_msg, chained=True)
        if c.topple_available:
            return lambda: self._offer_topple(atk_idx, target_idx, atk_name, tgt_name, result, atk_msg, weapon_idx, chained=True)
        if c.cleave_available:
            return lambda: self._offer_cleave(atk_idx, target_idx, atk_name, tgt_name, result, atk_msg, weapon_idx, chained=True)
        return None

    def _offer_brutal_strike(self, atk_idx, target_idx, atk_name, tgt_name, result, atk_msg, on_done=None):
        """Show Brutal Strike effect menu after a hit. Logs the attack after effect is chosen. When
        on_done is set (a pending weapon-Mastery rider), it is invoked instead of refreshing the
        overlay, chaining the Mastery prompt after this one."""
        atk_stats = self.combat.get_agent_stats(self.bm, atk_idx)
        level = atk_stats.char_level
        dice_str = "2d10" if level >= 17 else "1d10"

        # FLAG: Move to C++
        def _apply(effects):
            if effects:
                # Apply Brutal Strike effect and modify result
                self.combat.apply_brutal_strike_effect(self.bm, atk_idx, target_idx, effects, result)
                # Re-format attack message with updated damage breakdown
                dmg_parts = self._get_damage_type_names(result.magic_damage_types, result.physical_damage_types)
                dmg_type_str = "/".join(dmg_parts) if dmg_parts else "untyped"
                updated_msg = (f"{atk_name}→{tgt_name}: "
                               f"HIT {result.total_damage}{self._damage_breakdown_str(result)} {dmg_type_str}"
                               f"{' CRIT!' if result.critical else ''}"
                               f"{' — DOWN' if result.target_down else ''}")
                self._combat_log_add(updated_msg)
            else:
                # Skip chosen - log original attack
                self._combat_log_add(atk_msg)
            self._flush_combat_log()
            if on_done:
                on_done()
            else:
                self._update_attack_overlay()

        options = [
            (f"Forceful Blow ({dice_str} + push 15ft)", lambda: _apply([0])),
            (f"Hamstring Blow ({dice_str} + speed −15ft)", lambda: _apply([1])),
        ]
        if level >= 13:
            options += [
                (f"Staggering Blow ({dice_str} + disadv next save)", lambda: _apply([2])),
                (f"Sundering Blow ({dice_str} + +5 next atk vs target)", lambda: _apply([3])),
            ]
        options.append(("Skip Brutal Strike", lambda: _apply([])))

        px, py = self._agent_screen_pos(atk_idx)
        self.context_menu.show((px, py), options, self.screen.get_size())

    def _offer_push(self, atk_idx, target_idx, atk_name, tgt_name, result, atk_msg, chained=False):
        """Push weapon mastery: optionally shove the target 10 ft straight away (Large or smaller).
        The shove itself is applied in C++ via apply_push, which clears the availability flag. When
        chained=True it is presented after a preceding on-hit rider that already logged the HIT line,
        so the duplicate attack-message log is suppressed."""
        def _apply(do):
            if not chained:
                self._combat_log_add(atk_msg)
            if do:
                feet = self.combat.apply_push(self.bm, atk_idx, target_idx)
                if feet > 0:
                    self._combat_log_add(f"{atk_name} pushes {tgt_name} {feet} ft (Push).")
                else:
                    self._combat_log_add(f"{atk_name}: Push had no effect.")
            else:
                # Skip push: clear the availability flag so it won't be offered again this turn.
                # (push_used_this_turn was already set in C++ on the qualifying hit and is not
                # bound to Python; the overlay gates on push_available.)
                c = self.combat.get_agent_conditions(self.bm, atk_idx)
                c.push_available = False
                self.combat.set_agent_conditions(self.bm, atk_idx, c)
            self._flush_combat_log()
            self._update_attack_overlay()
        options = [
            ("Push 10 ft (away)", lambda: _apply(True)),
            ("Skip Push", lambda: _apply(False)),
        ]
        px, py = self._agent_screen_pos(atk_idx)
        self.context_menu.show((px, py), options, self.screen.get_size())

    def _offer_topple(self, atk_idx, target_idx, atk_name, tgt_name, result, atk_msg, weapon_idx, chained=False):
        """Topple weapon mastery: optionally force a CON save or knock the target Prone.
        The save + prone are resolved in C++ via apply_topple, which clears the flag. When chained=True
        it is presented after a preceding on-hit rider that already logged the HIT line, so the
        duplicate attack-message log is suppressed."""
        def _apply(do):
            if not chained:
                self._combat_log_add(atk_msg)
            if do:
                res = self.combat.apply_topple(self.bm, atk_idx, target_idx, weapon_idx)
                if res.toppled:
                    self._combat_log_add(
                        f"{tgt_name} is knocked Prone (Topple — save {res.save_roll} vs DC {res.save_dc}).")
                    self._spawn_flash(target_idx, "Failed", FLASH_BAD)
                else:
                    self._combat_log_add(
                        f"{tgt_name} resists Topple (save {res.save_roll} vs DC {res.save_dc}).")
                    self._spawn_flash(target_idx, "Saved", FLASH_GOOD)
            else:
                # Skip topple: clear the availability flag so it won't be offered again this turn.
                # (topple_used_this_turn is not bound to Python; the overlay gates on topple_available.)
                c = self.combat.get_agent_conditions(self.bm, atk_idx)
                c.topple_available = False
                self.combat.set_agent_conditions(self.bm, atk_idx, c)
            self._flush_combat_log()
            self._update_attack_overlay()
        options = [
            ("Topple (CON save or Prone)", lambda: _apply(True)),
            ("Skip Topple", lambda: _apply(False)),
        ]
        px, py = self._agent_screen_pos(atk_idx)
        self.context_menu.show((px, py), options, self.screen.get_size())

    def _cleave_valid_targets(self, atk: int, first: int, weapon_idx: int) -> list:
        """Foes a Cleave second attack may legally strike: a different, living, non-ally creature
        that is BOTH within 5 ft of the first target AND within the attacker's reach with the Cleave
        weapon. Footprint-aware (handles large creatures). Mirrors the RAW Cleave constraints."""
        agents = self.bm.placed_agents
        weapons = self.combat.get_agent_weapons(self.bm, atk)
        reach = weapons[weapon_idx].reach_ft if 0 <= weapon_idx < len(weapons) else 5
        out = []
        for t in range(len(agents)):
            if t == atk or t == first:
                continue
            if self.combat.get_agent_stats(self.bm, t).hp_cur <= 0:
                continue
            if self._are_allies(atk, t):
                continue
            if self._footprint_dist_ft(first, t) > 5:
                continue
            if self._footprint_dist_ft(atk, t) > reach:
                continue
            out.append(t)
        return out

    def _offer_cleave(self, atk_idx, target_idx, atk_name, tgt_name, result, atk_msg, weapon_idx, chained=False):
        """Cleave weapon mastery: optionally make one extra attack vs a 2nd creature within 5 ft of
        the first target AND within reach, with no ability modifier on damage (once per turn). Cleave
        is part of the Attack action, so it is resolved out-of-band (see _resolve_cleave) — it does
        not consume the bonus action or a sequence attack. On accept, the legal second targets are
        highlighted on the map (green rings) and the player clicks one (Esc cancels). When chained=True
        it is presented after a preceding on-hit rider that already logged the HIT line, so the
        duplicate attack-message log is suppressed."""
        def _apply(do):
            if not chained:
                self._combat_log_add(atk_msg)
            self._flush_combat_log()
            if do:
                valid = self._cleave_valid_targets(atk_idx, target_idx, weapon_idx)
                if not valid:
                    self._combat_log_add(
                        f"Cleave: no eligible creature within 5 ft of {tgt_name} and within reach.")
                    self._flush_combat_log()
                else:
                    # Mark Cleave spent for the turn so the engine won't re-offer it (and a chained
                    # Cleave hit can't recurse). Then await the 2nd-target click.
                    c = self.combat.get_agent_conditions(self.bm, atk_idx)
                    c.cleave_used_this_turn = True
                    c.cleave_available = False
                    self.combat.set_agent_conditions(self.bm, atk_idx, c)
                    self.pending_cleave = {"attacker": atk_idx, "first": target_idx,
                                           "weapon": weapon_idx, "valid": valid}
                    self._combat_log_add(
                        f"Cleave — click a highlighted creature within 5 ft of {tgt_name} "
                        f"(Esc to cancel).")
                    self._flush_combat_log()
            self._update_attack_overlay()
        options = [
            ("Cleave: extra attack (no ability mod)", lambda: _apply(True)),
            ("Skip Cleave", lambda: _apply(False)),
        ]
        px, py = self._agent_screen_pos(atk_idx)
        self.context_menu.show((px, py), options, self.screen.get_size())

    def _cancel_cleave(self):
        """Esc out of a pending Cleave second-target pick. Refunds the once-per-turn use so the
        player can still Cleave on a later attack this turn."""
        info = self.pending_cleave
        self.pending_cleave = None
        if not info:
            return
        c = self.combat.get_agent_conditions(self.bm, info["attacker"])
        c.cleave_used_this_turn = False
        self.combat.set_agent_conditions(self.bm, info["attacker"], c)
        self._combat_log_add("Cleave cancelled.")
        self._flush_combat_log()
        self._update_attack_overlay()

    def _resolve_cleave(self, second_target: int):
        """Resolve a pending Cleave attack against the clicked 2nd creature. One weapon attack with
        no positive ability modifier on damage. The click must be one of the highlighted legal
        targets (within 5 ft of the first AND within reach); a stray click re-arms rather than
        wasting the Cleave. No action/bonus is consumed."""
        info = self.pending_cleave
        self.pending_cleave = None
        if not info:
            return
        atk, first, wi = info["attacker"], info["first"], info["weapon"]
        valid = info.get("valid")
        if valid is None:
            valid = self._cleave_valid_targets(atk, first, wi)
        agents = self.bm.placed_agents
        if not (0 <= second_target < len(agents)):
            self.pending_cleave = info  # off-map click — keep waiting
            return
        if second_target not in valid:
            self._combat_log_add(
                "Cleave: pick a highlighted creature within 5 ft of the first target "
                "and within your reach.")
            self._flush_combat_log()
            self.pending_cleave = info  # re-arm so a misclick doesn't waste the Cleave
            return

        action = rpg.Attack(atk, second_target, wi)
        action.no_ability_damage = True
        # FLAG: stays on execute_action (the auto Shield path) by design — a Cleave is itself a
        # rider-spawned attack, so routing it through begin_attack would open a Shield window during
        # another reaction (reaction-during-reaction), which the engine has no decision stack for yet.
        # Move to begin_attack once that stack lands.
        result = self.combat.execute_action(self.bm, action)
        self._flush_combat_log()

        atk_name = agents[atk].name if atk < len(agents) else "?"
        tgt_name = agents[second_target].name
        if not result.valid:
            self._combat_log_add(f"Cleave: {tgt_name} is out of reach.")
        elif result.hit:
            dmg_parts = self._get_damage_type_names(result.magic_damage_types, result.physical_damage_types)
            dmg_type_str = "/".join(dmg_parts) if dmg_parts else "untyped"
            self._combat_log_add(
                f"Cleave {atk_name}→{tgt_name}: HIT {result.total_damage}"
                f"{self._damage_breakdown_str(result)} {dmg_type_str}"
                f"{' — DOWN' if result.target_down else ''}")
            self._spawn_flash(second_target, f"Hit ({result.total_damage})",
                              FLASH_CRIT if result.critical else FLASH_GOOD)
            if result.target_down:
                self._drop_concentration_for_agent(second_target)
        else:
            self._combat_log_add(
                f"Cleave {atk_name}→{tgt_name}: miss (roll {result.total_roll} vs AC {result.target_ac})")
            self._spawn_flash(second_target, "Miss", FLASH_BAD)
        self._flush_combat_log()
        self._update_attack_overlay()

    def _gwm_heavy_weapon_idx(self, atk_idx: int) -> int:
        """Index of the agent's equipped Heavy melee (or thrown) weapon — the one a GWM Hew bonus
        attack is made with. Returns the first match, or -1 if none is equipped."""
        weapons = self.combat.get_agent_weapons(self.bm, atk_idx)
        for i, w in enumerate(weapons):
            if w.heavy and (w.type == rpg.WeaponType.Melee or w.thrown):
                return i
        return -1

    def _start_gwm_hew(self, atk_idx: int):
        """Great Weapon Master — Hew: after a Critical Hit or a kill with a Heavy weapon (flagged in
        C++ as gwm_hew_available), make one attack with that weapon as a Bonus Action. Driven by the
        standalone bonus-action button rather than an on-hit popup, so it no longer competes with the
        weapon-mastery on-hit riders (Cleave/Topple/Push) that resolve on the triggering hit. Routes
        through the shared extra-attack flow (which spends the bonus action) and clears the flag."""
        c = self.combat.get_agent_conditions(self.bm, atk_idx)
        if not c.gwm_hew_available:
            return
        if self.bonus_used:
            self._combat_log_add("Hew: bonus action already used.")
            self._flush_combat_log()
            return
        weapon_idx = self._gwm_heavy_weapon_idx(atk_idx)
        if weapon_idx < 0:
            self._combat_log_add("Hew: no Heavy weapon equipped.")
            self._flush_combat_log()
            return
        c.gwm_hew_available = False
        self.combat.set_agent_conditions(self.bm, atk_idx, c)
        self._start_extra_attack(weapon_idx=weapon_idx, offhand=False,
                                 label="Great Weapon Master: Hew")
        self._update_attack_overlay()

    def _offer_sudden_strike(self, atk_idx, target_idx, atk_name, tgt_name, result, atk_msg, weapon_idx):
        """Stalker's Flurry — Sudden Strike (Gloom Stalker L11): immediately after a Dreadful Strike
        hit, optionally make one FREE additional attack with the same weapon against a creature within
        5 ft of the target. Routes through the shared extra-attack flow with slot="action" so it does
        NOT consume the bonus action (it's a free attack granted by the feature). Clearing
        sudden_strike_available stops a re-offer.

        v1 sequencing: like GWM Hew, accepting forgoes any remaining Attack-action attacks (the extra
        attack takes over the pending sequence). The "within 5 ft of the target" constraint is left to
        the player's target click (noted in the prompt). Mass Fear (the alternative L11 effect) is
        deferred — see known_limitations.md."""
        def _apply(do):
            self._combat_log_add(atk_msg)
            c = self.combat.get_agent_conditions(self.bm, atk_idx)
            c.sudden_strike_available = False
            self.combat.set_agent_conditions(self.bm, atk_idx, c)
            self._flush_combat_log()
            if do:
                # Forgo any leftover action attacks so the free Sudden Strike sets up cleanly.
                self.attacks_remaining = 0
                self._attack_sequence_slot = ""
                self.pending_attack_slot = ""
                self._start_extra_attack(weapon_idx=weapon_idx, offhand=False, slot="action",
                                         label="Stalker's Flurry: Sudden Strike (target within 5 ft)")
            self._update_attack_overlay()
        options = [
            ("Sudden Strike: free extra attack", lambda: _apply(True)),
            ("Skip Sudden Strike", lambda: _apply(False)),
        ]
        px, py = self._agent_screen_pos(atk_idx)
        self.context_menu.show((px, py), options, self.screen.get_size())

    def _offer_divine_strike(self, atk_idx, target_idx, atk_name, tgt_name, result, atk_msg, on_done=None):
        """After a qualifying weapon hit, offer Cleric Divine Strike (Radiant or Necrotic).
        Mirrors _offer_brutal_strike; the extra die is applied in C++ via apply_divine_strike_effect.
        When on_done is set (a pending weapon-Mastery rider), it is invoked instead of refreshing the
        overlay, chaining the Mastery prompt after this one."""
        def _apply(radiant):
            if radiant is not None:
                self.combat.apply_divine_strike_effect(self.bm, atk_idx, target_idx, radiant, result)
                dmg_parts = self._get_damage_type_names(result.magic_damage_types, result.physical_damage_types)
                dmg_type_str = "/".join(dmg_parts) if dmg_parts else "untyped"
                self._combat_log_add(
                    f"{atk_name}→{tgt_name}: HIT {result.total_damage}{self._damage_breakdown_str(result)} "
                    f"{dmg_type_str}{' CRIT!' if result.critical else ''}{' — DOWN' if result.target_down else ''}")
            else:
                self._combat_log_add(atk_msg)
            self._flush_combat_log()
            if on_done:
                on_done()
            else:
                self._update_attack_overlay()
        options = [
            ("Divine Strike: Radiant", lambda: _apply(True)),
            ("Divine Strike: Necrotic", lambda: _apply(False)),
            ("Skip Divine Strike", lambda: _apply(None)),
        ]
        px, py = self._agent_screen_pos(atk_idx)
        self.context_menu.show((px, py), options, self.screen.get_size())

