    def _resolve_lay_on_hands(self, target_idx: int):
        """Paladin Lay on Hands: spend from pool, heal target."""
        self.pending_lay_on_hands = False
        healer_idx = self._current_agent_idx()
        if not (0 <= healer_idx < len(self.bm.placed_agents)):
            return
        if not (0 <= target_idx < len(self.bm.placed_agents)):
            return

        # Check healer has Lay on Hands
        healer_stats = self.combat.get_agent_stats(self.bm, healer_idx)
        loh = healer_stats.get_resource("Lay on Hands")
        if not (loh and loh.current > 0):
            self._combat_log_add(f"{self.bm.placed_agents[healer_idx].name}: Lay on Hands pool is empty.")
            return

        # Determine max healable
        target_stats = self.combat.get_agent_stats(self.bm, target_idx)
        heal_needed = target_stats.hp_max - target_stats.hp_cur
        max_healing = min(loh.current, heal_needed)

        # For now, heal the full amount (can add a dialog for partial healing later)
        healing = max_healing
        if healing <= 0:
            self._combat_log_add(f"{self.bm.placed_agents[target_idx].name}: Already at full HP.")
            return

        # Call C++ lay_on_hands method
        actual_healed = self.combat.lay_on_hands(self.bm, healer_idx, target_idx, healing)
        if actual_healed <= 0:
            self._combat_log_add(f"Lay on Hands failed (pool error).")
            return

        # Fetch updated stats for logging
        healer_stats = self.combat.get_agent_stats(self.bm, healer_idx)
        loh = healer_stats.get_resource("Lay on Hands")
        pool_remaining = loh.current if loh else 0
        tgt_name = self.bm.placed_agents[target_idx].name
        healer_name = self.bm.placed_agents[healer_idx].name
        self._combat_log_add(
            f"{healer_name}: Lay on Hands restores {actual_healed} HP to {tgt_name} ({pool_remaining} pool remaining).")
        self.action_used = True

    def _resolve_bastion_of_law(self, target_idx: int):
        """Clockwork Sorcerer L6 Bastion of Law: spend the chosen Sorcery Points (1-5) to ward the
        clicked target (self or a creature within 30 ft) with a pre-rolled (sp)d8 absorption pool."""
        self.pending_bastion_of_law = False
        sp = self.pending_bastion_sp
        self.pending_bastion_sp = 0
        caster_idx = self._current_agent_idx()
        if not (0 <= caster_idx < len(self.bm.placed_agents)):
            return
        if not (0 <= target_idx < len(self.bm.placed_agents)):
            return
        ward = self.combat.activate_bastion_of_law(self.bm, caster_idx, target_idx, sp)
        if ward >= 0:
            self.action_used = True  # Bastion of Law is a Magic Action
        else:
            self._combat_log_add("Bastion of Law: not available (range / Sorcery Points / subclass/level)")
        self._flush_combat_log()
        self._update_attack_overlay()

    def _resolve_hand_of_healing(self, target_idx: int):
        """Monk Warrior of Mercy Hand of Healing: spend a bonus action + 1 Focus Point to heal the
        clicked target (Martial Arts die + WIS). At L6 (Physician's Touch) it also ends a condition."""
        self.pending_hand_of_healing = False
        healer_idx = self._current_agent_idx()
        if not (0 <= healer_idx < len(self.bm.placed_agents)):
            return
        if not (0 <= target_idx < len(self.bm.placed_agents)):
            return

        res = self.combat.hand_of_healing(self.bm, healer_idx, target_idx)
        if not res.valid:
            self._combat_log_add(f"{self.bm.placed_agents[healer_idx].name}: Hand of Healing unavailable.")
            return

        healer_name = self.bm.placed_agents[healer_idx].name
        tgt_name = self.bm.placed_agents[target_idx].name
        msg = f"{healer_name}: Hand of Healing restores {res.amount_healed} HP to {tgt_name}"
        if res.condition_cleared:
            msg += f" and ends {res.cleared_condition}"
        self._combat_log_add(msg + ".")
        self.bonus_used = True
        self._update_attack_overlay()

    @staticmethod
    def _item_menu_dice(it) -> str:
        """'2d4+2' for a potion, '2d6 Acid' for a thrown flask, 'Restrained' for a Net —
        whatever the DM is actually picking the item by."""
        if it.type == rpg.ItemType.Thrown:
            if it.damage.num_dice > 0:
                dice = f"{it.damage.num_dice}d{it.damage.die_size} {it.damage.type.name}"
                return f"{dice}, {it.condition_applied}" if it.condition_applied else dice
            return it.condition_applied or "no damage"
        return f"{it.healing.num_dice}d{it.healing.die_size}+{it.healing.bonus}"

    def _can_replace_attack(self, idx: int) -> bool:
        """True if this actor still has a weapon attack a thrown item could replace — either one
        left in an Attack action already under way, or an unspent Attack action to start."""
        if self._attack_sequence_slot == "bonus":
            return False                      # finish the bonus-action attacks first
        if self._attack_sequence_slot == "action" and self.attacks_remaining > 0:
            return True
        return not self.action_used

    def _consume_attack_replacement(self, user_idx: int):
        """Charge a thrown item to the Attack action: it "replaces one of your attacks", so it
        spends one swing out of the attack budget — seeding a fresh Attack action if the actor had
        not started one. Mirrors _consume_cast_slot's War Magic branch, including the disarm that
        lets the player move between attacks and resume with the standing "⚔ Attack (N)" button."""
        if self._attack_sequence_slot != "action" or self.attacks_remaining <= 0:
            stats = self.combat.get_agent_stats(self.bm, user_idx)
            self.attacks_remaining     = max(1, stats.num_attacks)
            self._attack_sequence_slot = "action"

        # The Attack action itself is spent the moment it is taken — exactly as _finish_attack marks
        # it on the first swing. Any swings still owed stay live through mid_sequence_action, which
        # keeps the standing "⚔ Attack (N)" button (and its handler) working while action_used is set.
        self.attacks_remaining -= 1
        self.action_used = True
        if self.attacks_remaining > 0:
            self.pending_attack_slot = ""
            rem = self.attacks_remaining
            nm  = self.bm.placed_agents[user_idx].name
            self._combat_log_add(
                f"{nm}: {rem} attack{'s' if rem != 1 else ''} remaining — "
                f"move if you wish, then click Attack to continue.")
        else:
            self._attack_sequence_slot = ""

    def _show_use_item_menu(self, pos):
        """Pop the current actor's inventory: pick which carried item to use, then click a target.
        Items the actor can no longer pay for this turn (the Bonus Action is gone, or there is no
        attack left for a thrown flask to replace) are left out of the menu."""
        idx = self._current_agent_idx()
        if not (0 <= idx < len(self.bm.placed_agents)):
            return
        items = self.combat.get_agent_items(self.bm, idx)
        if not items:
            self._combat_log_add(f"{self.bm.placed_agents[idx].name} is carrying no items.")
            return

        def _affordable(it) -> bool:
            if it.action_type == rpg.ItemAction.AttackReplacement:
                return self._can_replace_attack(idx)
            if it.action_type == rpg.ItemAction.BonusAction:
                return not self.bonus_used
            if it.action_type == rpg.ItemAction.Action:
                return not self.action_used
            return True

        def _arm(slot):
            self.pending_use_item = slot
            it = items[slot]
            if it.type == rpg.ItemType.Thrown:
                prompt = f"Click a creature within {it.range} ft to throw {it.name}"
            else:
                where = "yourself" if it.range <= 0 else f"yourself or a creature within {it.range} ft"
                prompt = f"Click {where} to use {it.name}"
            # self.hint is never rendered anywhere, so the target prompt has to go to the combat
            # log or the player is left with no direction at all after picking an item.
            self.hint = prompt
            self._combat_log_add(prompt + ".")

        opts = []
        for slot, it in enumerate(items):
            if not _affordable(it):
                continue
            cost = " — replaces an attack" if it.action_type == rpg.ItemAction.AttackReplacement else ""
            opts.append((f"{it.name} (x{it.quantity}, {self._item_menu_dice(it)}){cost}",
                         (lambda s=slot: _arm(s))))
        if not opts:
            self._combat_log_add(
                f"{self.bm.placed_agents[idx].name} has nothing left to spend on an item this turn.")
            return
        self.context_menu.show(pos, opts, self.screen.get_size())

    def _resolve_use_item(self, target_idx: int):
        """Use the armed inventory slot on the clicked target (which may be the user itself).
        The engine owns the rules — range, the heal/save rolls, the condition riders, and spending
        the charge — so a rejected use (out of reach, no bonus action left) costs nothing. The
        action economy is charged here, on the GUI's budgets."""
        slot = self.pending_use_item
        self.pending_use_item = -1
        user_idx = self._current_agent_idx()
        if not (0 <= user_idx < len(self.bm.placed_agents)):
            return
        if not (0 <= target_idx < len(self.bm.placed_agents)):
            return

        items = self.combat.get_agent_items(self.bm, user_idx)
        if not (0 <= slot < len(items)):
            return
        item     = items[slot]
        is_throw = (item.action_type == rpg.ItemAction.AttackReplacement)

        # A thrown flask replaces one of the Attack action's swings, so make sure there IS one to
        # replace before the engine spends the flask.
        if is_throw and not self._can_replace_attack(user_idx):
            self._combat_log_add(
                f"{self.bm.placed_agents[user_idx].name}: no attack left to replace "
                f"(a thrown {item.name} costs one attack of the Attack action).")
            self._update_attack_overlay()
            return

        # Healing is clamped to the target's max HP, so a potion drunk at full health rolls its
        # dice, restores nothing, and still burns the charge and the Bonus Action. Refuse it here
        # rather than let the engine silently eat it ("regains 0 HP").
        if item.type == rpg.ItemType.Heal:
            tgt = self.combat.get_agent_stats(self.bm, target_idx)
            if tgt.hp_cur >= tgt.hp_max - tgt.available_hit_points:
                self._combat_log_add(
                    f"{self.bm.placed_agents[target_idx].name} is already at full HP — "
                    f"{item.name} not used.")
                self._update_attack_overlay()
                return

        res = self.combat.use_item(self.bm, user_idx, slot, target_idx)
        if not res.valid:
            self._combat_log_add(
                f"{self.bm.placed_agents[user_idx].name}: can't use that item "
                f"(out of reach, no bonus action left, or none carried).")
            self._update_attack_overlay()
            return

        # The engine already narrates the use (the drink and the HP regained; a throw's save roll,
        # damage and condition), so just flush its lines — re-stating them here printed every use
        # twice. Only the charge count is the GUI's to report.
        self._flush_combat_log()
        if res.consumed:
            self._combat_log_add(
                f"{self.bm.placed_agents[user_idx].name}: that was the last {res.item_name}.")

        if is_throw:
            self._consume_attack_replacement(user_idx)
        elif item.action_type == rpg.ItemAction.Action:
            self.action_used = True
        elif item.action_type == rpg.ItemAction.BonusAction:
            self.bonus_used = True
        self._update_attack_overlay()

    def _resolve_extinguish(self):
        """Put out a Burning actor: an action to drop Prone and roll on the ground."""
        idx = self._current_agent_idx()
        if not (0 <= idx < len(self.bm.placed_agents)):
            return
        if not self.combat.extinguish_burning(self.bm, idx):
            return
        self._combat_log_add(
            f"{self.bm.placed_agents[idx].name} drops and rolls, putting out the flames "
            f"(now Prone, no longer Burning).")
        self._flush_combat_log()
        self.action_used = True
        self._update_attack_overlay()

    def _netted_within_reach(self, actor_idx: int) -> list:
        """Netted creatures this actor could cut loose: itself, plus anything within 5 ft."""
        out = []
        for i in range(len(self.bm.placed_agents)):
            if not self.combat.get_agent_conditions(self.bm, i).netted:
                continue
            if i == actor_idx or 0 <= self._footprint_dist_ft(actor_idx, i) <= 5:
                out.append(i)
        return out

    def _begin_escape_net(self):
        """Free from Net: cut yourself loose right away, or arm a click for a netted neighbour."""
        idx = self._current_agent_idx()
        if not (0 <= idx < len(self.bm.placed_agents)):
            return
        freeable = self._netted_within_reach(idx)
        if not freeable:
            return                       # nothing tangled here (a stale button rect)
        if idx in freeable:
            self._resolve_escape_net(idx)          # cut yourself loose
        elif len(freeable) == 1:
            self._resolve_escape_net(freeable[0])  # only one neighbour to free — no click needed
        else:
            self.pending_escape_net = True
            self.hint = "Click the netted creature to free (within 5 ft)"

    def _resolve_escape_net(self, target_idx: int):
        """Free a netted creature (self, or one within 5 ft) with a DC 10 STR check — an action."""
        self.pending_escape_net = False
        actor_idx = self._current_agent_idx()
        if not (0 <= actor_idx < len(self.bm.placed_agents)):
            return
        if not (0 <= target_idx < len(self.bm.placed_agents)):
            return

        res = self.combat.escape_net(self.bm, actor_idx, target_idx)
        if not res.valid:
            self._combat_log_add(
                f"{self.bm.placed_agents[actor_idx].name}: can't free that creature "
                f"(it is not netted, or it is out of reach).")
            self._update_attack_overlay()
            return

        who = "itself" if target_idx == actor_idx else self.bm.placed_agents[target_idx].name
        self._combat_log_add(
            f"{self.bm.placed_agents[actor_idx].name}: STR check {res.total} vs DC {res.dc} to free "
            f"{who} from the Net — {'FREED' if res.freed else 'still tangled'}.")
        self._flush_combat_log()
        self.action_used = True
        self._update_attack_overlay()

    def _resolve_grant_inspiration(self, target_idx: int):
        """Bard Grant Inspiration (bonus action): spend a Bardic Inspiration use to give
        an ally a Bardic Inspiration die of the bard's current size."""
        self.pending_grant_inspiration = False
        bard_idx = self._current_agent_idx()
        if not (0 <= bard_idx < len(self.bm.placed_agents)):
            return
        if not (0 <= target_idx < len(self.bm.placed_agents)):
            return
        if target_idx == bard_idx:
            self._combat_log_add("Bardic Inspiration must be granted to another creature.")
            return

        bard_stats = self.combat.get_agent_stats(self.bm, bard_idx)
        bi = bard_stats.get_resource("Bardic Inspiration")
        if not (bi and bi.current > 0):
            self._combat_log_add(f"{self.bm.placed_agents[bard_idx].name}: no Bardic Inspiration uses left.")
            return

        die = bard_stats.bardic_inspiration_die_size
        if not self.combat.spend_resource(self.bm, bard_idx, "Bardic Inspiration", 1):
            self._combat_log_add("Grant Inspiration failed (resource error).")
            return
        self.combat.grant_bardic_die(self.bm, target_idx, die)
        self._flush_combat_log()

        bi = self.combat.get_agent_stats(self.bm, bard_idx).get_resource("Bardic Inspiration")
        remaining = bi.current if bi else 0
        bard_name = self.bm.placed_agents[bard_idx].name
        tgt_name = self.bm.placed_agents[target_idx].name
        self._combat_log_add(
            f"{bard_name}: grants a Bardic Inspiration d{die} to {tgt_name} ({remaining} uses left).")
        self.bonus_used = True

    def _use_inspiration_die(self, agent_idx: int):
        """Spend a held Bardic Inspiration die (free): primes a +die bonus on the holder's
        next d20 Test."""
        stats = self.combat.get_agent_stats(self.bm, agent_idx)
        if stats.bardic_inspiration_die <= 0:
            self._combat_log_add(f"{self.bm.placed_agents[agent_idx].name}: no Bardic Inspiration die held.")
            return
        value = self.combat.use_bardic_die(self.bm, agent_idx)
        self._flush_combat_log()
        name = self.bm.placed_agents[agent_idx].name
        if value > 0:
            self._combat_log_add(f"{name}: Bardic Inspiration (+{value}) will apply to the next D20 Test.")

    def _mantle_cha_cap(self, bard_idx: int) -> int:
        """Max recipients for Mantle of Inspiration = the bard's CHA modifier (min 1)."""
        stats = self.combat.get_agent_stats(self.bm, bard_idx)
        return max(1, (stats.cha - 10) // 2)

    def _start_mantle(self, bard_idx: int):
        """College of Glamour Mantle of Inspiration (bonus action): begin collecting up to
        CHA-mod other creatures within 60 ft. Enter confirms / Esc cancels."""
        stats = self.combat.get_agent_stats(self.bm, bard_idx)
        bi = stats.get_resource("Bardic Inspiration")
        if not (bi and bi.current > 0):
            self._combat_log_add(f"{self.bm.placed_agents[bard_idx].name}: no Bardic Inspiration uses left.")
            self._flush_combat_log()
            return
        self.pending_mantle_active  = True
        self.pending_mantle_targets = []
        cap = self._mantle_cha_cap(bard_idx)
        self._combat_log_add(
            f"Mantle of Inspiration — click up to {cap} creature(s) within 60 ft, then Enter "
            f"(Esc cancels).")
        self._flush_combat_log()

    def _mantle_add_target(self, hit: int):
        """Add a clicked creature to the Mantle recipient list (within 60 ft, not the bard,
        not already chosen, capped to CHA mod)."""
        bard_idx = self._current_agent_idx()
        agents = self.bm.placed_agents
        if not (0 <= hit < len(agents)) or not (0 <= bard_idx < len(agents)):
            return
        if hit == bard_idx:
            self._combat_log_add("Mantle of Inspiration affects other creatures, not yourself.")
            self._flush_combat_log()
            return
        if hit in self.pending_mantle_targets:
            return
        cap = self._mantle_cha_cap(bard_idx)
        if len(self.pending_mantle_targets) >= cap:
            self._combat_log_add(f"Mantle of Inspiration: already chose {cap} creature(s) — Enter to confirm.")
            self._flush_combat_log()
            return
        if self._footprint_dist_ft(bard_idx, hit) > 60:
            self._combat_log_add("Mantle of Inspiration: that creature is more than 60 ft away.")
            self._flush_combat_log()
            return
        self.pending_mantle_targets.append(hit)
        self._combat_log_add(
            f"  Mantle target {len(self.pending_mantle_targets)}/{cap} → {agents[hit].name}")
        self._flush_combat_log()

    def _finalize_mantle(self):
        """Resolve Mantle of Inspiration on the collected recipients."""
        bard_idx = self._current_agent_idx()
        targets  = list(self.pending_mantle_targets)
        self.pending_mantle_active  = False
        self.pending_mantle_targets = []
        if not (0 <= bard_idx < len(self.bm.placed_agents)) or not targets:
            self._combat_log_add("Mantle of Inspiration cancelled (no targets).")
            self._flush_combat_log()
            return
        thp = self.combat.apply_mantle_of_inspiration(self.bm, bard_idx, targets)
        self._flush_combat_log()
        if thp > 0:
            self.bonus_used = True
            bi = self.combat.get_agent_stats(self.bm, bard_idx).get_resource("Bardic Inspiration")
            remaining = bi.current if bi else 0
            self._combat_log_add(
                f"{self.bm.placed_agents[bard_idx].name}: Mantle of Inspiration grants {thp} "
                f"Temporary HP to {len(targets)} creature(s) ({remaining} uses left).")
        self._update_attack_overlay()

    def _cancel_mantle(self):
        """Esc out of Mantle of Inspiration without spending the Bardic Inspiration use."""
        self.pending_mantle_active  = False
        self.pending_mantle_targets = []
        self._combat_log_add("Mantle of Inspiration cancelled.")
        self._flush_combat_log()

    def _start_mantle_majesty(self, bard_idx: int):
        """College of Glamour Mantle of Majesty (bonus action). The FIRST use spends the once/long-rest
        resource, opens the 1-minute Concentration window, and casts Command for free; while the window
        is already active, the button just re-casts Command for free (bonus action, no resource).

        Flow: pick the Command word (ElementPickerDialog), then — only on confirm, so an Esc wastes
        nothing — activate the window if needed and set up a free single-target Command cast."""
        if self.bonus_used:
            self._combat_log_add("Bonus action already used this turn.")
            self._flush_combat_log()
            return
        stats = self.combat.get_agent_stats(self.bm, bard_idx)
        if not (stats.bard_subclass == rpg.BardCollege.Glamour and stats.char_level >= 6):
            return
        window_active = stats.mantle_majesty_turns > 0
        maj = stats.get_resource("Mantle of Majesty")
        if not window_active and not (maj and maj.current > 0):
            self._combat_log_add(
                f"{self.bm.placed_agents[bard_idx].name}: no Mantle of Majesty use left.")
            self._flush_combat_log()
            return
        spells = self.combat.get_agent_spells(self.bm, bard_idx)
        command_idx = next((i for i, sp in enumerate(spells) if sp.name == "Command"), -1)
        if command_idx < 0:
            self._combat_log_add("Mantle of Majesty: Command spell not prepared.")
            self._flush_combat_log()
            return

        def _on_word(chosen, bard_idx=bard_idx, command_idx=command_idx, window_active=window_active):
            word = chosen[0] if chosen else 3   # default Halt
            if not window_active:
                if not self.combat.activate_mantle_of_majesty(self.bm, bard_idx):
                    self._flush_combat_log()
                    return
                self._flush_combat_log()
            # Free single-target Command cast (bonus action, no slot). The bonus action is charged in
            # _consume_cast_slot; the slot is skipped in C++ via SpellAction.free_cast.
            self.pending_spell_slot         = "bonus"
            self.pending_spell_idx          = command_idx
            self.pending_spell_slot_level   = 0
            self.pending_spell_is_aoe       = False
            self.pending_spell_targets      = []
            self.pending_spell_num_targets  = 0
            self.pending_spell_damage_type  = -1
            self.pending_spell_free_cast    = True
            self.pending_spell_command_word = word
            self.pending_spell_curse_choice = -1
            self.pending_chromatic_active   = False
            self.pending_chromatic_chain    = []
            word_name = next((lbl for lbl, val in COMMAND_WORD_OPTIONS if val == word), "?")
            self._combat_log_add(
                f"Mantle of Majesty: casting Command ({word_name}) — click a target within 60 ft.")
            self.hint = f"Command ({word_name}): click a target within 60 ft"
            self._flush_combat_log()

        self._element_dialog.show(_on_word, COMMAND_WORD_OPTIONS, current_values=None, multi=False,
                                  title="Command: choose a word")

    def _start_unbreakable_majesty(self, bard_idx: int):
        """College of Glamour Unbreakable Majesty (bonus action, L14+). Spend the once/long-rest resource
        to open a 1-minute Concentration window of "majestic presence": melee attacks against the bard
        trigger Psychic damage and a CHA save (no reaction). While the window is active the button is
        just a display (clicking does nothing, since the feature runs automatically)."""
        if self.bonus_used:
            self._combat_log_add("Bonus action already used this turn.")
            self._flush_combat_log()
            return
        stats = self.combat.get_agent_stats(self.bm, bard_idx)
        if not (stats.bard_subclass == rpg.BardCollege.Glamour and stats.char_level >= 14):
            return
        window_active = stats.majestic_presence_turns > 0
        if window_active:
            # Already active — button is just informational (the feature runs automatically)
            self._combat_log_add(f"{self.bm.placed_agents[bard_idx].name}'s majestic presence is already active.")
            self._flush_combat_log()
            return
        um = stats.get_resource("Unbreakable Majesty")
        if not (um and um.current > 0):
            self._combat_log_add(
                f"{self.bm.placed_agents[bard_idx].name}: no Unbreakable Majesty use left.")
            self._flush_combat_log()
            return
        if not self.combat.activate_unbreakable_majesty(self.bm, bard_idx):
            self._flush_combat_log()
            return
        self.bonus_used = True
        self._combat_log_add(f"{self.bm.placed_agents[bard_idx].name} takes on a majestic presence (Unbreakable Majesty).")
        self._flush_combat_log()

    def _set_fiendish_resilience(self, agent_idx: int, dmg_idx: int):
        """Fiend Warlock L10: set the chosen damage resistance (0.5x), clearing any prior choice."""
        if not (0 <= agent_idx < len(self.bm.placed_agents)):
            return
        stats = self.combat.get_agent_stats(self.bm, agent_idx)
        old = stats.fiendish_resilience_type
        if old >= 0:
            stats.set_magic_damage_multiplier(old, 1.0)  # clear previous selection
        stats.fiendish_resilience_type = dmg_idx
        stats.set_magic_damage_multiplier(dmg_idx, 0.5)
        self.combat.set_agent_stats(self.bm, agent_idx, stats)
        self._combat_log_add(
            f"{self.bm.placed_agents[agent_idx].name}: Fiendish Resilience set (damage type {dmg_idx}, resistance).")

    def _start_shove(self, shove_type: str):
        """Start a shove action (requires target selection)."""
        if self.bonus_used:
            return
        self.pending_shove_slot = "bonus"
        self.pending_shove_type = shove_type
        hint = f"shove and {'knock prone' if shove_type == 'prone' else 'push 5ft'}"
        self._combat_log_add(f"Click a target to {hint}.")

    def _start_telekinetic_shove(self):
        """Telekinetic feat — Telekinetic Shove (bonus action, 30 ft, STR save or pushed 5 ft)."""
        if self.bonus_used:
            return
        self.pending_shove_slot = "bonus"
        self.pending_shove_type = "telekinetic"
        self._combat_log_add("Click a target within 30 ft to telekinetically shove (STR save or pushed 5 ft).")

    def _resolve_shove(self, target_idx: int):
        """Execute the pending shove action."""
        if not self.pending_shove_slot or not self.pending_shove_type:
            return

        atk_idx = self._current_agent_idx()
        if atk_idx < 0:
            self.pending_shove_slot = ""
            self.pending_shove_type = ""
            return

        # Telekinetic Shove is a STR-save shove at 30 ft (reuses the C++ Thunderwave knockback);
        # the ordinary push/prone shove is a contested Athletics check at 5 ft.
        if self.pending_shove_type == "telekinetic":
            result = self.combat.apply_telekinetic_shove(self.bm, atk_idx, target_idx)
            if result.valid:
                self._combat_log_add(result.log_message)
                if result.push_ft_applied > 0:
                    self._update_reach()
                    self._update_attack_overlay()
            else:
                self._combat_log_add(f"Telekinetic Shove failed: {result.log_message}")
            self.pending_shove_slot = ""
            self.pending_shove_type = ""
            self.bonus_used = True
            return

        # Create ShoveAction
        action = rpg.ShoveAction()
        action.attacker_idx = atk_idx
        action.target_idx = target_idx
        action.knock_prone = (self.pending_shove_type == "prone")

        # Execute shove
        result = self.combat.execute_shove(self.bm, action)

        # Log result
        if result.valid:
            self._combat_log_add(result.log_message)
            if result.push_ft_applied > 0 or result.knocked_prone:
                self._update_reach()
                self._update_attack_overlay()
        else:
            self._combat_log_add(f"Shove failed: {result.log_message}")

        # Mark bonus action as used
        self.pending_shove_slot = ""
        self.pending_shove_type = ""
        self.bonus_used = True

    # FLAG: Move to C++
    def _execute_grapple_escape(self):
        """Execute escape from grapple (bonus action, no target selection)."""
        if self.bonus_used:
            return

        agent_idx = self._current_agent_idx()
        if agent_idx < 0:
            return

        # Check if agent is actually grappled
        conds = self.combat.get_agent_conditions(self.bm, agent_idx)
        if not conds.grappled:
            self._combat_log_add("Not grappled!")
            return

        # Execute escape
        result = self.combat.execute_grapple_escape(self.bm, agent_idx)

        # Log result
        if result.valid:
            self._combat_log_add(result.log_message)
            if result.success:
                self._update_reach()
                self._update_attack_overlay()
        else:
            self._combat_log_add(f"Escape failed: {result.log_message}")

        # Mark bonus action as used
        self.bonus_used = True

    def _execute_grapple_drop(self):
        """Voluntarily drop all grapples initiated by the current agent (free action)."""
        agent_idx = self._current_agent_idx()
        if agent_idx < 0:
            return

        # Check if agent is grappling anyone
        agents = self.bm.placed_agents
        is_grappling = any(
            agents[i].conditions.grappler_idx == agent_idx and agents[i].conditions.grappled
            for i in range(len(agents))
        )
        if not is_grappling:
            self._combat_log_add("Not grappling anyone!")
            return

        # Drop all grapples
        self.combat.drop_grapples_by(self.bm, agent_idx)
        agent_name = agents[agent_idx].name if agent_idx < len(agents) else "Unknown"
        self._combat_log_add(f"{agent_name} releases all grappled targets.")
        self._update_reach()
        self._update_attack_overlay()

    def _on_spell_done(self, agent_idx: int, spells: list[dict]):
        cpp_spells = []
        for j, d in enumerate(spells):
            cpp_spells.append(_dict_to_spell(d))
            # Store all metadata for this spell (terrain, level, upcast)
            meta = {
                "terrain_effect": d.get("terrain_effect"),
                "hatch_pattern": d.get("hatch_pattern"),
                "terrain_color": d.get("terrain_color"),
                "level": d.get("level", 0),
                "upcast_dice_bonus": d.get("upcast_dice_bonus", 0),
            }
            self._spell_metadata[(agent_idx, j)] = meta
        self._grant_class_features(agent_idx, cpp_spells)
        self.combat.set_agent_spells(self.bm, agent_idx, cpp_spells)

    def _grant_class_features(self, agent_idx: int, cpp_spells: list):
        """Append always-prepared class features (Channel Divinity options, etc.) from
        classfeatures.json that match this agent's class and level, baking scaling dice
        from level. Mutates and returns cpp_spells; skips any already present by name."""
        if not self.all_class_features:
            return cpp_spells
        stats = self.combat.get_agent_stats(self.bm, agent_idx)
        class_name = stats.character_class.name
        level = stats.char_level
        existing = {sp.name for sp in cpp_spells}
        for feat in self.all_class_features:
            if feat.get("class") != class_name:
                continue
            if level < int(feat.get("min_level", 1)):
                continue
            # Subclass-gated features (e.g. Radiance of the Dawn, Nature's Wrath) only for the matching
            # subclass. Map each class to the Stats attribute that names its chosen subclass.
            sub = feat.get("subclass")
            if sub:
                agent_sub = {
                    "Cleric": stats.cleric_subclass.name,
                    "Paladin": stats.paladin_oath.name,
                }.get(class_name)
                if agent_sub != sub:
                    continue
            name = feat.get("name")
            if name in existing:
                continue
            sp = _dict_to_spell(feat)
            self._apply_feature_scaling(sp, feat, level, stats)
            cpp_spells.append(sp)
            existing.add(name)

        # Always-prepared divine domain spells (regular spells from spells.json).
        if class_name == "Cleric":
            domain_table = self._DOMAIN_SPELLS.get(stats.cleric_subclass.name, {})
            for min_lvl, names in domain_table.items():
                if level < min_lvl:
                    continue
                for name in names:
                    if name in existing:
                        continue
                    idx = self.spell_name_to_idx.get(name)
                    if idx is None:
                        continue  # not in spells.json — skip gracefully
                    cpp_spells.append(_dict_to_spell(self.all_spells[idx]))
                    existing.add(name)

        # Always-prepared Ranger subclass spells (regular spells from spells.json).
        if class_name == "Ranger":
            sub_table = self._RANGER_SUBCLASS_SPELLS.get(stats.ranger_subclass.name, {})
            for min_lvl, names in sub_table.items():
                if level < min_lvl:
                    continue
                for name in names:
                    if name in existing:
                        continue
                    idx = self.spell_name_to_idx.get(name)
                    if idx is None:
                        continue  # not in spells.json (e.g. Summon Fey) — skip gracefully
                    cpp_spells.append(_dict_to_spell(self.all_spells[idx]))
                    existing.add(name)

        # Always-prepared Bard college spells (regular spells from spells.json). Glamour L6 has
        # Command always prepared (cast for free via Mantle of Majesty).
        if class_name == "Bard":
            sub_table = self._BARD_SUBCLASS_SPELLS.get(stats.bard_subclass.name, {})
            for min_lvl, names in sub_table.items():
                if level < min_lvl:
                    continue
                for name in names:
                    if name in existing:
                        continue
                    idx = self.spell_name_to_idx.get(name)
                    if idx is None:
                        continue  # not in spells.json — skip gracefully
                    cpp_spells.append(_dict_to_spell(self.all_spells[idx]))
                    existing.add(name)

        # Sorcerer subclass always-prepared lists (Aberrant Mind Psionic Spells, Clockwork Soul
        # Clockwork Spells) — regular spells from spells.json, granted by subclass + level.
        if class_name == "Sorcerer":
            sub_table = self._SORCERER_SUBCLASS_SPELLS.get(stats.sorcerer_subclass.name, {})
            for min_lvl, names in sub_table.items():
                if level < min_lvl:
                    continue
                for name in names:
                    if name in existing:
                        continue
                    idx = self.spell_name_to_idx.get(name)
                    if idx is None:
                        continue  # not in spells.json — skip gracefully
                    cpp_spells.append(_dict_to_spell(self.all_spells[idx]))
                    existing.add(name)

        # Warlock patron always-prepared lists — regular spells from spells.json, granted by
        # subclass + Warlock level (2024 PHB). Uses WarlockSubclass.name as the key.
        if class_name == "Warlock":
            sub_table = self._WARLOCK_SUBCLASS_SPELLS.get(stats.warlock_subclass.name, {})
            for min_lvl, names in sub_table.items():
                if level < min_lvl:
                    continue
                for name in names:
                    if name in existing:
                        continue
                    idx = self.spell_name_to_idx.get(name)
                    if idx is None:
                        continue  # not in spells.json — skip gracefully
                    cpp_spells.append(_dict_to_spell(self.all_spells[idx]))
                    existing.add(name)

        # Paladin oath always-prepared spells — regular spells from spells.json, granted by
        # oath + Paladin level (2024 PHB). Uses PaladinOath.name as the key. Pure-utility oath
        # spells (e.g. Scrying, Commune with Nature) are intentionally omitted — see known_limitations.
        if class_name == "Paladin":
            sub_table = self._PALADIN_OATH_SPELLS.get(stats.paladin_oath.name, {})
            for min_lvl, names in sub_table.items():
                if level < min_lvl:
                    continue
                for name in names:
                    if name in existing:
                        continue
                    idx = self.spell_name_to_idx.get(name)
                    if idx is None:
                        continue  # not in spells.json — skip gracefully
                    cpp_spells.append(_dict_to_spell(self.all_spells[idx]))
                    existing.add(name)
        return cpp_spells

